-- 0034(2026-09-07):草本原料库首批 100 条。
--
-- 来源:botanical-100 工作流(选料 → 十路并行写 → 逐批审)。
-- 审稿抓到 16 处必须改(16 处已按给出的替换文本套用)、40 处建议改(36 处已套用)。
-- 典型问题:桑白皮部位写错(根 vs 根皮)、编造 40℃ 加速试验结论、
-- 编造固含区间、荷荷巴标控油、六支精油标舒缓、水解小麦蛋白欧盟身份写错。
-- 这一步是入库前的最后一道:不改直接进,这一库会带着编造上线。
--
-- 另外统一执行三条(不管审稿有没有提):functions 只留词表内的值;
-- 站内词表里没有的 claim_tag 一律留空;use_level 必须自带「非法规限值」;
-- 市场字段一律附「以最新官方文本为准」;CAS 空的写「未确认」。

INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('glycyrrhiza-glabra-root-extract','Glycyrrhiza Glabra Root Extract','name_zh 改为「光果甘草(根)提取物」;aliases 保留「甘草根提取物」并在 mechanism_zh 中补一句:「与乌拉尔甘草(Glycyrrhiza uralensis)对应的是另一条 INCI,物种不同、标示物与目录条目均不通用,选料时先确认拉丁名。」','光果甘草根提取物,甘草根萃取,Licorice Root Extract,Glycyrrhiza glabra','84775-66-6(对应 Glycyrrhiza glabra, ext. 的常见登记号;实际以供应商 COA 标注为准)','植物提取物','soothing,brightening,antioxidant,barrier','水溶性提取物主要含黄酮类与甘草酸(皂苷)类,脂溶性规格则以光果甘草中的疏水黄酮为主。配方中常用于泛红与刺激后舒缓方向,以及肤色不均方向的复配。要注意「甘草酸二钾」是单一化合物盐,与「甘草根提取物」不是同一件物料,价格、溶解方式与颜色都不同,报价和送样不能混用。','水溶性提取物 0.1–2%,脂溶性高含量规格 0.01–0.05%(公开配方学常见添加区间,非法规限值)','serum,essence,toner,lotion,cream,mask,gel,foam','4.5–6.5(甘草酸类在 pH 低于约 4 时易以游离酸形式析出)','1)与低 pH 体系冲突:甘草酸/甘草酸盐在 pH 降到 4 以下会转成溶解度很低的游离酸,和高浓度抗坏血酸精华(体系 pH 常在 3 附近)同锅,放置几天出现浑浊或白色絮状沉淀,过滤也回不来。2)与阳离子调理剂(聚季铵盐-7/10、西曲氯铵、山嵛基三甲基氯化铵)形成不溶复合物,洁面和护发体系表现为料体发浑、粘度明显掉、泡沫变粗。3)皂苷部分会干扰卡波姆中和体系的表观粘度,先加提取物再中和,粘度常比小样低一截。4)高浓度乙醇体系中黄酮类先溶后析,兑水稀释时出现雾状浑浊。5)与含铁的色粉、铁质设备接触会加深颜色。','提取物本体呈浅黄至棕黄色。pH 上到 7 以上颜色明显加深并向黄褐偏移;黄酮类见光遇氧缓慢氧化,长期光照下色相变深、气味往「药材味」走;80℃ 以上长时间保温同样加深颜色。常见防护做法:降温后加、配 0.05–0.1% EDTA 二钠或植酸做螯合、体系 pH 控在 4.5–6.0、用避光或深色内包,并做 45℃/3 个月与光照对照,验收标准写成色差上限而不是「无明显变化」。','作为化妆品原料属常规使用方向,需核对该原料的收录状态与使用部位,并按目标市场规则复核;以最新官方文本为准。','作为植物提取物属常规使用方向,需完成安全评估并复核该市场对植物提取物的限制清单;以最新官方文本为准。','属常规使用方向,按该市场化妆品监管框架与行业安全评估惯例复核;以最新官方文本为准。','日韩及东南亚对草本原料接受度高,属常规使用方向,需按各国原料目录与备案要求分别复核;以最新官方文本为准。','植物来源,通常可做 vegan;需确认提取溶剂与载体(部分规格用乙醇或丙二醇);清真需供应商出具证明。','mid','粉状规格必须先用少量甘油或丙二醇打浆分散再入水相,直接撒进水里会结块挂在桶壁上,实际投料量偏低。皂苷含量高的规格在搅拌下起泡明显,建议低转速、抽真空溶解,泡沫带进乳化会造成液位假高、计量不准、灌装装量不足。乳化体系一律降温到 45℃ 以下后加,不要随水相同煮。与卡波姆体系搭配时先中和到目标粘度、再加提取物,顺序反过来容易出现粘度回落。放大生产的主要坑是批间色差:不同产地、不同提取溶剂的批次色相肉眼可辨,量产前先比三批色卡并把色相范围写进内控。','soothing','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('scutellaria-baicalensis-root-extract','Scutellaria Baicalensis Root Extract','黄芩(根)提取物','黄芩根提取物,黄芩苷提取物,Baikal Skullcap Root Extract,Scutellaria baicalensis','未确认','植物提取物','antioxidant,soothing,barrier','该句改为:「也常出现在抗蓝光、晒后舒缓类概念的配方设计里。」','0.05–0.5%(公开配方学常见添加区间,非法规限值)','serum,essence,toner,lotion,cream,mask,gel','4.0–5.5(pH 上移颜色明显加深)','1)遇三价铁离子生成有色络合物,料体在几天内由浅黄转橄榄绿或黄褐——来源可能是硬水、磨损的铁质搅拌桨、含铁色粉,不一定是配方本身。2)与碱性原料(氨甲基丙醇、三乙醇胺、皂基高 pH 体系)接触当场变深黄至橙色,且不可逆。3)与阳离子表活及阳离子聚合物易絮凝。4)与过氧化物、过氧化苯甲酰等氧化型原料共存会褪色并可能产生异味。5)与锌盐、铜肽同锅有变色风险,这类组合必须单独做兼容性小试,不要靠经验判断。','黄色明显,是无色/浅色配方最容易翻车的一味。pH 每上升约一个单位颜色明显加深并趋于不可逆;见光后表面层先褐变,透明瓶装常最先在瓶肩出现色差;80℃ 以上长时间保温加速黄变。常见防护做法:pH 控在 4.0–5.5;必配螯合剂(EDTA 二钠 0.05–0.1%,或植酸/GLDA);全程 316L 不锈钢设备、禁止铁质工具;内包避光或加不透明外盒;稳定性做 45℃/3 个月加光照对照,验收标准写成色差上限。','作为化妆品原料属常规使用方向,需核对收录状态与使用部位并按目标市场规则复核;以最新官方文本为准。','属常规使用方向,需完成安全评估并复核该市场对植物提取物的限制清单;以最新官方文本为准。','属常规使用方向,按该市场化妆品监管框架与行业安全评估惯例复核;以最新官方文本为准。','日韩市场在抗氧化与舒缓类配方中使用普遍,属常规使用方向,需按各国原料目录分别复核;以最新官方文本为准。','植物来源,通常可做 vegan;需确认提取溶剂与稀释载体;清真需供应商出具证明。','mid','粉体在水中溶解度有限,建议先用丁二醇/丙二醇或含少量增溶剂的水相在 50–60℃ 溶清、过 200 目筛后再入主锅,否则未溶颗粒会在膏体里形成黄点——灯下检膏时这是客户最容易挑出来的缺陷。乳化体系降温到 45℃ 以下后加。加料顺序上必须先加螯合剂再加黄芩,顺序反了当场看不出差别,问题在货架期才暴露。换品种时产线要彻底清洗,黄芩残留会把下一锅白膏染成米黄色。透明水剂建议增加一道 0.45–1 μm 澄清过滤。','antioxidant','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('salvia-miltiorrhiza-root-extract','Salvia Miltiorrhiza Root Extract','丹参(根)提取物','丹参根提取物,紫丹参,红根,Danshen Root Extract,Salvia miltiorrhiza','未确认','植物提取物','antioxidant,soothing,oil-control','丹参有两条完全不同的成分线,采购必须先说清要哪一条:脂溶性的丹参酮类(丹参酮 IIA、隐丹参酮)呈橙红色,只溶于油相或醇/增溶体系;水溶性的丹酚酸类(丹酚酸 B、丹参素)呈深褐色,属多酚。两者的价格、检测标示物、溶解方式和成品颜色都不一样,常有客户拿着一份规格书问另一种料的问题。配方中丹参酮线多用于油性肌肤方向,丹酚酸线多用于抗氧化方向。','水溶性丹酚酸类 0.1–1%,脂溶性丹参酮类 0.01–0.2%(公开配方学常见添加区间,非法规限值)','serum,essence,cream,lotion,gel,oil,balm,mask','水溶性规格 3.5–6.0;脂溶性规格 4.0–7.0','1)丹酚酸类含邻二酚结构,遇铁/铜离子迅速生成深色络合物,料体可以一夜之间从棕色转向墨绿黑。2)pH 超过 7 时多酚氧化聚合,颜色急剧加深并可能出现沉淀。3)与过氧化物、次氯酸类、氧化型染发中间体不可共存。4)丹参酮类在含大量极性溶剂的水相中会重新析出结晶,与低极性酯类(IPM、辛酸/癸酸甘油三酯)相容,但与硅油相容性差,在硅弹体系里常出现橙色斑点。5)两条线与阳离子聚合物均可能絮凝。','两条线的失效方向相反,必须分开考察。丹参酮见光褪色明显,橙红色在透明瓶日照下几周内就淡化,是「同一批货颜色不一致」投诉的典型来源;丹酚酸则往深里走,持续褐变。两者都对氧敏感。常见防护做法:丹参酮走遮光包材、配生育酚、避免高温长保温;丹酚酸走低 pH、螯合剂、减少料体顶空并配水溶性抗氧化剂。务实的做法是承认「颜色会随货架期缓慢变化」,把可接受的色差范围提前写进规格书,而不是向客户承诺不变色。','作为化妆品原料属常规使用方向,需核对收录状态与使用部位并按目标市场规则复核;以最新官方文本为准。','属常规使用方向,需完成安全评估并复核该市场对植物提取物的限制清单;以最新官方文本为准。','属常规使用方向,按该市场化妆品监管框架与行业安全评估惯例复核;以最新官方文本为准。','在东亚草本线中使用较普遍,属常规使用方向,需按各国原料目录分别复核;以最新官方文本为准。','植物来源,通常可做 vegan;脂溶性规格常以植物油或醇作载体,需确认载体来源;清真需供应商出具证明。','mid','脂溶性规格多为油溶或醇溶浸膏,黏稠挂壁严重,过料时必须用同批油相把容器冲洗干净,否则实际投料量偏低、批间颜色差异肉眼可见。丹参酮要在油相 60–70℃ 完全溶清后再乳化,冷却后补加会析出结晶。水溶性粉末则相反,必须降温后加。同一产品线里两种规格务必用不同物料代码和不同货位,产线极易拿错。深色料对白膏上色能力强,0.1% 就能改变整体色相,试产阶段先做色相梯度再定投料量。清洗成本高,排产时放在浅色品之后。','antioxidant','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('angelica-sinensis-root-extract','Angelica Sinensis Root Extract','当归(根)提取物','当归根提取物,秦归,Dong Quai Root Extract,Angelica sinensis','未确认','植物提取物','soothing,conditioning,antioxidant','主要含阿魏酸类、藁本内酯等挥发性内酯以及多糖组分。配方中一方面参与抗氧化方向的复配,另一方面承担草本/汉方产品线的气味与调性,是少数会直接改变成品嗅觉印象的植提。要注意香豆素类(含呋喃香豆素)的含量随药材产地、部位与提取方式波动很大,不能按「当归就是光敏的」或「提取物没问题」任何一种笼统说法处理,必须要供应商给具体检测数据。','0.1–1%(公开配方学常见添加区间,非法规限值)','serum,essence,cream,lotion,balm,oil,mask','4.5–6.5','1)与香精相互作用最明显:藁本内酯等挥发性成分会把调好的香型往药材味方向拉,而且随货架期越来越重,调香必须在加完当归之后再定案。2)高浓度乙醇体系会把挥发性成分带到顶空,开盖瞬间气味冲。3)多酚伴生物遇铁离子变深。4)与阳离子体系可能絮凝。5)与其他含香豆素类的原料(某些柑橘类精油)叠加时,光敏相关风险必须放在一起评估,不能各算各的。','主要变化路径是颜色加深与气味漂移,而不是外观崩坏。见光遇氧后色深、香气走向变化;高温回流或长时间保温会显著损失挥发性成分,直接造成批间气味不一致——这是当归类产品最常见的退货理由。常见防护做法:降温后加、避光包材、控制瓶内顶空、必要时选用经过处理并附检测报告的低香豆素规格。面部免洗类产品应向供应商索取呋喃香豆素类含量数据并纳入安全评估;冲洗类与身体用产品条件相对宽松,但不等于可以跳过评估。','作为化妆品原料属常规使用方向,需核对收录状态与使用部位,并对香豆素类相关项做安全评估;以最新官方文本为准。','属常规使用方向,但该市场对光敏相关成分与致敏香味成分关注度较高,需提供含量数据并完成安全评估;以最新官方文本为准。','属常规使用方向,按该市场化妆品监管框架与行业安全评估惯例复核,重点关注光敏与致敏相关数据;以最新官方文本为准。','汉方与草本线接受度高,属常规使用方向,需按各国原料目录与安全评估要求分别复核;以最新官方文本为准。','植物来源,通常可做 vegan;需确认提取溶剂(乙醇规格在部分市场需额外说明);清真需供应商出具证明。','mid','浸膏类规格黏稠挂壁,建议先用丙二醇或丁二醇稀释成 1:4 母液再投料,既好计量也便于冲洗容器。一律降温到 40℃ 以下后加,高温投料会损失挥发性成分并让气味漂移。投料顺序上先加当归、搅拌分散均匀,再加香精做最后调整;反过来做,调香师定的头香会被当归吃掉。每批加完必须做感官确认并留样闻香,把可接受的气味范围写进内控——当归的批间气味差异是量产阶段最容易引发争议的一项,靠嘴上说「差不多」是不够的。','soothing','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('paeonia-lactiflora-root-extract','Paeonia Lactiflora Root Extract','白芍(根)提取物','芍药根提取物,杭白芍,White Peony Root Extract,Paeonia lactiflora','未确认','植物提取物','soothing,antioxidant,firming','主要含芍药苷类与含量较高的单宁(可水解与缩合鞣质)。在汉方复配里是高频配角,常用于舒缓与紧致方向的整体设计,同时对肤感有收敛性的贡献。单宁含量是它所有配伍问题的根源,选料时要向供应商索取单宁或总多酚的含量范围,而不是只看 INCI。','0.1–1%(公开配方学常见添加区间,非法规限值)','serum,essence,toner,lotion,cream,mask,gel','4.0–5.5','典型的「单看没事、一起就浑」。1)与蛋白及多肽类原料(水解胶原、水解小麦蛋白、各类信号肽/铜肽)形成不溶复合物,先是料体发浑,几天后底部出现絮状沉淀。2)与阳离子表活及阳离子聚合物(聚季铵盐-10/7、西曲氯铵)直接絮凝,护发体系里粘度会崩。3)与季铵盐类杀菌/防腐组分同样会相互失活,防腐挑战必须重做而不能沿用历史数据。4)与铁离子生成蓝黑色络合物,是深色斑点的经典来源。5)高浓度电解质共存时溶解度下降。','多酚在 pH 升高时氧化加快,料体由浅黄转褐;溶氧与光照都会加速。常见防护做法:pH 控在 4.0–5.5、配 EDTA 二钠或植酸、避免任何铁质接触、降低瓶内顶空、选避光包材。关键一点是稳定性考察不能只测单方——必须做「与体系内肽类/阳离子共存」的兼容测试,并加做 4℃ 与 45℃ 冷热循环,絮凝在常温放置里往往三个月都不显形,冷热循环两周就出来了。','作为化妆品原料属常规使用方向,需核对收录状态与使用部位并按目标市场规则复核;以最新官方文本为准。','属常规使用方向,需完成安全评估并复核该市场对植物提取物的限制清单;以最新官方文本为准。','属常规使用方向,按该市场化妆品监管框架与行业安全评估惯例复核;以最新官方文本为准。','汉方复配线使用普遍,属常规使用方向,需按各国原料目录分别复核;以最新官方文本为准。','植物来源,通常可做 vegan;需确认提取溶剂与载体;清真需供应商出具证明。','mid','和肽类、蛋白类同处一个配方时,两者要分别用不同溶剂稀释,加入时间点拉开:先加白芍分散均匀,再缓慢滴加肽液,一次性对冲最容易当场起絮。成品必须在 45℃ 与 4℃ 各放四周观察,冷热循环比常温更能暴露问题。清洁与护发体系里如果必须与阳离子共存,考虑改用增溶或包裹规格,或者把白芍放到不含阳离子的段位。溶解时避免长时间高剪切,带进去的气泡会让澄清度判断失真,量产时常因此误判为「浑浊」而返工。降温后加。','soothing','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('panax-ginseng-root-extract','Panax Ginseng Root Extract','人参(根)提取物','人参根提取物,高丽参,园参,Ginseng Root Extract,Panax ginseng','未确认','植物提取物','anti-aging,antioxidant,conditioning,firming','主要含人参皂苷(以 Rg1、Re、Rb1 等的组合为特征)及多糖、多酚伴生物。配方中常用于抗老与紧致方向的复配,也是东亚市场搜索量最大的草本词之一,采购几乎一定会问。皂苷本身有表面活性,这既是它在配方里的特点,也是它在车间里的麻烦来源。','0.1–2%(公开配方学常见添加区间,非法规限值);高皂苷标示规格通常用量更低','serum,essence,toner,cream,lotion,mask,gel,foam','4.5–6.0','1)人参皂苷是天然表面活性物质,会降低体系界面张力:在 W/O 或高油相体系里可能削弱乳化稳定性,放置后出现微量析油,这类问题常被误判为乳化剂选型错误。2)与阳离子调理剂形成复合物,清洁体系里泡沫质量下降、粘度掉。3)与高浓度电解质(高盐、氨基酸表活中和液)共存时溶解度下降。4)多酚伴生物遇铁离子变色。5)醇溶规格兑水稀释时容易出现瞬时浑浊(类似 ouzo 效应),做透明水剂前必须先做稀释预试。','颜色浅黄至棕黄,遇氧与 pH 升高时缓慢加深;高温长时间保温会使部分皂苷水解,外在表现是气味往焦糖或土腥方向转。微生物角度尤其要注意:含糖类与皂苷的提取物是很好的碳源,防腐挑战必须针对含人参的配方单独做,不能沿用同系列不含人参版本的历史数据——这是实际发生过的翻车路径。常见防护做法:pH 4.5–6.0、配螯合剂、避免长时间高温、防腐体系重新验证。','作为化妆品原料属常规使用方向,需核对收录状态与使用部位并按目标市场规则复核;以最新官方文本为准。','属常规使用方向,需完成安全评估并复核该市场对植物提取物的限制清单;以最新官方文本为准。','属常规使用方向,按该市场化妆品监管框架与行业安全评估惯例复核;以最新官方文本为准。','韩日市场认知度极高,属常规使用方向,需按各国原料目录与宣称管理规则分别复核;以最新官方文本为准。','植物来源,通常可做 vegan;需确认提取溶剂(部分规格用乙醇)与稀释载体;清真需供应商出具证明。','mid','起泡是这一味最大的工程问题。溶解时用低转速搅拌加抽真空,禁止用高剪切均质头直接打溶液;乳化后进入降温段再加,并保持真空状态。泡沫会带来三个连锁后果:液位假高导致计量不准、灌装装量不足、成品瓶内可见气泡被判外观不良。灌装前建议静置 4–12 小时或过一次脱气工序,并把脱泡时间写进工艺卡,不要留给现场凭经验判断。粉状规格先用甘油预分散。不同供应商标称的皂苷含量差异很大,报价与送样一定要按皂苷(或供应商指定标示物)含量对齐,只对 INCI 名必然对不上。','anti-aging','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('astragalus-membranaceus-root-extract','Astragalus Membranaceus Root Extract','黄芪(根)提取物','黄芪根提取物,北芪,绵芪,Astragalus Root Extract,Astragalus membranaceus','未确认','植物提取物','hydrating,barrier,soothing','改为:「多糖类具成膜性,配方中参与保湿方向的设计,同时对体系流变有实际贡献——这一点常被低估:它不只是活性物,也是半个增稠剂。」','0.2–2%(公开配方学常见添加区间,非法规限值)','serum,essence,toner,lotion,cream,mask,gel','4.5–7.0','该条改为:「高醇体系中多糖易析出白色絮状物,析出阈值随规格与分子量差异很大,高醇爽肤水必须先做梯度稀释预试或另选耐醇规格,不要按某个固定醇度判断。」','多糖在低 pH 加高温条件下缓慢水解,表现为货架期粘度下降,而且第一个月降得最明显——「客户收到的货比留样稀」多半是这个原因。含糖体系是微生物的良好营养源,防腐必须单独挑战。冻融时可能相分离。常见防护做法:体系 pH 不低于 4.5、避免 80℃ 以上长时间保温、粘度考察必做 45℃/1 个月与三次冻融循环,并把初始粘度做在规格中值偏上而不是压在下限。','作为化妆品原料属常规使用方向,需核对收录状态与使用部位并按目标市场规则复核;以最新官方文本为准。','属常规使用方向,需完成安全评估并复核该市场对植物提取物的限制清单;以最新官方文本为准。','属常规使用方向,按该市场化妆品监管框架与行业安全评估惯例复核;以最新官方文本为准。','草本保湿线使用普遍,属常规使用方向,需按各国原料目录分别复核;以最新官方文本为准。','植物来源,通常可做 vegan;需确认提取溶剂与防腐载体;清真需供应商出具证明。','low','加料方式直接决定手感,必须先定目标再定加料点。与水相同煮:多糖充分水化,体系更稠、更「厚」,但高温保温时间长会损失粘度、颜色也会加深;降温到 45℃ 以下后加:粘度贡献小、肤感更清爽,但可能残留未完全水化的颗粒感。这个加料点一旦确定就写死在工艺卡上,不允许现场随意调整,否则同一配方会做出两种手感。粉体必须先用甘油或多元醇预分散,直接入水会结「鱼眼」团,团块在成品里表现为透明颗粒,过筛也去不掉。放大生产时大锅水化更慢,首批按小样粘度上浮 10–15% 预留调整空间。','hydration','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('panax-notoginseng-root-extract','Panax Notoginseng Root Extract','三七(根)提取物','三七根提取物,田七,山漆,Notoginseng Root Extract,Panax notoginseng','未确认','植物提取物','barrier','与人参同属不同种,成分谱并不通用:三七以三七皂苷 R1 与 Rb1/Rg1 的特定组合为特征,人参则是 Rg1/Re/Rb1 的另一种比例结构,标示物和检测方法都不一样。配方中常用于舒缓与泛红方向的复配。采购最常犯的错是把两者当同一物料互换报价或互换送样,结果客户送检时对不上标示物——库里把这一点写清楚,就是为了拦住这个错。','0.1–1%(公开配方学常见添加区间,非法规限值)','serum,essence,cream,lotion,mask,gel,toner','4.5–6.0','1)皂苷带起泡性与表面活性,在高油相或 W/O 体系里会削弱乳化稳定性,放置后可能微量析油。2)与阳离子聚合物形成复合物,导致浑浊或粘度下降。3)伴生多酚与多糖遇铁离子变色。4)高浓度电解质下溶解度下降。5)必须区分「三七提取物」与「三七粉」:后者是未提取的粉体,含大量不溶物,直接进面部免洗产品会有明显颗粒感,且微生物负载与提取物完全不是一个量级,不能按同一套工艺处理。','浅黄至黄棕色,遇氧与 pH 升高时缓慢加深;高温长时间保温可能引起皂苷转化,外在表现是颜色与气味同时变化。含糖类的规格微生物风险偏高。常见防护做法:pH 控在 4.5–6.0、配螯合剂、降温后加、防腐单独做挑战测试,并要求供应商提供特征皂苷(如 R1)的含量数据,用于判断批间一致性——只看外观和总固含判断不了这一点。','作为化妆品原料属常规使用方向,需核对收录状态与使用部位并按目标市场规则复核;以最新官方文本为准。','属常规使用方向,需完成安全评估并复核该市场对植物提取物的限制清单;以最新官方文本为准。','属常规使用方向,按该市场化妆品监管框架与行业安全评估惯例复核;以最新官方文本为准。','东亚草本线关注度较高,属常规使用方向,需按各国原料目录分别复核;以最新官方文本为准。','植物来源,通常可做 vegan;需确认提取溶剂与载体;清真需供应商出具证明。','mid','与人参共线生产时必须用不同物料代码、不同货位、不同标签颜色。两者粉体外观几乎一样,拿错在成品上看不出来,只有客户送检时才暴露,属于会直接赔货的事故类型。溶解同样起泡,低转速加抽真空,乳化降温后再加。客户要求「人参三七复配」时,先确认标示物合计怎么算,合同里写清各自投料量而不是只写一个总量,否则后续检测口径会打架。粉状规格先用多元醇预分散。','soothing','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('morus-alba-root-extract','INCI 保持 Morus Alba Root Extract;name_zh 改为「白桑(根)提取物」;aliases 改为「桑根提取物,White Mulberry Root Extract,Morus alba」(删掉「桑白皮」「桑根皮提取物」「Morus Alba Root Bark Extract」);mechanism_zh 开头加一句边界:「注意区分部位:中药语境的桑白皮是根皮,对应的是另一条 INCI(Morus Alba Bark Extract 一类),与本条的根提取物不是同一物料,报价与送样不能互换。」','桑白皮提取物','桑根皮提取物,桑白皮,White Mulberry Root Extract,Morus Alba Root Bark Extract,Morus alba','未确认','多酚','brightening,antioxidant','以桑辛素类、氧化白藜芦醇等多酚为主。配方中常用于肤色不均方向的复配以及抗氧化体系设计。它的技术难点不在活性,而在颜色管理:多酚在配方里几乎是一个「氧化指示剂」,体系里凡是有铁、有碱、有氧化剂,它都会第一个显形。','0.05–0.5%(公开配方学常见添加区间,非法规限值)','serum,essence,toner,lotion,cream,mask,gel','4.0–5.5','这是浅色配方里最容易翻车的一味。1)与过氧化物、高浓度氧化剂、氧化型染发中间体接触会立即褐变。2)与铁/铜离子生成有色络合物,微量即可见。3)pH 超过约 6.5 时,几小时内由无色转黄、由黄转褐。4)与含醛类香精成分、与碱性氨基酸体系共存会加速褐变。5)与抗坏血酸类共存虽然抗氧化方向一致,但只要 pH 或金属离子残留失控,两者会一起变色,反而更难定位是谁引起的——排查时要先做单方对照。','主要失效模式是变色,而不是活性衰减:实际投诉里绝大多数是「放两个月变茶色」。氧、光、金属离子、pH 上移这四个因素叠加时速度极快。常见防护做法:pH 控在 4.0–5.5;必配螯合剂(EDTA 二钠或植酸);加水溶性抗氧化剂并控制顶空(小容量灌装、真空瓶、软管都优于广口瓶);避光包材;有条件时水相脱氧或氮气保护。稳定性考察必须同时做光照组与 45℃ 组,验收标准写成色差上限,并在留样架放平行样每周记录色号。','作为化妆品原料属常规使用方向,需核对收录状态与使用部位并按目标市场规则复核;以最新官方文本为准。','属常规使用方向,需完成安全评估并复核该市场对植物提取物的限制清单;以最新官方文本为准。','属常规使用方向,按该市场化妆品监管框架与行业安全评估惯例复核;以最新官方文本为准。','东亚肤色管理类配方使用普遍,属常规使用方向,需按各国原料目录与宣称管理规则分别复核;以最新官方文本为准。','植物来源,通常可做 vegan;需确认提取溶剂与载体;清真需供应商出具证明。','mid','生产用水必须走纯化水,自来水里的微量铁就足以让整锅泛黄——这是最常被忽略的一条,也是最便宜的一条改进。设备选 316L,避免碳钢工具,避免长时间接触铜质阀门。加料顺序固定为:先加螯合剂 → 调 pH 到目标区间 → 加桑白皮 → 最后加香精;顺序颠倒当天不一定看得出来,货架期一定看得出来。降温到 40℃ 以下后加,高温投料会造成一次性且不可逆的加深。透明水剂建议同时控澄清度与色度两个指标,只写「澄清透明」在量产阶段没有判定力。','brightening','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('polygonum-multiflorum-root-extract','Polygonum Multiflorum Root Extract','何首乌(根)提取物','aliases 删掉「夜交藤同源植物根」,改为「何首乌根提取物,首乌,Fo-Ti Root Extract,Polygonum multiflorum,Reynoutria multiflora」;若要保留这个区分,放进 mechanism_zh:「同株的藤茎(首乌藤/夜交藤)对应另一条 INCI,部位不同、不可互换。」','未确认','植物提取物','conditioning,antioxidant','主要含二苯乙烯苷类与蒽醌类背景成分。在头皮与头发护理配方中常作为草本调性组分使用,参与抗氧化方向的复配,同时是配方颜色设计里的强着色料。有一条边界必须说在前面:何首乌在口服与中药语境下的讨论(包括肝相关安全争议与炮制要求)与化妆品外用是两套不同的评估体系;对外沟通时既不能拿口服文献给外用产品背书,也不能假装那些讨论不存在——两边话术要分开写。','0.05–0.5%(公开配方学常见添加区间,非法规限值)','serum,essence,foam,lotion,cream,gel,mask','4.5–6.5','1)颜色极深(深棕至近黑),0.1% 就能改变白色膏体的整体色相,与浅色或透明体系基本不兼容,配色要在立项阶段就定,不要等打样再改。2)多酚与蒽醌遇铁离子加深并可能出现色斑。3)pH 超过 7 时颜色急剧加深并偏红,皂基与高 pH 洗发体系必须先做色相评估。4)与阳离子调理剂可能絮凝,并在发丝上形成沉积,浅发色人群有着色风险,冲洗类同样要评估。5)与氧化型染发体系不可共存。','深色料的稳定性不能只靠目视判断——本体已经很深,继续加深不易察觉,建议用色度计定量并设色差上限。光照下缓慢褪红、遇氧加深、高 pH 与高温都会加速。常见防护做法:pH 控在 4.5–6.5、配螯合剂、用避光包材(深色料装透明瓶还有「看起来脏」的商业问题)。此外必须单独做染色测试:白布或白发束浸泡 24 小时观察,提前拦掉「洗完毛巾被染色」这类上市后才爆发的投诉。','化妆品用途需核对该原料的收录状态与允许使用部位,并按目标市场规则复核;口服/中药语境下的资料不能用于外用产品的合规或宣称依据;以最新官方文本为准。','属常规使用方向,需完成安全评估并复核该市场对植物提取物及蒽醌类相关关注点的要求;以最新官方文本为准。','属常规使用方向,按该市场化妆品监管框架与行业安全评估惯例复核;以最新官方文本为准。','头皮护理线询问度高,属常规使用方向,需按各国原料目录与宣称管理规则分别复核;以最新官方文本为准。','植物来源,通常可做 vegan;需确认提取溶剂与载体;清真需供应商出具证明。','mid','这是本批十味里清洗成本最高的一味。强着色料必须排在批次末尾,清洗用碱性清洗剂加多次冲洗并做白水验证,否则下一锅浅色产品直接报废。浸膏黏稠挂壁,用配方内多元醇冲洗容器保证投料准确。降温到 45℃ 以下后加。采购环节要求供应商提供蒽醌类相关检测项与规格范围,并把结果存进物料档案。客户沟通材料里把「外用化妆品」与「口服/中药」的边界写清楚,不引用口服文献做宣称,也不做生发、乌发、防脱一类的功效表述。','conditioning','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('centella-asiatica-extract','Centella Asiatica Extract','积雪草提取物','积雪草,雷公根,崩大碗,老公根,Centella asiatica,Gotu kola,CICA','84696-21-9（积雪草提取物常见登记号；积雪草苷、羟基积雪草苷等单体另有各自编号，以供应商 COA 为准）','植物提取物','soothing,barrier,repair,anti-aging','主要活性是以积雪草苷、羟基积雪草苷为代表的三萜苷类，以及积雪草酸、羟基积雪草酸等三萜酸。配方里通常放在舒缓与屏障线，用于外界刺激后皮肤泛红、紧绷、干燥脱屑这一类感受问题的配方方向，也常与神经酰胺、泛醇、胆固醇一起做屏障组合。需要特别区分两种规格：常规倍数提取物（活性物含量低、带较多多糖与色素）和苷类富集物／单体（活性物含量高、颜色浅），两者不能按同一个添加量沟通。','常规提取物 0.1–5%；苷类富集规格 0.1–1%（公开配方学常见区间，非法规限值）','serum,essence,cream,lotion,mask,gel,toner','4.0–7.0','5) 苷类富集规格（积雪草苷／羟基积雪草苷总量高的规格）在纯水中溶解度很低，直接投水相必然结团挂壁，必须先用多元醇或乙醇助溶。','苷类本身对光相对不敏感，真正不耐放的是提取物里的多酚与色素：见光遇氧后颜色由淡黄转琥珀，透明包装三个月内肉眼可辨，这不是变质但客诉率高。60℃ 以上长时间保温会加速苷类水解，加速试验里表现为含量与外观同时走。pH 漂到 8 以上时活性与颜色一起走。含多糖和残糖较多的规格水活度高、微生物余量小。常见防护：终点 pH 控在 5.0–6.5、必配螯合剂、后段低温投料、避光或不透明包装、透明剂型改用浅色富集规格。','常规使用方向的植物提取物，需确认所用原料已在国内已使用化妆品原料目录内并具备原料安全信息码；以最新官方文本为准。','按常规植物提取物使用，安全评估需覆盖溶剂残留、农残与重金属项；以最新官方文本为准。','一般作为化妆品成分常规使用，宣称不得越过 OTC 药品界线；以最新官方文本为准。','日韩及东南亚多按常规化妆品原料使用，个别市场对具药用背景的植物另有清单要求，按目标市场规则复核；以最新官方文本为准。','植物来源，通常可做 vegan；醇提规格的清真认定需供应商说明乙醇来源与残留并出具证明。','mid','投料：粉末规格先用少量丙二醇、1,3-丁二醇或 10–30% 乙醇预分散成浆，再细流加入水相，直接撒粉一定结团挂壁；水溶液型规格多自带防腐与共溶剂，入锅前先测 pH。乳化体系放在乳化完成、降温到 45℃ 以下加，不要跟高温均质段一起走。加热上限建议 60℃ 短时。放大生产的坑：批间颜色与活性物含量差异比小样明显，建议按 COA 的苷类含量折算投料重量，而不是固定按公斤投。最重要的一条：和客户确认规格时必须在配方单和报价单上写清是「多少倍提取物」还是「苷类总量 ≥x%」，这是这条料最高频的浓度纠纷来源——客户以为的 2% 和工厂投的 2% 常常差一个数量级。','barrier-repair','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('camellia-sinensis-leaf-extract','Camellia Sinensis Leaf Extract','绿茶（叶）提取物','绿茶提取物,茶叶提取物,Camellia sinensis,Green tea extract,儿茶素来源原料','84650-60-2（茶提取物常见登记号；EGCG 等单体另有各自编号，以供应商 COA 为准）','多酚','antioxidant,soothing,oil-control,anti-aging','主要成分是以 EGCG 为代表的儿茶素类多酚，另含咖啡因与少量氨基酸。配方里主要放在抗氧化方向，作为体系自身的自由基清除与协同护色成分，也常出现在油皮清爽线和舒缓线。需要注意它既是活性物也是体系里最活跃的还原性物质，会主动参与配方内的氧化还原反应，因此更常被当成需要被保护的对象来设计。','0.05–2%（以常规倍数提取物计；高儿茶素富集规格 0.01–0.5%）（公开配方学常见区间，非法规限值）','serum,essence,toner,gel,lotion,cream,mask,foam','4.0–6.0','1) 金属离子是头号杀手：与铁、铜接触立刻生成有色络合物，由黄转褐甚至发墨绿黑。金属来源不只是配方，还包括自来水、锅具锈斑、管路磨损、色粉与滑石粉中的铁杂质。2) pH 6.5 以上儿茶素氧化速率大幅上升，与三乙醇胺、氨甲基丙醇等碱化剂共处的局部高 pH 区就足以启动褐变。3) 与抗坏血酸类同用短期看着护色，实际两者互相消耗，中后期一起走，不要当成稳定方案。4) 与阳离子调理剂、水解蛋白与肽类同用，单宁结合会出浑浊或絮状，肽类活性也可能被拉低。5) 与过氧化物、含活性氯体系完全不相容。6) 与高含铁的天然矿物色料（部分土黄、氧化铁系）同配会整体发暗。','见光遇氧变褐是最典型表现——含儿茶素的水剂放置后变黄，第一顺位怀疑对象就是儿茶素氧化。温度是加速因子，80℃ 以上短时间即可见色，加速试验 45℃ 一个月往往就能看出成品寿命。','常规使用方向的植物提取物，需确认原料在国内已使用化妆品原料目录内并具备原料安全信息码；以最新官方文本为准。','按常规植物提取物使用，安全评估需覆盖溶剂残留与重金属项；以最新官方文本为准。','一般作为化妆品成分常规使用，抗氧化叙述不得转成治疗性表述；以最新官方文本为准。','日韩及东南亚多按常规化妆品原料使用；具体申报与限制要求按目标市场规则逐项复核；以最新官方文本为准。','植物来源，通常可做 vegan；醇提规格的清真认定需供应商说明乙醇来源与残留并出具证明。','low','投料顺序有讲究：配料水先加螯合剂搅匀，再加提取物，不要反过来——先加提取物再补螯合剂，褐变往往已经发生且不可逆。粉末规格先用去离子水或丁二醇溶开再入锅。加热上限建议 50℃，实际操作放在降温到 40–45℃ 的后段加，绝不与高温保温段同行。锅具与管路开工前确认无锈斑，铜质配件禁用。放大生产的坑：大锅顶空与循环时间比小样长，带氧量高，颜色批差比小样明显，建议每批留色板并规定色差判定范围；同时与香精同用时褐变会改变顶调感受，香精定型样要用放大批做。给客户打样时同时给「当天样」和「45℃/1 个月样」看色，把预期先讲在前面，比事后解释省事得多。','antioxidant','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('artemisia-princeps-leaf-extract','Artemisia Princeps Leaf Extract','艾蒿（叶）提取物','艾草,日本艾,韩国艾蒿,Artemisia princeps,Mugwort','未确认','植物提取物','soothing,barrier,antioxidant','含黄酮、酚酸、香豆素类与少量挥发油成分。配方里主要放在舒缓与草本叙事方向，常见于韩式舒缓精华、水乳与贴片面膜。它的价值有一半在概念端——采购会直接拿「艾蒿／Mugwort」这个词来找工厂，因此规格沟通要早于配方沟通：脱色脱味规格和保留草本香气的规格，做出来是两支完全不同气质的产品。','0.1–3%（公开配方学常见区间，非法规限值）','serum,essence,toner,cream,lotion,mask,gel','4.5–6.5','1) 菊科（Asteraceae）背景需要在配方层面控总量：与洋甘菊、金盏花、蓍草、款冬等同科提取物叠加时，倍半萜内酯类的致敏背景会累加，舒缓线堆料是常见误区。2) 多酚与单宁含量不低，与阳离子调理剂、水解蛋白／肽类同用易出浑浊或絮状。3) 与高浓度电解质同用会返浊。4) 遇铁离子发暗，pH 中性以上颜色加深。5) 含挥发油残留的规格在水剂中若增溶剂用量不足会起雾，透明爽肤水尤其明显。6) 醇提规格直接投入已成型乳液可能局部破乳。','两条线同时走：颜色和气味。叶绿素与多酚残留使其见光褪绿转黄褐，透明包装三个月内可见；挥发性香气成分在开放搅拌、长时间高温与大顶空条件下大量损失，导致成品草本香型批间不一致，这一条比颜色更容易被客户挑出来。pH 上到中性以上颜色加深加速。防护：避光包装、后段低温投料、加螯合剂、透明剂型选澄清脱色规格、生产全程加盖低速。','常规使用方向的植物提取物，需确认原料在国内已使用化妆品原料目录内并具备原料安全信息码；以最新官方文本为准。','按常规植物提取物使用，安全评估需覆盖菊科致敏背景、香气成分过敏原与溶剂残留；以最新官方文本为准。','一般作为化妆品成分常规使用，安全性文件建议纳入菊科过敏背景说明；以最新官方文本为准。','日韩市场使用成熟且概念认知度高，部分市场对植物来源与部位申报另有要求，按目标市场规则复核；以最新官方文本为准。','植物来源，通常可做 vegan；醇提规格的清真认定需供应商说明乙醇来源与残留并出具证明。','mid','第一件事是和客户敲定「要不要保留草本气」。保留：接受批间气味差，并在香精设计上预留空间，香精不能只按小样定；不要味：选脱色脱味规格，工艺省心但草本叙事随之变弱，这一点要提前讲清楚，避免打样后反复。投料放在乳化完成、降温 40℃ 以下；醇提液先与部分水相或多元醇预混稀释再细流加入，直接倒入易局部破乳。加热上限 50℃。放大生产的坑：大锅静置后原料本身的青草气比小样更明显，且顶空大导致香气损失更快，因此香精定型样必须按放大批做；贴片面膜要连无纺布一起做闻香和色泽的加速试验，布上的表现与料体不同。','soothing','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('houttuynia-cordata-extract','Houttuynia Cordata Extract','鱼腥草提取物','蕺菜,折耳根,狗贴耳,Houttuynia cordata,Chameleon plant','未确认','植物提取物','soothing,oil-control,barrier','含黄酮类（槲皮苷、芦丁类）、酚酸与特征性挥发性醛类成分。配方中主要用于油痘线与舒缓线方向，常与锌盐、水杨酸温和体系或控油多糖搭配。这条料的技术难点几乎全在气味工程上：活性成分与异味来源部分重叠，去味越彻底、草本叙事和感官识别度就越弱。','0.1–2%（公开配方学常见区间，非法规限值）','toner,essence,serum,gel,lotion,mask,foam','4.5–6.5','1) 与含醛类香调（青醛、脂肪醛系）的香精叠加，会把腥味放大而不是掩盖，这是最常见的遮味失败原因。2) 与胺类原料、氨基酸类在偏碱条件下可能生成新的异味物质，气味方向变得更难预测。3) 多酚含量高，遇铁离子发暗；与阳离子调理剂、肽类同用可能浑浊。4) 高浓度醇体系（>20%）会把挥发性成分「提」出来，爽肤水与喷雾中腥味显著加重。5) 与高浓度电解质同用返浊。6) 与强氧化性体系不相容，活性与气味同时改变。','最先出问题的不是颜色而是气味：特征醛类在储存中氧化，气味由「青腥」转「陈腐」，消费者比检测更早发现。见光、高温、大顶空都加速这一变化；pH 偏碱时挥发释放更强。颜色方面见光遇氧由浅黄转褐。防护：终点 pH 控偏酸（4.5–5.5）、避光包装、缩小灌装顶空、选低气味或脱味规格、把用量往下压到概念够用的水平、必要时加抗氧剂延缓醛类氧化。','常规使用方向的植物提取物，具药食背景但化妆品用需确认原料在国内已使用化妆品原料目录内并具备原料安全信息码；以最新官方文本为准。','按常规植物提取物使用，安全评估需覆盖溶剂残留、农残与重金属；以最新官方文本为准。','一般作为化妆品成分常规使用，控油方向宣称不得越过 OTC 痤疮药品界线；以最新官方文本为准。','日韩及东南亚常规使用，部分市场对药用背景植物另有清单要求，按目标市场规则复核；以最新官方文本为准。','植物来源，通常可做 vegan；醇提规格的清真认定需供应商说明乙醇来源与残留并出具证明。','low','遮味方案会反过来限制香精选择，这是别处查不到的经验：常见做法是用柑橘、薄荷、绿茶这类清爽调压味，但它们本身挥发快，货放三个月后香气衰减、腥味回头，所以闻香判定必须做在加速试验的后期样上，只闻当天样一定会误判；木质调、粉香调、东方调基本压不住醛类腥气，白花调容易和腥味合成第三种更差的气味。投料必须在最后降温段（<40℃）、加盖低速搅拌，不能开盖高速把香气挥发掉再靠香精回补——那样批间气味完全不可控。加热上限 50℃。放大生产的坑：大锅顶空比小样大，气味损失与氧化都更明显，香精用量要按放大批重新定；建议给客户同时寄「当天样」和「40℃/1 个月样」做闻香对比，把气味预期写进打样确认单。','oil-control','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('lonicera-japonica-flower-extract','Lonicera Japonica Flower Extract','金银花（花）提取物','忍冬花,双花,银花,Lonicera japonica,Japanese honeysuckle','未确认（绿原酸单体 CAS 327-97-9，仅供规格核对参考，以供应商 COA 为准）','多酚','soothing,antioxidant,barrier','以绿原酸类酚酸为主，另含木犀草苷等黄酮和少量环烯醚萜苷。配方中放在舒缓与抗氧化方向，常见于清爽水剂、后阳光舒缓线与草本概念产品。因为主活性是酚酸，它对 pH 的敏感度高于大多数植提，配方设计要先定 pH 窗口再谈别的。','0.1–3%（公开配方学常见区间，非法规限值）','toner,essence,serum,gel,mask,lotion,cream','4.0–6.0','1) 与胺类碱化剂（三乙醇胺、氨甲基丙醇、氢氧化钠溶液）直接接触是最典型的翻车点：局部高 pH 会把绿原酸迅速氧化成醌类并聚合，同时胺与醌加成，颜色一步跳深且不可逆，回调 pH 也救不回来。2) 遇铁离子生成深色络合物，整批发墨绿或发黑。3) 与含活性氯、过氧化物体系不相容。4) 与阳离子调理剂、蛋白肽同用可能因酚酸结合出浑浊。5) 与高浓度电解质同用返浊。6) 与同样怕碱的抗坏血酸类同配时两者互相消耗，不宜当作护色搭配。','水剂配方的 pH 窗口必须写死：pH 4.0–6.0 区间相对稳定；超过 6.5 颜色与活性一起走；pH 7 以上常温数天内即可见明显加深。见光遇氧加速氧化聚合，透明包装表现最差。高温保温同样加速。常见防护：终点 pH 控 4.5–5.5、必配螯合剂、避光或不透明包装、灌装前降氧减少带气、加速试验做到 45℃ 一个月看色并留色板。','常规使用方向的植物提取物，药食同源背景不等于化妆品可用，需确认原料在国内已使用化妆品原料目录内并具备原料安全信息码；以最新官方文本为准。','按常规植物提取物使用，安全评估需覆盖溶剂残留、农残与重金属；以最新官方文本为准。','一般作为化妆品成分常规使用，舒缓方向宣称不得转成治疗性表述；以最新官方文本为准。','日韩及东南亚常规使用，部分市场对药用背景植物另有清单要求，按目标市场规则复核；以最新官方文本为准。','植物来源，通常可做 vegan；醇提规格的清真认定需供应商说明乙醇来源与残留并出具证明。','mid','投料顺序是这条料的关键：先把水相 pH 调到目标值、搅匀、复测确认，再加提取物；绝不能先加提取物再用碱剂回调 pH——回调时碱剂入锅点的局部 pH 会瞬间冲到 9 以上，颜色当场打深且不可逆，这是小厂最常见的整批报废原因。碱剂必须先稀释成 10% 以下溶液、在搅拌良好的位置细流慢加。加热上限 50℃，实际放在降温 40℃ 以下的后段投料。配料水先加螯合剂。放大生产的坑：大锅里 pH 调节的局部不均匀比小烧杯严重得多，建议加装循环或分点加碱；透明水剂建议先做 45℃/1 个月与光照试验确认色泽后再开印刷版包材。','soothing','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('bambusa-vulgaris-extract','Bambusa Vulgaris Extract','竹提取物','aliases 改为「竹子提取物,龙头竹提取物,Bambusa vulgaris,Bamboo extract」；把部位问题挪进 mechanism_zh，补一句：「该 INCI 不标注部位，叶部另有 Bambusa Vulgaris Leaf Extract 等独立 INCI，下单前须与供应商确认部位、提取方式与硅含量规格。」','未确认','植物提取物','oil-control,hydrating,soothing','含以二氧化硅／硅酸盐形式存在的矿物成分，以及多糖、酚酸与氨基酸。配方中常用于清爽肤感与控油概念方向，也用作「植物矿物感」叙事的载体。要点在于它不是一个真正的水溶性单一物质，硅类成分在水中更接近胶体分散状态，配方稳定性问题多半由此而来。','0.1–3%（公开配方学常见区间，非法规限值）','toner,essence,gel,lotion,cream,mask,serum','4.5–7.0','1) 含硅类成分在水中呈胶体状态，对电解质敏感：与高浓度盐类、镁铝盐、部分电解质型保湿剂同用会絮凝，静置后出现瓶底细微沉淀。2) 与阳离子表活、阳离子调理剂同用容易电荷中和而聚集。3) 与铝盐、锆盐类同用可能共沉。4) 与高浓度醇（>25%）同用胶体稳定性下降。5) 在卡波姆透明凝胶中同用可能出现云雾感，或降低触变恢复，凝胶「挂不住」。6) pH 漂到碱性侧硅酸溶解行为改变，澄清度和黏度都可能跟着变。','最常见的现象不是变质而是外观：静置后瓶底出现一层极薄的白色沉淀，透明瓶尤其扎眼，客户往往直接判成品不合格。高温灭菌或长时间高温保温会促进颗粒长大、沉淀更明显。pH 漂移会同时改变澄清度与体系黏度。常见防护：控 pH 在 5.0–6.5、必要时用黄原胶／结冷胶做微量悬浮体系、透明剂型改用澄清级或已过滤规格、避免高浓度电解质同配、成品做长时间静置观察而不只看当天外观。','常规使用方向的植物提取物，需确认原料在国内已使用化妆品原料目录内并具备原料安全信息码；以最新官方文本为准。','按常规植物提取物使用，安全评估需覆盖不溶性颗粒物形态与重金属项；以最新官方文本为准。','一般作为化妆品成分常规使用；以最新官方文本为准。','日韩及东南亚常规使用，按目标市场规则复核植物来源与部位申报；以最新官方文本为准。','植物来源，通常可做 vegan；醇提规格的清真认定需供应商说明乙醇来源与残留并出具证明。','low','澄清度靠过滤工艺解决，而且必须提前和客户摊牌：0.45–1 μm 级过滤或离心能显著改善透明水剂的外观，但会把一部分硅类成分一起滤掉，含量与澄清度是取舍关系，不能又要「看得见的矿物感」又要「玻璃一样透」。投料先用少量水或多元醇分散成浆再入锅，不要干粉直投。避免在高剪切下长时间循环——既带气又可能把颗粒打细后重新团聚。加热上限 60℃。放大生产的坑：管路、滤芯和泵的截留量占比与小样完全不同，收率要重算，按小样比例投料常常导致成品含量偏低；灌装前静置脱气 4–12 小时能明显减少瓶内悬浮点与气泡。判定外观建议以「灌装后静置 72 小时」为准，不要以刚灌完为准。','oil-control','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('rhodiola-rosea-root-extract','Rhodiola Rosea Root Extract','红景天（根）提取物','红景天,玫瑰红景天,Rhodiola rosea,Golden root,Roseroot','未确认（红景天苷单体 CAS 10338-51-9，仅供规格核对参考，以供应商 COA 为准）','多酚','antioxidant,soothing,anti-aging','主要标志成分是红景天苷（salidroside）与酪醇，另含洛塔文类肉桂醇苷、黄酮与酚酸。配方中放在抗环境压力、抗氧化的概念方向，常与依克多因、麦角硫因、多种植提组成「城市防护」类叙事。这条料的现实问题不在配方性能，而在来料真假与批间一致性。','0.05–1%（以提取物计，视标志物含量折算）（公开配方学常见区间，非法规限值）','serum,essence,cream,lotion,toner,mask','4.5–6.5','1) 酚苷类在碱性条件下水解，pH 8 以上标志物含量走低，同时颜色加深。2) 与过氧化物、含活性氯等氧化性体系不相容。3) 多酚与单宁背景使其与阳离子调理剂、水解蛋白与肽类同用可能出现浑浊或絮凝。4) 遇铁离子发暗。5) 高浓度醇提液直接倒入已成型乳液会造成局部破乳或颗粒感。6) 与高浓度电解质同用可能返浊。','见光与遇氧使颜色由浅黄逐步转红棕，透明包装最明显；高温长时间保温会降解苷类，加速试验中标志物含量与颜色同步走；pH 建议控在 4.5–6.5。常见防护：避光包装、必配螯合剂、后段低温投料、配抗氧剂、灌装控顶空。因为单价高，稳定性损失直接等于成本损失，建议对高价配方做标志物含量的加速前后对比而不只看外观。','常规使用方向的植物提取物，需确认原料在国内已使用化妆品原料目录内并具备原料安全信息码；以最新官方文本为准。','按常规植物提取物使用，安全评估需覆盖植物基原确认、溶剂残留与重金属项；以最新官方文本为准。','一般作为化妆品成分常规使用，抗压／抗氧叙述不得转成治疗性表述；以最新官方文本为准。','日韩及东南亚常规使用，部分市场对具药用背景植物另有清单要求，按目标市场规则复核；以最新官方文本为准。','植物来源，通常可做 vegan；醇提规格的清真认定需供应商说明乙醇来源与残留并出具证明。','high','这条料的核心工作是来料验证，采购真正关心的就是这一段。掺假手法有三类：一是用同属其它种（如大花红景天等）冒充 Rhodiola rosea；二是外加合成红景天苷把标志物含量「做上去」；三是用糊精、麦芽糊精大比例稀释后仍标高倍数。验证要点：① 索要完整 HPLC 图谱而不是只看一个总含量数字，重点看红景天苷与洛塔文类、酪醇的相对比例是否符合天然来源的指纹特征——只有红景天苷一个高峰、其余几乎没有，基本可判为外加单体；② 要求提供拉丁学名、药用部位、产地与原厂批号可追溯的文件，转手商的自制 COA 不作数；③ 要求同批留样，并做批间图谱比对；④ 报价明显低于市场时先怀疑再谈价。生产上：后段降温到 40℃ 以下投料，醇提液先与多元醇或部分水相预混稀释；加热上限 50℃。配方单上要按标志物含量锁死规格，换供应商必须重新做稳定性，不能因为 INCI 名相同就直接替换。','antioxidant','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('lycium-barbarum-fruit-extract','Lycium Barbarum Fruit Extract','枸杞（果）提取物','枸杞,宁夏枸杞,枸杞子,Lycium barbarum,Goji berry,Wolfberry','未确认','多糖','antioxidant,hydrating,barrier','主要成分是枸杞多糖，另含玉米黄质等类胡萝卜素、甜菜碱与酚酸。配方中用于保湿成膜与抗氧化方向，药食同源的叙事在东亚与出海市场都好讲。技术上要同时处理两件事：多糖与残糖带来的微生物余量下降，以及类胡萝卜素带来的颜色不稳定。','0.1–3%（公开配方学常见区间，非法规限值）','essence,serum,cream,lotion,mask,toner,gel','4.5–6.5','1) 与低强度防腐体系（仅低用量苯氧乙醇、或所谓「无防腐」路线）搭配风险高：糖与多糖是现成的碳源，原本能过的防腐方案加了这条料就可能过不了。2) 与高浓度电解质同用，酸性多糖可能絮凝、体系黏度掉。3) 与阳离子调理剂同用可能与酸性多糖结合成絮。4) 类胡萝卜素是脂溶性的，在纯水剂中增溶不足会起雾或出现油点。5) 遇铁离子与强氧化剂褪色。6) 与胺类在高温下共处会加速美拉德型褐变并产生焦甜气味。','两个现实问题：颜色和微生物。类胡萝卜素见光遇氧褪色变暗，由橙黄转土黄；糖类在偏碱与高温下发生褐变并可能带出气味；含糖体系水活度高，水剂与面膜液的微生物挑战难度明显上升，生产环境与灌装暴露时间的影响被放大。常见防护：选择低糖／已纯化的多糖规格、避光包装、终点 pH 控弱酸、加螯合与抗氧剂、并且按含糖体系重新设计防腐并实测。','常规使用方向的植物提取物，药食同源背景不等于化妆品可用，需确认原料在国内已使用化妆品原料目录内并具备原料安全信息码；以最新官方文本为准。','按常规植物提取物使用，安全评估需覆盖溶剂残留、农残与重金属项；以最新官方文本为准。','一般作为化妆品成分常规使用；以最新官方文本为准。','日韩及东南亚常规使用，按目标市场规则复核植物来源与部位申报；以最新官方文本为准。','植物来源，通常可做 vegan；清真需供应商就加工助剂与载体出具证明。','mid','最实用的一条：防腐体系必须跟着调。含糖植提进配方后，原来通过的防腐方案不能沿用，必须重做防腐挑战试验；水基面膜液、无醇爽肤水、高水活度啫喱尤其要把防腐余量留足，并考虑缩短灌装暴露时间。采购规格上要把固含量和糖含量写进去，只写「多少倍提取」无法评估微生物风险与成本。投料放在降温 45℃ 以下的后段，避免与高温保温段共存——那一段既褐变又伤类胡萝卜素。加热上限 55℃。设备清洗要按含糖料体加强，残留糖膜是后续批次染菌的常见源头。放大生产的坑：面膜液在无纺布上的颜色变化比料体本身快，加速试验必须连布一起做，否则上市后会出现「料没问题、布发黄」的投诉。','antioxidant','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('betula-alba-juice','Betula Alba Juice','白桦树汁','桦树汁,白桦汁,桦树液,Betula alba,Birch sap,Birch juice','未确认','植物提取物','hydrating,soothing,barrier','是早春从桦树采集的树液，天然含糖类（以木糖、葡萄糖、果糖为主）、有机酸、氨基酸与钾钙镁等矿物质，固含量低。配方中常被用作「以树汁替代部分水」的概念性基质，用于清爽保湿方向。它在技术上不是一个活性物问题，而是一个基质工程问题：换掉的是配方里占比最大的那一相。','以替代部分水相计，常见 5–50%；工艺可控起步区间建议 30–50%，更高比例须先跑通防腐挑战与稳定性再谈（公开配方学常见区间，非法规限值）','toner,essence,lotion,mask,gel,serum','4.5–6.5','1) 自带钾钙镁等电解质，会压缩卡波姆等阴离子增稠体系的黏度——高比例直接替代水，凝胶往往起不来或明显变稀，这是最常见的第一次翻车。2) 二价阳离子与酸性多糖（如卡拉胶、部分果胶）或皂化体系同用，可能生成不溶物或絮状。3) 与高浓度醇同用可能析出沉淀。4) 糖分与胺类在高温下褐变并产生焦甜气味。5) 高含糖背景与低强度防腐体系不相容。6) 与铁离子接触后颜色加深。','这是一条营养液，不是水：水活度高、含糖含氮，微生物挑战难度显著上升，未经处理的原液在常温下数小时就可能起菌变味。冻存或浓缩规格解冻后常见沉淀与颜色变化，需要重新过滤或均质。高温灭菌会引发褐变与气味改变，破坏「清透」的产品定位。常见防护：来料必须已做除菌处理（除菌过滤或巴氏）并自带防腐；进厂后冷链或低温存放，规定开桶后使用期限；成品防腐体系按最高风险设计并实测挑战；灌装环境与暴露时间纳入控制。','常规使用方向的植物汁液原料，需确认原料在国内已使用化妆品原料目录内并具备原料安全信息码，高比例使用时微生物指标需重点关注；以最新官方文本为准。','按常规植物汁液使用，安全评估需覆盖来料微生物控制、防腐有效性与重金属项；以最新官方文本为准。','一般作为化妆品成分常规使用，高水活度产品的微生物控制需有完整记录；以最新官方文本为准。','韩国等市场使用成熟且概念认知度高，按目标市场规则复核原料申报与微生物要求；以最新官方文本为准。','植物来源，通常可做 vegan；清真需供应商就防腐与加工助剂出具证明。','mid','这是典型的营销与工艺冲突案例：客户开口就是「90% 桦树汁替代水」，工厂要先把三个问题摆到桌面上——① 来料是否已除菌、自带什么防腐、开桶后能放几天；② 替代后增稠体系要重做，阴离子增稠剂多半得换成非离子型或耐电解质型，或改用胶体复配，肤感会跟着变，需要重新打样确认；③ 防腐挑战必须整套重做，不能沿用同款配方的历史数据。生产上：优先冷配，或在降温段加入并缩短滞留时间，不要与料体一起长时间高温保温；加热上限 50℃，能不加热就不加热。设备与管路按含糖料体加强清洗与消毒，残留极易成为下批染菌源。放大生产的坑：大批量时从开桶到灌装完成的总暴露时间远长于小样，微生物风险不是线性放大而是跳跃式上升，首批必须做在线取样验证。给客户的务实建议是先做 30–50% 替代跑通防腐挑战和稳定性，再谈更高比例——把这个台阶讲在报价前面，比事后返工划算。','hydrating','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('platycodon-grandiflorum-root-extract','Platycodon Grandiflorum Root Extract','桔梗（根）提取物','桔梗,苦桔梗,道拉基,Platycodon grandiflorum,Balloon flower root','未确认','植物提取物','soothing,hydrating,cleansing','主要成分是桔梗皂苷类三萜皂苷，另含多糖与酚酸。在韩式草本配方里常作配角出现，用于舒缓与草本叙事方向；皂苷本身具天然表面活性，在清洁类产品中也能贡献一部分起泡与助溶。正因为它是天然表活，它会主动改变体系的界面行为，这一点比它的活性更需要在配方设计时考虑。','0.1–2%（公开配方学常见区间，非法规限值）','essence,serum,cream,lotion,toner,mask,foam','4.5–6.5','1) 提取物整体呈弱阴离子性（主要来自共萃的酸性多糖与酚酸，皂苷本身多接近非离子），与阳离子调理剂结合易生成不溶复合物，调理感被拉低并可能出现絮状物，这在护发与身体乳中最明显。','皂苷在强酸、强碱与长时间高温下水解，起泡力随之下降，这是判断料体是否被工艺伤过的直观指标；含糖多糖残留带来微生物余量的下降；颜色偏黄，见光遇氧加深。常见防护：pH 控在 4.5–6.5、后段低温投料、避光包装、按含糖体系复核防腐。','常规使用方向的植物提取物，需确认原料在国内已使用化妆品原料目录内并具备原料安全信息码；以最新官方文本为准。','按常规植物提取物使用，安全评估需覆盖皂苷类含量、溶剂残留与重金属项；以最新官方文本为准。','一般作为化妆品成分常规使用；以最新官方文本为准。','日韩及东南亚常规使用，按目标市场规则复核植物来源与部位申报；以最新官方文本为准。','植物来源，通常可做 vegan；醇提规格的清真认定需供应商说明乙醇来源与残留并出具证明。','mid','起泡是这条料最现实的生产问题，直接影响钱：在真空乳化锅后段加入皂苷类提取物，泡沫在真空条件下被抽成极细密的微泡，回压后长时间消不掉，结果是灌装装量偏低、瓶内可见气泡、批次装量波动超标。实操办法：① 在保持真空的状态下低速加入，加完维持真空慢搅 15–30 分钟脱气，绝不用高速均质，均质只会把泡打得更细更难消；② 必要时加微量消泡剂（有机硅型或非硅型），但要先做肤感、相容性与后续宣称的确认，硅类消泡剂会影响「无硅」诉求；③ 灌装前静置 8–24 小时，并按实测密度留装量补偿；④ 容量法灌装改重量法可显著降低装量波动，异形瓶尤其建议改。加热上限 55℃，投料放降温 40℃ 以下。放大生产的坑：大锅的高径比、搅拌桨形式与真空能力和小样差别很大，泡沫行为不能按小样推，首批必须现场确认脱气时间并写进工艺卡。','soothing','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('hamamelis-virginiana-leaf-extract','Hamamelis Virginiana Leaf Extract','金缕梅叶提取物','金缕梅,美洲金缕梅,维吉尼亚金缕梅,巫榛,Hamamelis virginiana,Witch Hazel','84696-19-5(以供应商 COA 复核)','植物提取物','soothing,oil-control,antioxidant','活性方向主要来自水解单宁(以金缕梅单宁为代表)与黄酮类多酚。单宁与皮肤表层蛋白结合后产生收敛的即时肤感,是欧美爽肤水、油痘线与湿巾配方里最常见的收敛骨架;多酚部分在体系中兼作抗氧化配角。选料时必须先分清两类完全不同的商品:一是含醇蒸馏液(hamamelis water),活性单宁很低但带明显醇感;二是水或丁二醇提取物,单宁含量高、收敛表现强,配伍风险也集中在这一类。','水/丁二醇提取物 1–5%;含醇蒸馏液型可占水相 10–30%(公开配方学常见区间,非法规限值)','toner,essence,serum,gel,lotion,mask','4.0–6.0','单宁类原料的典型翻车点,几乎都能在这一条上看到。1) 与阳离子调理剂直接絮凝:聚季铵盐-7/-10、瓜儿胶羟丙基三甲基氯化铵等一旦与它混合,几秒内出现白色絮状物或拉丝沉淀,二合一洗发、护发素与阳离子调理型爽肤水要么避开,要么改用低单宁的脱色蒸馏液规格。2) 与水解蛋白、水解胶原、多肽形成不溶复合物,现场可能还清澈,静置三到七天后瓶底出现絮状沉降,含肽精华里加金缕梅是高频事故。3) 遇三价铁离子显色,水相由黄转紫黑;含铁氧化物颜料、碳钢或镀锌管道、非 316L 的取样勺与滤网都会带来色斑,必须配螯合剂。4) 与硫酸锌、葡糖酸铜、乳酸铜等金属盐活性物共存易变色。5) 蒸馏液型自带乙醇,总醇量超过约 15% 时卡波姆体系会明显稀化,透明凝胶需改用耐醇聚合物。6) 与阴离子表活可用,但会削弱起泡与泡沫细腻度,洁面加量需控制。','多酚见光遇氧氧化,水相颜色沿淡黄→琥珀→棕褐推进,pH 越高褐变越快,超过 6.5 时数周内就能肉眼看出差异,建议把体系锁在 4.0–5.5。常见防护做法是低 pH + 0.05–0.1% 螯合剂 + 避光或深色包材三件套,单靠其中一件通常不够。热稳定性一般,60°C 以上长时间保温会显著加深颜色并带出涩味,所以按后加处理。做透明玻璃瓶爽肤水时必须提前跑光照与 45°C 加速(建议 4–8 周),把「随时间变深」的色泽范围写进质量标准,而不是给客户一个单点色标;这条原料被判色差退货,九成不是变质,是当初没对齐色泽预期。原料本身偏酸,不同批次会把体系 pH 拉低 0.2–0.5,每批都要复测。','作为植物提取物属常规使用方向,需确认原料已收录于国内已使用原料目录并取得原料安全信息码;以最新官方文本为准。','常规使用方向;含醇蒸馏液型需按实际乙醇含量处理标示与通报口径;以最新官方文本为准。','化妆品常规使用方向;收敛、控油类文案容易被写成疾病或治疗暗示,宣称需与法务复核;以最新官方文本为准。','日韩及东南亚多为常规使用方向,部分市场对植物提取物有进口与备案资料要求;以最新官方文本为准。','植物来源,通常可做 vegan;含醇蒸馏液型的清真认定需按乙醇来源与残留量单独评估,并要求供应商出具证明。','low','1) 严格按后加料处理:乳化完成、降温到 40°C 以下再投,不要跟着水相一起 85°C 保温。2) 投料前用配方内的部分水或丁二醇按 1:3–1:5 预稀释,再沿桶壁缓慢加入;直接把高浓度提取物倒进含高电解质的水相,会在接触面局部絮凝,形成后面搅不开的小颗粒。3) 与阳离子调理剂同配方时,先做小样并静置 48 小时确认无絮状再放大;要特别注意放大后的剪切强度更高,絮凝是更明显而不是更轻,小样勉强通过的组合放大必翻车。4) 全流程金属材质核对到位:主锅、管道、阀门、过滤网、取样器都要 316L,碳钢或铜件接触会直接显色。5) 蒸馏液规格含乙醇,投料时注意车间通风与闪点管理,并把这部分乙醇并入配方总醇量计算,别在标签和安全评估里漏算。6) 加完后复测并回调 pH,记录进批记录。','oil-control','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('chamomilla-recutita-flower-extract','inci 改为:Chamomilla Recutita (Matricaria) Flower Extract;aliases 末尾补上:Chamomilla Recutita Flower Extract(CosIng 无括号写法)','母菊花提取物(洋甘菊)','洋甘菊,德国洋甘菊,母菊,Matricaria chamomilla,Matricaria recutita,Chamomilla recutita,German Chamomile','84082-60-0(以供应商 COA 复核)','植物提取物','soothing,barrier,antioxidant','活性方向来自芹菜素类黄酮、红没药醇与母菊天蓝烃等萜类,常用于泛红与不耐受肌肤的安抚型配方,与神经酰胺、胆固醇等屏障脂质搭配,构成敏感线常见的低刺激骨架。真正要说清楚的是规格差异:水或丁二醇提取物近无色至浅黄,主体是黄酮与多糖;蓝色精油(蓝油)是母菊天蓝烃含量高的深蓝色精油,属精油范畴。两者的颜色、加量、气味与配伍规则完全不通用,客户口中的「洋甘菊」必须先问清是哪一个。','水/丁二醇提取物 0.5–3%;蓝油类按精油口径另计,常见 0.05–0.3%(公开配方学常见区间,非法规限值)','essence,serum,cream,lotion,mask,gel,toner','4.0–7.0','1) 菊科交叉致敏是这条最现实的配伍问题,而且是配方设计层面的:与金盏花、山金车、蓍草、洋蓟等同科提取物叠加,对菊科敏感人群的风险是累加的。婴童线与「敏感肌专用」定位建议全配方只保留一种菊科来源,不要为了成分表好看堆四五个。2) 黄酮与多酚遇三价铁离子显色,由浅黄转棕绿;含铁氧化物颜料的有色产品、硫酸亚铁类原料不宜共存,需加螯合剂并核对设备材质。3) 提取物携带的多糖与高浓度电解质(氯化钠、镁盐、高加量锌盐)共存时,低温储存会出现雾浊与沉降。4) 蓝油与浅色配方直接相冲:0.1% 级别就能把乳霜染成明显蓝绿,叠加二氧化钛白基后变成灰蓝,不是「少加一点」能解决的,只能换规格;蓝油还会被卡波姆体系吸附导致分散不均。5) 与高浓度过氧化物、次氯酸等强氧化体系不兼容,黄酮被破坏并变色。','黄酮与萜类见光氧化,浅黄水提物在透明瓶中三个月内可见加深。蓝油的蓝色本身就是不稳定的:遇光、遇酸会向绿、灰绿漂移,这是母菊天蓝烃降解的正常路径,不是长菌也不是变质,但客户几乎必然当成质量问题,所以色泽范围要在报价与确认样阶段一次说清并写进标准。pH 落到 3 以下或升到 8 以上都会加速色变与气味变化,建议锁在 4.5–6.5。热耐受一般,70°C 以上长时间保温会损失香气成分与部分黄酮,按后加处理。提取物含糖与多糖,是微生物友好基质,防腐挑战试验必须带这条原料一起做,不能用无洋甘菊的空白基质数据外推。','常规使用方向,需确认原料目录收录情况与原料安全信息码;以最新官方文本为准。','常规使用方向;若使用精油/蓝油规格,需按香料致敏物相关规则核对标示口径;以最新官方文本为准。','常规使用方向;「舒缓、修护敏感」类文案需避免疾病与治疗暗示;以最新官方文本为准。','常规使用方向,部分市场要求提供植物来源与进口资料;以最新官方文本为准。','植物来源,通常可做 vegan;醇提规格的清真认定需按乙醇来源与残留另行评估,并要求供应商出具证明。','mid','1) 水/丁二醇提取物属后加料,降温至 40–45°C 以下加入;若工艺上必须前加,把总保温时间压在 30 分钟内,并接受一定程度的色深与香气损失。2) 加料前做 1:5 预稀释,尤其当水相甘油超过 15% 时,直接投料分散不均会出现丝状纹路,灌装时表现为丝絮。3) 蓝油或精油规格必须先与油相或增溶剂(氢化蓖麻油类)预混均匀再入体系,直接滴入水相会浮油,并在灌装末期出现集中色点,整批返工。4) 色泽验收要按「色泽范围卡」而不是单一标样:同一供应商不同批次的黄绿深浅差异明显。建议在客户确认样阶段就取最深和最浅两个极限批各打一支给客户看,让客户签字确认范围。5) 微生物:植物提取物是初始菌落的常见来源,要求供应商逐批提供微生物数据并进料抽检;无防腐或极简防腐体系里不要用高加量。6) 香精评估必须在含它的实际基质里做,不要拿空白基质定香型。','soothing','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('rosmarinus-officinalis-leaf-extract','Rosmarinus Officinalis Leaf Extract','迷迭香叶提取物','迷迭香,海洋之露,Rosmarinus officinalis,Salvia rosmarinus,Rosemary Leaf Extract','84604-14-8(以供应商 COA 复核)','植物提取物','antioxidant,oil-control,soothing','主要成分方向是鼠尾草酸、鼠尾草酚与迷迭香酸。前两者是油溶性酚二萜,常被用作油相的抗氧化辅助,延缓不饱和油脂氧化酸败;迷迭香酸是水溶性多酚,多用于水相抗氧化配角与油痘线的清爽方向。它在配方里同时扮演「活性物」和「油脂保护剂」两种角色,选规格前必须先明确用途,因为两种用途对应的浓缩度、颜色与价格完全不同。','水/丁二醇提取物 0.5–2%;油溶抗氧化浓缩规格(以鼠尾草酸计)0.02–0.2%(公开配方学常见区间,非法规限值)','oil,balm,cream,lotion,serum,essence,stick','4.0–7.0(水溶规格)','1) 规格颜色差异是报价前必须确认的第一件事:未脱色规格呈深绿至棕黑,0.1% 就能把白色乳霜拉成灰绿;脱色脱味规格颜色浅、气味淡,但抗氧化能力通常同步下降,价格也不同。两种规格标签上往往是同一个 INCI,客户拿着未脱色的报价去要脱色的效果,是这条原料最常见的扯皮点。2) 与铁、铜离子形成有色络合物,深绿转棕黑;含铁氧化物颜料的彩妆基质与铜肽体系需谨慎,必须加螯合剂并做色泽加速。3) 油溶规格多以植物油或聚甘油酯为载体,直接投入水相会浮油,必须走油相或增溶。4) 与高浓度阳离子调理剂共用时,水溶部分可能造成轻微浑浊,深色发用产品影响不大,透明体系必须先测。5) 气味强:未脱味规格带明显草本药味,与清淡花香型香精正面冲突,做无香配方时是投诉高发点。6) 与皂基等 pH 大于 9 的强碱体系不宜,酚类快速氧化变褐。','酚二萜在高温与氧气下逐步失活,一般认为 80°C 以上长时间加热会显著削弱其油相保护能力,所以「当抗氧化剂用」时最忌与油脂一起长时间高温保温——那等于先让它自己消耗掉一半。见光变色明显,深色规格在透明包材中会持续加深;水溶规格 pH 超过 7 后褐变加快。还要提醒客户一句:它做油脂保护不是万能的,对玫瑰果油、月见草油、亚麻籽油这类高不饱和体系有帮助,但不能替代避光包材、氮气保护与螯合剂,三者要一起上。与生育酚常见协同使用,加上螯合剂后加速试验中的过氧化值上升通常更缓,但效果随油相组成变化很大,必须按实际配方跑加速数据,不要照搬原料商的通用曲线做承诺。','常规使用方向;注意同一原料在食品抗氧化与化妆品两条线都有使用,采购规格与用途口径要一致;以最新官方文本为准。','常规使用方向;若以配方抗氧化功能添加,需与安全评估中的用途描述一致;以最新官方文本为准。','常规使用方向;抗氧化叙述应限定在配方保护层面,不要外推为人体功效宣称;以最新官方文本为准。','常规使用方向,部分市场需补充植物来源与提取溶剂残留资料;以最新官方文本为准。','植物来源,通常可做 vegan;油溶规格需确认载体油为非动物来源,清真需供应商出具证明。','mid','1) 油溶抗氧化规格在油相降温阶段加入,建议 70°C 以下,不要在油相 85°C 保温时就投——最常见的错误就是「和油一起化开」。2) 水溶规格属后加料,降温 40°C 以下加入,高浓度时先用丁二醇或甘油预稀释。3) 收料环节是本条最大的现场风险:未脱色与脱色规格外观天差地别,标签上却可能只写同一个 INCI,进厂必须核对批号与供应商规格代号并分区存放,混料会直接导致整批色差报废。4) 未脱味规格的气味评估要在实际基质里做,不要拿空白基质定香型,否则香精加量会被迫上调,连带推高致敏物标示与成本。5) 深色提取物容易在管道、灌装嘴与滤芯残留染色,换线做浅色产品时必须加一道表活或溶剂清洗步骤,否则下一批出现零星色点。6) 水提规格偏酸,加完复测 pH 并记录。','antioxidant','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('aloe-barbadensis-leaf-juice','Aloe Barbadensis Leaf Juice','库拉索芦荟叶汁','库拉索芦荟,芦荟原汁,芦荟叶汁,Aloe barbadensis,Aloe vera,Aloe Vera Leaf Juice','85507-69-3(以供应商 COA 复核)','多糖','hydrating,soothing,barrier','主体是水,加上多糖(以乙酰化甘露聚糖为代表)、氨基酸、有机酸与少量矿物质。在配方里主要提供水相的亲肤感与轻微成膜保湿方向,常作为水相的一部分替代纯水,用来支撑「高含量芦荟」的产品叙事。真正决定表现的是规格而不是名字:原汁(1x)、浓缩液(10x/40x)与冻干粉复水三种形态,在固含量、粘度、气味、微生物背景与蒽醌背景上完全不同。','原汁型可占水相 5–50%;200:1 冻干粉复配常见 0.05–0.5%(公开配方学常见区间,非法规限值)','gel,toner,essence,lotion,cream,mask,serum','4.0–6.0','1) 高含量原汁把大量电解质带进配方,卡波姆与丙烯酸酯类增稠剂的增稠效率明显下降甚至直接塌陷。做「高含量芦荟凝胶」时不要硬加卡波,应改用黄原胶、结冷胶或耐电解质型合成增稠剂,这是打样阶段最常见的返工原因。2) 与阳离子调理剂共用时,芦荟中的阴离子多糖与有机酸会造成浑浊或絮凝,透明发用体系尤其明显。3) 与乙醇超过约 20% 混合会析出多糖,出现雾浊与絮状物,含醇爽肤水需先做澄清度试验。4) 自带的钙镁离子会加速部分抗氧化剂与维生素 C 衍生物降解,需要额外补螯合剂。5) 与氯化钠增稠的表活体系叠加,会把总电解质推过临界点,黏度曲线突然反转塌黏。','多糖在高温下解聚,粘度与滑感随加热时间同步下降;70°C 以上长时间保温后,原汁那点粘度基本消失——这就是「打样时滑、放大后不滑」最常见的原因,不是配方错了,是受热历程变了。见光与遇氧会让浅黄汁液变黄变褐并带轻微异味,含蒽醌背景(芦荟苷、芦荟大黄素)的规格褐变更快,颜色深浅可以当作规格精制程度的粗略线索。微生物是这条原料最现实的风险:高糖高氨基酸,是极好的培养基,原汁的初始菌与防腐负担远高于粉复水;而且原汁本身常自带防腐剂(如苯氧乙醇、山梨酸钾),这部分必须计入配方总防腐量并在成分表体现,漏算既是稳定性问题也是标签问题。原汁偏酸且批间波动,含它的配方每批都要复测 pH。','常规使用方向;需确认原料目录收录与原料安全信息码,浓缩液与粉体规格的 INCI 标示要与实际形态一致;以最新官方文本为准。','常规使用方向;蒽醌类背景相关的原料规格与安全评估资料需齐备;以最新官方文本为准。','常规使用方向;「纯芦荟」「99% 芦荟」类文案必须与实际配方与投料一致,否则构成误导风险;以最新官方文本为准。','常规使用方向;部分市场对植物原汁的进口检疫与微生物指标有额外要求;以最新官方文本为准。','植物来源,通常可做 vegan;需确认原汁自带的防腐剂与澄清助剂来源,清真需供应商出具证明。','low','1) 客户说「要 50% 芦荟」时,第一件事是问清他要的是标签上 Aloe Barbadensis Leaf Juice 的位次靠前,还是要真实的多糖含量。用 200:1 粉复配的还原汁在标签上同样成立,但粘度、气味、微生物负担与成本完全不同,这一层不在报价阶段说清,就是后期扯皮的源头。2) 原汁属后加料,降温至 40°C 以下加入,不要与油相一起高温乳化;若工艺上必须前加,提前告知客户会损失粘度与感官。3) 粉料先用少量常温水或甘油润湿打浆,再入主锅;直接撒粉必结团,团块被过滤网截留后实际加量低于配方,批间差异就是这么来的。4) 微生物控制要当成硬要求:原汁开桶后极易染菌,建议整桶用完不隔夜并留开桶记录;储罐与管道必须 CIP,冲一冲不算清洗。5) 防腐挑战必须用含芦荟的实际配方单独做,不能套用无芦荟版本的数据;高含量版本通常需要上调防腐或补螯合剂与多元醇辅助。6) 若客户对蒽醌背景有要求(部分品牌方会明确提低蒽醌规格),在采购规格书里写明检测项、方法与限值,并要求逐批 COA,不接受口头承诺。7) 高含量原汁体系粘度低、易起泡,灌装前静置消泡,否则装量不齐被判不合格。','hydrating','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('calendula-officinalis-flower-extract','Calendula Officinalis Flower Extract','金盏花花提取物','金盏花,金盏菊,万寿菊(易混,非同种),Calendula officinalis,Pot Marigold','84776-23-8(以供应商 COA 复核)','植物提取物','soothing,barrier,antioxidant','成分方向以三萜类(以法地醇酯类 faradiol esters 为代表,另含金盏花皂苷等三萜皂苷)、类黄酮与类胡萝卜素为主,常用于婴童护理、剃须后与敏感线的安抚型配方,为「温和低刺激」的产品叙事提供骨架。市面常见两种规格:水或丁二醇提取物,与金盏花油浸提物(浸泡油)。两者的颜色深浅、加量区间与配伍规则完全不同,选料时必须先定规格再谈加量。','水溶提取物 0.5–3%;油浸提物 1–10%(公开配方学常见区间,非法规限值)','cream,lotion,balm,oil,mask,gel,essence,stick','4.5–7.0','1) 颜色是这条原料的头号坑:类胡萝卜素带来的黄至橙黄在白色乳霜里极其明显,1–3% 就足以把纯白基质拉到米黄或浅杏色,再叠加二氧化钛也压不回纯白,只会变成发灰的白。要做「纯白婴儿霜」的客户必须在打样前看到实物色卡,光看文字描述一定对不齐。2) 菊科交叉致敏:与洋甘菊、山金车、蓍草同为菊科,敏感与婴童线不建议在同一配方里堆叠多种菊科提取物。3) 遇铁离子显色加深,含铁颜料体系需加螯合剂。4) 油浸提物会稀释油相极性并带入自身甘油三酯,与高含量硅油或高极性酯共用时改变乳化平衡,原本稳定的配方在提高加量后出现析油,这类故障常被误判为乳化剂问题。5) 与高浓度过氧化物等强氧化体系不兼容,类胡萝卜素快速脱色。6) 提取物带电解质,与卡波姆体系叠加会降黏,需要复配增稠。','类胡萝卜素见光极易褪色:透明包材中的黄色会在数周到数月内明显变淡,客户常常误判为「活性没了」,实际是色素降解,所以质量标准里应给出色泽范围而不是单点色。油浸提物除了褪色,载体油本身也会氧化产生哈味,油浸规格必须搭配生育酚类抗氧化并避光。热稳定性一般,70°C 以上保温会加速褪色与气味变化,水提物按后加处理。pH 偏碱条件下黄酮变色加深,建议锁在 4.5–6.5。提取物带糖与多糖背景,防腐负担上升,挑战试验必须带料做。','常规使用方向;需确认原料目录收录与原料安全信息码,婴童类产品另有更严的整体要求;以最新官方文本为准。','常规使用方向;婴童与敏感定位产品的安全评估资料要求更高;以最新官方文本为准。','常规使用方向;安抚类文案需避免疾病与创伤修复暗示;以最新官方文本为准。','常规使用方向,部分市场对婴童产品与植物原料有额外备案要求;以最新官方文本为准。','植物来源,通常可做 vegan;油浸提物需确认载体油为非动物来源,醇提规格的清真认定需另行评估并要求供应商出具证明。','mid','1) 水提物降温 40°C 以下后加并做 1:5 预稀释;油浸提物在油相降温段加入(建议 70°C 以下),不要跟着油相一起高温保温。2) 色泽管理是本条的核心工作:进料按色泽范围验收,客户确认样阶段同时提供最深与最浅两个批次的样品并让客户签字。还要提前告知一件事——放大生产的受热时间比小样长,成品通常比小样更淡一点,不提前说,客户一定按小样判色差。3) 油浸提物经冷藏或冬季运输后常出现浑浊或蜡质析出,使用前需在 40–45°C 缓慢回温并充分搅匀再取用,否则上下层浓度不同,批间加量不准。4) 婴童线建议向供应商索取农残与重金属数据,并明确提取溶剂:不少品牌方会直接拒绝醇提规格用于婴童产品,这一条要在选料阶段问,不要等配方定稿。5) 原料自带草本甜香,做无香配方时必须在实际基质里嗅辨评估。','soothing','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('avena-sativa-kernel-extract','Avena Sativa Kernel Extract','燕麦仁提取物','燕麦,燕麦仁,燕麦提取物,Avena sativa,Oat Kernel Extract','未确认','多糖','soothing,barrier,hydrating','作用方向来自 β-葡聚糖等多糖、燕麦生物碱(avenanthramides)与少量谷物脂质。多糖在皮肤表面形成含水膜,带来即时的柔滑与干燥紧绷缓解方向;燕麦生物碱则是抗氧化与安抚叙事的来源。它是敏感与干燥线里客户接受度最高的名字之一,但从工程角度看,它更像一个功能性的增稠与成膜原料,加量提高后先改变的是流变而不是肤感。','液体提取物 0.5–3%;粉体规格通常 0.1–1%(公开配方学常见区间,非法规限值)','cream,lotion,mask,gel,essence,foam,balm','4.5–7.0','1) 含淀粉与多糖,与高浓度电解质共存或在 pH 低于约 3.5 的强酸体系中会降黏甚至析出,所以不适合往高浓度果酸、水杨酸类去角质体系里高加量塞。2) 与阳离子调理剂在某些配比下形成复合物,体系突然变稠甚至结块,发用体系必须先做浓度梯度试验。3) 与乙醇超过约 20% 共存会析出多糖,出现雾浊与沉淀。4) 与含蛋白酶、淀粉酶的原料(部分酵素粉、木瓜蛋白酶)同处一个体系会被逐步降解,表现为货架期内黏度持续下降,这类故障往往拖到三个月加速末期才暴露。5) 与强氧化性体系不兼容。6) 高多糖淀粉背景会吸附并削弱部分防腐剂的效率,尤其是有机酸类,防腐设计不能照抄空白基质的方案。','多糖在高剪切与长时间高温下解聚,黏度与滑感下降,这就是「加量越高越难放大」的根源:小样均质三分钟和大罐均质十五分钟,得到的是两个流变曲线。淀粉背景在低温储存时可能出现回生现象,表现为体系变粗糙、出现细微颗粒感或轻微分层,所以冷冻—解冻循环测试对这条原料是必做项而不是可选项。微生物方面,淀粉与多糖是高营养基质,防腐负担明显上升,含它的配方必须单独做防腐挑战,并同步关注车间水系统与储罐卫生。见光影响相对小,但含燕麦生物碱的规格久置会轻微变黄。pH 向碱性漂移会加速多糖水解并带出谷物气味。','常规使用方向;注意区分液体提取物与粉体的不同 INCI 与目录收录情况;以最新官方文本为准。','常规使用方向;麸质与谷物过敏原信息按供应商文件如实传递;以最新官方文本为准。','常规使用方向;若客户希望走胶体燕麦对应的非处方皮肤保护剂路径,必须改用对应的 INCI 与规格并另行做合规评估,不能用本原料顶替;以最新官方文本为准。','常规使用方向;部分市场对谷物来源原料有进口检疫要求;以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明,并确认提取溶剂与载体。','low','1) 加量上限是工程边界不是活性边界:液体提取物超过约 3–5%(视固含量)后,黏度与稳定性的负面变化会跑赢感官收益,典型故障是放大后表面出现细颗粒或轻微析水。要跟客户讲清「再加也不会更舒缓,只会更难做」。2) 粉体规格必须先在冷水或甘油中打浆分散,再缓慢入锅并适度加热溶胀;直接撒进热水会瞬间糊化结团,团块过滤时被截留,导致实际加量低于配方,还会在滤网上越积越多。3) 液体规格按后加处理,降温 40–45°C 以下;需要溶胀的粉料在辅锅单独完成后再并入主锅,不要在主锅里边升温边撒粉。4) 过滤环节要提前评估:高多糖体系过 100 目以上细网时压力上升明显,放大生产要预留过滤时间,否则灌装节拍被整体拖慢。5) 麸质问题不能靠推理:客户若要 gluten-free 标示,必须由供应商出具检测数据,燕麦本身不含麸质但种植与加工环节交叉污染很常见。6) 关键区分:Avena Sativa Kernel Extract 与 Avena Sativa Kernel Flour(胶体燕麦)是两个不同的 INCI,后者在美国另有一套口径,报价、宣称与合规路径都不能混用。客户说「要燕麦」时,先问是哪一个再报价。','barrier-repair','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('arctium-lappa-root-extract','Arctium Lappa Root Extract','牛蒡根提取物','牛蒡,牛蒡根,东洋参(俗称),Arctium lappa,Burdock Root Extract','未确认','植物提取物','oil-control,soothing,conditioning','含菊粉类多糖与咖啡酰奎宁酸类多酚(绿原酸方向),水溶性好,常用于头皮清爽、油痘辅助以及「控油不紧绷」的配方叙事,在配方里通常做配角而非主角。需注意木脂素(牛蒡子苷/牛蒡子苷元)主要富集在果实牛蒡子,根提取物中含量低,不要按木脂素指标去选根提取物。它在水剂中几乎不改变外观与黏度,是少数可以直接顶到较高加量而不引起物性变化的植提之一;真正限制它加量的不是配伍,是气味。','0.5–3%(公开配方学常见区间,非法规限值)','toner,essence,serum,gel,foam,lotion,mask','4.0–7.0','1) 气味是最实际的配伍问题:带明显的土腥与根茎类药味,1% 以上在无香或淡香体系里就能被明确闻出来,与柑橘、清爽花香型香精正面冲突。常见连锁反应是香精加量被迫上调,进而推高致敏物标示与香精成本,最后为了掩盖气味重新开香型。做无香配方时,要么降加量,要么选脱味精制规格,要么直接换料,这个判断要在报价前做。2) 多酚遇铁离子显色发暗,含铁氧化物颜料或使用非 316L 设备时问题明显。3) 与阳离子调理剂可能出现轻微浑浊,透明头皮水体系必须先做小试。4) 与高浓度乙醇共存时,菊粉类多糖可能析出造成雾浊,醇量高的头皮水要跑低温澄清度测试。5) 与其它高电解质植提叠加时,会共同拉低卡波姆类增稠剂的效率。','多酚见光遇氧变色,浅棕色水提物在透明瓶中持续加深;pH 偏碱时褐变加快,建议锁在 4.5–6.0 并配螯合剂。菊粉类多糖是易被利用的碳源,微生物风险高于平均水平的植提,防腐挑战必须带料做,不能用无此原料的基质数据外推。加热耐受尚可,但长时间高温保温会同时加深颜色与放大气味,按后加处理。低温储存可能出现细微沉降,属多糖与不溶物析出,使用前搅匀即可;若客户要求成品「绝对澄清」,应在采购环节直接选精制或超滤规格并写进规格书,不要靠成品端过滤补救。','常规使用方向;需确认原料目录收录与原料安全信息码,并注意其在传统药材语境下的宣称边界;以最新官方文本为准。','常规使用方向;需提供植物部位与提取工艺资料以支持安全评估;以最新官方文本为准。','常规使用方向;头皮与油痘相关文案需避免疾病治疗暗示;以最新官方文本为准。','常规使用方向,部分市场对植物根类原料有进口与备案资料要求;以最新官方文本为准。','植物来源,通常可做 vegan;醇提规格的清真认定需另行评估,并要求供应商出具证明。','low','1) 按后加料处理,降温 40°C 以下加入,先做 1:5 预稀释再沿桶壁入锅。2) 气味必须在实际基质里评估,不能只闻原料本身——稀释进基质后气味特征会变,典型情况是「原料闻着还行,做进产品被客户投诉」。建议在客户确认样阶段同时送含它与不含它的两个版本,让客户自己闻过再定。3) 如果产品定位是无香,在报价前就要把这条原料对香精方案的连带影响讲清楚,避免后期为掩盖气味重新开香型带来的时间与成本损失。4) 深色规格会在管道与灌装嘴残留,换线做浅色产品要加清洗步骤。5) 进料时务必确认提取溶剂与固含量:同一个 INCI 下,水提、醇提与丁二醇提的颜色、气味和有效物含量差异极大,不同批次混用会直接体现在成品气味上。6) 加完复测 pH 并记录。','oil-control','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('crithmum-maritimum-extract','Crithmum Maritimum Extract','海茴香提取物','海茴香,海蓬子(俗称易混),岩海茴香,Crithmum maritimum,Sea Fennel,Rock Samphire','未确认','植物提取物','brightening,antioxidant','海茴香是生长在海岸带岩缝中的伞形科植物,常见商品形态是植物干细胞培养提取物或精制提取物,活性方向来自多酚与有机酸类。欧洲高端线常把它用在肤色均匀度与更新节奏的产品叙事上。它是典型的低添加、高单价原料,在配方里几乎不改变体系的物性,所以决定它有没有意义的是供应商标称的活性物含量与对应推荐区间,而不是配方表上出现没出现这个名字。','0.1–2%(不同规格活性物含量差异极大,须按供应商标称含量换算;公开配方学常见区间,非法规限值)','serum,essence,cream,lotion,mask','4.5–7.0(以供应商规格书为准)','1) 不同供应商的「海茴香」载体形态差异极大:有的以丁二醇或甘油为溶剂,有的做成脂质体或其它包裹体系。包裹型最怕高剪切与高浓度表活,均质过头或加入表活后包裹结构被破坏,活性提前释放,外观上可能出现浑浊或颗粒。选料时必须先拿到规格书确认形态,再决定加料工序。2) 与高浓度电解质、强离子体系共存时,脂质体规格容易聚集絮凝。3) 多酚遇铁、铜离子显色,需配螯合剂并核对设备材质。4) 与乙醇超过约 15–20% 共存会破坏包裹结构,清爽型醇基精华应改用非包裹规格。5) 与 pH 低于 3.5 的高浓度果酸体系或强碱体系共存,活性与外观都不可预期,必须先做兼容小试再定配方。','低添加不等于低风险,恰恰相反:因为加量小,任何降解都直接把有效成分推向接近零,而外观上完全看不出来。所以这条原料只能靠加速试验加供应商稳定性数据双重把关,肉眼判断在这里没有意义。多酚见光遇氧降解,建议避光包材并配螯合剂。包裹型规格对温度敏感,通常要求 40°C 以下加入,超温会出现粒径变化甚至破乳。部分规格自带防腐体系,配方的总防腐设计必须把这部分计入,否则既可能超量也可能在成分表上漏标。原料本身常有储存温度要求(冷藏为多),仓储不达标会在进厂前就损失活性,这部分损失不体现在任何检测报告上。','需先确认该原料是否已收录于国内已使用原料目录并具备原料安全信息码;未收录则涉及新原料路径,项目周期与成本要重新评估;以最新官方文本为准。','欧洲高端线常见使用方向;植物干细胞培养类规格的来源与工艺安全评估资料需齐备;以最新官方文本为准。','常规使用方向;宣称需严格限定在化妆品范围内;以最新官方文本为准。','常规使用方向;部分市场需提供植物来源、培养工艺与溶剂资料;以最新官方文本为准。','植物来源,通常可做 vegan;培养基成分与载体来源需向供应商书面确认,清真需出具证明。','high','1) 剂量逻辑必须先和客户讲清楚,这比任何工艺细节都重要:这类原料的意义在于落在供应商推荐区间内的活性物浓度,不是配方表上有这个名字。如果客户预算只允许加到推荐下限的十分之一,应当直接告诉他「这个加量下它只是标签成分」,由客户决定保留还是换料,并把这次沟通留痕。含糊过去,后面出功效争议时工厂要背。2) 最后加入,降温至 35–40°C 以下,低剪切搅拌 5–10 分钟即可,不要再过均质。3) 单价高,称量误差的成本被放大:小批量建议用更高精度天平并双人复核,称量器皿上的残留要用配方内溶剂洗入锅中,不要直接冲掉。4) 进料必须核对活性物含量指标,不同批次的标称含量差异会直接改变配方加量设计;同时索取冷链或阴凉运输记录。5) 供应商通常带商标名与专利叙事,签约前确认宣称使用权限与范围,避免客户直接把供应商宣传语印到包装上,风险落回工厂。','brightening','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('arnica-montana-flower-extract','Arnica Montana Flower Extract','山金车花提取物','山金车,阿尼菊,雪山金莲花(俗称易混),Arnica montana,Arnica,Leopard''s Bane','未确认','植物提取物','soothing,antioxidant','含倍半萜内酯(以山金车内酯类为代表)、黄酮与酚酸。传统上用于身体与运动后护理方向的按摩类产品,配方里常与薄荷醇、樟脑等清凉剂或按摩油基质搭配,支撑「活力舒缓」的产品叙事。作用方向以局部使用后的舒适感为主,不做任何医疗用途表述,这条原料的文案边界比配方设计更需要盯紧。','0.5–3%(公开配方学常见区间,非法规限值)','cream,lotion,gel,balm,oil,stick','4.5–7.0','1) 菊科交叉致敏:与洋甘菊、金盏花、蓍草同科,叠加会放大菊科敏感人群风险。身体与运动线特别爱堆草本,这里要克制,一个配方保留一种菊科来源就够。2) 倍半萜内酯本身是已知的接触致敏方向,与高加量丙二醇、乙醇等渗透促进剂,或与果酸、水杨酸类去角质成分同用,刺激是叠加的,不建议放进酸类产品或以破损、术后皮肤为定位的产品。3) 与薄荷醇、樟脑、水杨酸甲酯等清凉剂常见共用,但这些成分会一起推高整体刺激与气味负担,必须整体评估而不是逐个评估——单看每个都合规,合起来仍可能不耐受。4) 多酚遇铁离子显色。5) 醇提规格与卡波姆体系相冲,高醇量下卡波稀化,按摩凝胶应改用非离子增稠或耐醇型聚合物。','黄酮与多酚见光遇氧变色,黄绿色提取物会向棕色漂移;透明按摩凝胶是最容易暴露这个问题的剂型,建议避光包材或深色瓶。pH 偏碱会加速变色与活性降解,建议锁在 4.5–6.5。高温保温会损失挥发性成分与部分内酯,按后加处理,建议 45°C 以下加入。油浸提物规格要连同载体油一起考虑氧化,搭配生育酚并避光。还有一个常被混淆的点:与清凉剂共用的体系需要单独测挥发损失,薄荷醇在开口保温阶段挥发明显,成品清凉感不足往往是这个原因,不是山金车的问题,但现场经常一起被追责。','需确认原料目录收录与原料安全信息码,并特别注意其在传统药材语境下的宣称边界;以最新官方文本为准。','部分市场对山金车的使用部位与浓度存在额外关注,化妆品用途需由安全评估人逐案确认后再定加量;以最新官方文本为准。','化妆品用途属常规方向,但与之相关的传统用法叙述极易被理解为药品宣称,文案必须经法务复核;以最新官方文本为准。','各市场对山金车的态度差异明显,需逐个目标市场核对原料准入与宣称口径;以最新官方文本为准。','植物来源,通常可做 vegan;醇提规格的清真认定需按乙醇来源与残留另行评估,并要求供应商出具证明。','mid','1) 按后加料处理,降温 40–45°C 以下加入,先做预稀释再入锅。2) 出海项目必须在立项阶段就锁定目标市场清单再决定加量:不同市场对山金车的使用部位与浓度态度不一致,部分市场把其制剂放在传统草药或药品范畴。等包材开版、印刷稿定了才发现要改配方,损失的是整套包材和上市窗口,这是这条原料最贵的一个坑。3) 含它的配方建议走完整的刺激性与致敏性评估路径,并保留供应商提供的倍半萜内酯含量数据备查;婴童线与面部敏感线不建议使用。4) 气味明显,做无香或淡香配方需在实际基质中评估。5) 与高油含量按摩基质共用时要更保守:油相会延长其在皮肤上的驻留时间,刺激叠加风险随之上升,同样的加量在水基和油基里不是一回事。6) 加完复测 pH。','soothing','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('salix-alba-bark-extract','Salix Alba Bark Extract','白柳树皮提取物','白柳,白柳树皮,柳树皮提取物,Salix alba,White Willow Bark Extract','84082-82-6(以供应商 COA 复核)','植物提取物','oil-control,soothing,antioxidant','标志性成分是水杨苷(salicin),另有多酚与单宁。这里必须说清一件事:水杨苷是糖苷,不是水杨酸,两者在结构、酸性和在配方中的行为上都不同;商品化提取物中的水杨苷含量通常很低,而且在皮肤表面并没有可靠的转化路径把它变成足量的水杨酸。因此在配方里,它更接近一个温和的多酚型控油与舒缓配角,而不是酸类去角质活性物。','0.5–3%;若规格标注水杨苷含量,按供应商推荐区间执行(公开配方学常见区间,非法规限值)','toner,essence,serum,gel,cream,mask,foam','4.0–6.5','1) 含单宁,与阳离子调理剂、水解蛋白、多肽类会絮凝或产生沉淀,机理与金缕梅同类。含肽精华里加白柳树皮是这一库里最高频的翻车组合之一,而且经常是灌装完成、静置几天后才出现絮状。2) 多酚遇铁离子显色发暗,必须配螯合剂并保证 316L 设备与器具。3) 与高浓度锌盐、铜盐共用变色。4) 与真正的水杨酸(BHA)叠加时要注意:整个配方的酸负担与刺激来自水杨酸本身,不要因为「都是柳树来的」就在刺激评估上放松,这是心理上的坑不是化学上的坑。5) 与皂基等强碱体系不宜,多酚快速氧化变褐。6) 与高醇体系相对相容,但颜色会加深更快。','多酚与单宁见光遇氧褐变,水提物由浅黄棕向深棕漂移,pH 越高越快,建议锁在 4.0–5.5 并加螯合剂,配深色或避光包材。另一个容易被忽略的点:水杨苷在酸性与高温条件下可能水解,长时间高温保温会改变成品的检测值。如果客户是按水杨苷含量验收的,工艺参数(加料温度、保温时长、搅拌方式)必须固定并写进批记录,否则每批检测值会飘,而工厂拿不出解释。加料温度建议 45°C 以下。透明包材里的色变是投诉重灾区,方案阶段就该劝客户用深色瓶。','常规使用方向;需确认原料目录收录与原料安全信息码,并避免与水杨酸相关的功效表述混用;以最新官方文本为准。','常规使用方向;不可借用水杨酸的相关口径来支撑本原料的宣称;以最新官方文本为准。','常规使用方向;若产品文案暗示其等同于水杨酸类去角质活性,存在被视为不实宣称或药妆用语的风险,必须经法务复核;以最新官方文本为准。','常规使用方向;部分市场对功效宣称有备案与证据要求,「天然水杨酸」类表述风险更高;以最新官方文本为准。','植物来源,通常可做 vegan;醇提规格的清真认定需另行评估,并要求供应商出具证明。','low','1) 这条原料最大的风险不在工艺而在宣称:客户经常把它当「天然水杨酸」「植物 BHA」来卖。实际提取物的水杨苷含量低,水杨苷也不等于水杨酸,拿它去支撑「可替代水杨酸去角质」既缺乏依据也容易被平台和监管盯上。工厂侧的正确做法是在报价单与技术资料里写明所用规格的水杨苷含量(或明确注明未检测),并书面说明它不等同于水杨酸,把宣称的决定权和沟通记录都留痕。2) 客户如果确实要去角质表现,直接用水杨酸或其它酸类并按目标市场规则设计,不要靠提高白柳树皮加量硬凑——加量上去只会带来颜色加深和单宁配伍问题,去角质表现不会跟着上来。3) 按后加料处理,降温 40°C 以下,先做 1:5 预稀释。4) 与含肽、含阳离子调理剂的配方同锅前必须小试并静置观察 48–72 小时;放大后剪切更强,絮凝表现比小样更明显,小样勉强通过不代表能放大。5) 单宁会染管道与滤芯,做浅色产品前的换线要加清洗步骤。6) 提取物偏酸会把体系 pH 拉低,加完复测并回调,记录进批记录。','oil-control','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('bifida-ferment-lysate','Bifida Ferment Lysate','二裂酵母发酵产物溶胞物','二裂酵母溶胞产物,双歧杆菌发酵溶胞物,Bifidobacterium','未确认','发酵物','barrier,soothing,repair,hydrating','通过发酵后对菌体破壁(溶胞)得到的可溶性组分,含氨基酸、寡肽、核酸片段与多糖。在配方中作为水相功能料存在,常用于屏障支撑与舒缓方向,也是客户询单中常被点名的发酵类成分之一。它本身不提供活菌,进入配方后按普通水溶性功能料对待。','1–10%(公开配方学常见区间,非法规限值);以发酵叙事为卖点时常见 2–5%','serum,essence,toner,lotion,cream,mask,gel','4.5–6.5','与高浓度阳离子表活及阳离子调理剂(季铵盐类)同用,易与其中带负电的多糖与蛋白组分形成复合物,水剂里表现为丝状浑浊、絮状物或挂壁。强氧化性体系(高浓度过氧化物、部分过硫酸盐)会加速蛋白与核酸片段降解,颜色向深黄漂移。与乙醇含量超过约 20% 的体系同用有析出风险,必须先做澄清度小试。pH 低于 3.5 的强酸体系(高浓度果酸、纯维生素C水剂)下容易褐变并伴随气味加重。与钙、镁、铁等多价金属离子共存会交联起浑或异常增稠,用硬水配制时尤其明显。','耐热性差是它最突出的短板,长时间处于 60℃ 以上会明显褐变、气味变重,功能组分也随之损失,所以工艺上必须后段低温加入。见光会缓慢加深颜色,建议使用避光包材并配抗氧组分。遇氧与痕量金属会协同氧化,常规做法是配螯合剂(EDTA 类或植酸)并控制搅拌带入的空气。pH 向酸漂移会加重褐变与异味,向碱漂移到 7 以上则更利于微生物滋生。它本身是优质的微生物营养源,防腐余量必须比同类水剂留得更足,并做完整的防腐挑战试验。','属国内常用发酵类原料,使用前按已使用原料目录与备案要求核对原料来源、规格与安全信息;以最新官方文本为准。','常规使用方向,需完成安全评估并按当地成分申报流程处理,微生物来源须有菌株与灭活工艺说明;以最新官方文本为准。','常规使用方向,重点复核标签成分名写法与宣称边界,按目标市场规则复核;以最新官方文本为准。','日韩市场对发酵类原料接受度高,东南亚及其它市场按各自原料目录与进口要求逐一复核;以最新官方文本为准。','微生物发酵来源,培养基不含动物源时通常可做 vegan,须供应商出具培养基声明;清真需供应商出具证明,并注意工艺中是否使用乙醇。','mid','乳化完成、料温降到 40℃ 以下(建议 35–38℃)再加入,禁止随油相或水相一起过热。加料前先用配方中的部分水相或多元醇稀释成预混液,在低速搅拌下缓慢加入,避免局部高浓度结块。搅拌以低速短时为准,过度剪切会把空气打进料体加速氧化。pH 调节应在它加入之前完成,避免加完后再用碱剂造成局部冲击。放大生产的典型坑:大罐从 80℃ 降到 40℃ 的时间远长于小试,若沿用小试的加料时间点,实际加料时料体仍在高温段,批次间颜色和气味差异往往由此而来,必须以罐内实测温度而非时间表为准。不同供应商的固含、颜色与特征气味差异大,换供应商必须重做稳定性与香精配伍。','barrier-repair','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('galactomyces-ferment-filtrate','Galactomyces Ferment Filtrate','半乳糖酵母样菌发酵产物滤液','半乳糖酵母滤液,GFF,酵母样真菌发酵滤液,Galactomyces','未确认','发酵物','hydrating,brightening,barrier,soothing','酵母样真菌发酵后经过滤得到的水相滤液,含氨基酸、有机酸、小分子维生素类与微量多糖。配方里常以较高比例替代部分配方用水,做出清爽不粘的水相基底,常用于水润与提亮方向的化妆水和精华设计。','5–90%(公开配方学常见区间,非法规限值);做「高含量」卖点时常见 30% 以上','toner,essence,serum,mask,lotion,gel','3.8–6.0','本身偏酸并含有机酸,大比例替代配方水会把体系 pH 整体拉低,与不耐酸的活性(部分肽类、某些植物提取物、部分防腐体系)同用必须先测终点 pH 再定配方。与阳离子调理剂共用易絮凝,水剂里出现浑浊或缓慢沉降。与高浓度电解质(氯化钠及各类盐)叠加会使卡波类增稠体系粘度骤降。含铁、铜等痕量金属会催化其中酚类与糖类组分氧化,颜色发黄发暗,不加螯合剂几乎必然出现色漂。与含硫醇类原料或强还原剂同用会加重气味问题。','最典型的货架期问题是气味漂移与澄清度漂移:高添加量配方在加速试验期间可能出现酵母味变酸变重、液体由清转微浑,具体出现时间随添加量、pH 与包材差异很大,必须按本配方实测并逐周记录,不能套用经验值。','发酵类常用原料,按已使用原料目录与备案要求核对来源与规格,高添加量配方注意随附完整的原料安全信息;以最新官方文本为准。','常规使用方向,需完成安全评估与成分申报,微生物来源须提供菌株与工艺说明;以最新官方文本为准。','常规使用方向,按目标市场规则复核标签写法与宣称边界;以最新官方文本为准。','日韩市场认知度高,东南亚及其它市场按各自原料目录与进口要求逐一复核;以最新官方文本为准。','微生物发酵来源,培养基不含动物源时通常可做 vegan,须供应商出具培养基声明;清真需供应商出具证明。','mid','属水相料,可在水相配制阶段加入,但若配方需要长时间高温分散增稠剂,建议留到降温至 50℃ 以下再补入,减少热致气味。高添加量时不要指望后期用碱大幅回调 pH,应以它打底后逐步微调,一次性加碱会造成局部浑浊。与卡波体系配合时先中和体系再加它,或分批加入并观察粘度跌落幅度。灌装前必须过滤并留样看澄清度。包材匹配是采购最担心的一环:高含量配方建议按玻璃、PET、PP 以及带内涂层铝管分材质做相容性试验,重点看气味吸附、变色,以及酸性体系是否侵蚀内涂层。放大生产要按批留样,并在规格中写明可接受的颜色与气味范围。','brightening','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('saccharomyces-ferment-filtrate','Saccharomyces Ferment Filtrate','酵母发酵产物滤液','酵母滤液,酿酒酵母发酵滤液,Saccharomyces cerevisiae','未确认','发酵物','hydrating,barrier,soothing,conditioning','酿酒酵母发酵后过滤得到的水相滤液,主要含氨基酸、多肽片段、B 族维生素类小分子和寡糖。它属于发酵产品线里最基础的一类水相料,在配方中承担水相保湿与肤感柔润的角色,也常作为发酵概念的底料与其它发酵料复配。','1–20%(公开配方学常见区间,非法规限值)','toner,essence,serum,lotion,cream,mask','4.0–6.5','与阳离子表活和阳离子调理剂共用易絮凝。与高浓度乙醇同用可能析出多糖类组分,呈雾状浑浊。与强氧化剂、高浓度过氧化物同用会使颜色迅速加深。与多价金属离子共存会异常增稠或起浑。pH 低于 3.5 长期储存会加速褐变并放大酵母味。含还原糖较高的批次与含氨基、胺基的原料(部分氨基酸衍生物、乙醇胺类中和剂)在高温下更容易走褐变路线,成品逐月发黄。','这一支最需要单独提醒的是来料一致性:不同供应商的固含可能相差数倍,颜色深浅与气味强度也完全不同,同一个 INCI 名底下可能是浓度差异很大的东西,具体数值以来料 COA 与干物质实测为准,直接按百分比换料会导致气味、颜色、粘度同时改变。','常用发酵类原料,按已使用原料目录与备案要求核对来源与规格;以最新官方文本为准。','常规使用方向,需完成安全评估与成分申报,微生物来源须提供菌株与工艺说明;以最新官方文本为准。','常规使用方向,按目标市场规则复核标签与宣称边界;以最新官方文本为准。','日韩及东南亚普遍使用,按各自原料目录与进口要求逐一复核;以最新官方文本为准。','微生物发酵来源,培养基不含动物源时通常可做 vegan,须供应商出具培养基声明;清真需供应商出具证明,并确认工艺中的乙醇使用情况。','low','建议 45℃ 以下加入,能后加就后加。换供应商或换批次之前,先索取固含或干物质含量、颜色范围与气味描述,并做一次并行小试(同配方两批料体对照放置四周),不要只看 COA 合格就直接上线。若两家固含相差一倍,不能按等体积替换,应按固含折算后再重新调香、调色并复测粘度。大罐生产先做预混稀释再入罐,避免局部浓度过高结团。含此料的配方灌装前应过滤,个别批次带入的细微悬浮物在成品里很容易被客户误判为「长东西」。','hydration','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('lactobacillus-soybean-ferment-extract','Lactobacillus/Soybean Ferment Extract','乳酸杆菌/大豆发酵产物提取物','乳酸菌大豆发酵提取物,发酵豆提取物,Glycine max,Lactobacillus','未确认','发酵物','barrier,soothing,antioxidant,hydrating','以大豆为底物、经乳酸杆菌发酵后提取的水相料,发酵过程会把部分大豆大分子转化为更小的肽与氨基酸,并改变异黄酮类的存在形态。配方里同时落在草本植物基与发酵后生元两条叙事上,常用于屏障支撑与舒缓方向,是植物基发酵里客户认知度较高的一支。','0.5–5%(公开配方学常见区间,非法规限值)','serum,essence,toner,lotion,cream,mask','4.0–7.0','含酚类与异黄酮类组分,与铁、铜离子接触会显色变深,严重时呈灰绿,必须配螯合剂。与强氧化剂、高浓度过氧化物同用会褪色或异常变色。与阳离子体系同用可能絮凝。与高浓度阴离子表活在清洁类配方里可能出现浑浊或沉降,做洗类前必须单独试配。pH 高于 8 的碱性体系下颜色加深、豆腥气味回归。与高浓度乙醇同用需先测溶解极限。','见光与遇氧都会推动颜色向深黄、深棕漂移,透明包材里最直观。高温大幅加速变色。pH 向碱漂移会同时带来变色与气味回升。常见防护做法:pH 控制在偏酸区间、加螯合剂、配水溶性抗氧组分、选避光包材、控制乳化搅拌带入的空气。发酵料营养丰富,防腐挑战必须做完整版,不能沿用同厂其它配方的防腐方案。','按已使用原料目录与备案要求核对来源与规格,大豆来源与提取工艺需在原料资料中说明;以最新官方文本为准。','常规使用方向,需完成安全评估与成分申报;大豆来源建议保留过敏原与来源说明文件备查;以最新官方文本为准。','常规使用方向,大豆来源在下游沟通中可能涉及过敏原标示需求,按目标市场规则复核;以最新官方文本为准。','日韩接受度高,部分市场对大豆来源与转基因议题关注度较高,按各自要求逐一复核;以最新官方文本为准。','植物底物加微生物发酵,通常可做 vegan,须供应商出具培养基与助剂声明;清真需供应商出具证明。','mid','后段加入,建议料温 40–45℃ 以下。粉体形态必须先在水或多元醇中完全溶解、静置排净气泡再入罐,直接撒入会结团且后续搅不开。液体形态要留意来料颜色的批次差异,深色批次会把整体料体拉黄,浅色或透明配方需要按颜色分级采购并在规格里写明色度上限。大豆来源要在过敏原沟通上主动留一句:虽然是提取物、蛋白残留通常极低,但下游品牌方在标注与消费者沟通上可能需要声明大豆来源,建议在规格书中明确原料来源并向供应商索取残留蛋白检测与来源说明。若下游市场关注转基因议题,应提前取得大豆原料来源文件。','barrier-repair','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('saccharomyces-rice-ferment-filtrate','Saccharomyces/Rice Ferment Filtrate','酵母/大米发酵产物滤液','米发酵滤液,酒粕发酵滤液,Oryza sativa,Saccharomyces','未确认','发酵物','hydrating,brightening,barrier,soothing','以大米为底物经酵母发酵后过滤得到的水相滤液,含氨基酸、有机酸、糖类与米源小分子。它是东亚「米发酵」叙事的核心原料,配方中主要承担水相保湿与肤感调理,常见于化妆水、精华与面膜液。','1–20%(公开配方学常见区间,非法规限值);做叙事卖点时可更高,但需重新评估气味与澄清度','toner,essence,serum,mask,lotion,gel','4.0–6.0','与阳离子体系同用絮凝。与高浓度乙醇同用会析出糖类与多糖组分。与铁离子接触显色发暗。与强氧化剂同用变色。与碱剂局部高浓度接触会立即加深颜色,调 pH 时必须稀释后缓慢滴加。米发酵料通常含还原糖,与含氨基、胺基的原料(部分氨基酸、乙醇胺类中和剂、部分肽)在高温或长期储存下更容易走褐变路线,导致成品逐月变黄。','两个绕不开的现实:一是特征气味(米酒、酒粕味)明显,二是天然带微黄色。透明水剂里这两点几乎藏不住,配方设计必须提前取舍——要么接受并把它讲成产品特征,要么降低添加量并配合掩盖香与微量调色。高温加速黄变与气味加重;见光加深颜色;pH 向碱漂移会同时放大气味与色变。防护做法:加螯合剂、控制溶氧、用避光包材、pH 锁在 4.5–5.5,加速试验必须做满并每周记录颜色与气味。防腐余量要足。','发酵类常用原料,按已使用原料目录与备案要求核对来源与规格;以最新官方文本为准。','常规使用方向,需完成安全评估与成分申报,谷物来源建议保留来源说明备查;以最新官方文本为准。','常规使用方向,按目标市场规则复核标签与宣称边界;以最新官方文本为准。','日韩市场叙事接受度极高,其它市场按各自原料目录与进口要求逐一复核;以最新官方文本为准。','谷物底物加微生物发酵,通常可做 vegan,须供应商出具培养基与助剂声明;清真需供应商出具证明,并特别确认发酵与提取过程中的乙醇处理方式。','low','后段加入,45℃ 以下为宜,加得越晚气味损失越小、颜色越浅。香精体系要围绕它来设计,不要先定香再加料——加完后再改香往往要推翻整支香。透明配方建议先做梯度稀释目视对照,确定客户能接受的色度上限并写进规格书。灌装前过滤。批次间颜色与气味差异较大,建议按色度分级并规定可接受范围;若客户对颜色要求严格,应与供应商锁定批次,或事先取得客户对微量调色方案的书面确认。大罐降温慢,加料点以实测温度为准而不是按时间表。','brightening','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('aureobasidium-pullulans-ferment','Aureobasidium Pullulans Ferment','出芽短梗霉发酵产物','黑酵母发酵液,β-葡聚糖发酵物,Aureobasidium pullulans','未确认','发酵物','hydrating,barrier,soothing,firming','出芽短梗霉发酵得到的含 β-葡聚糖类多糖的水相料。它在皮肤表面形成连续的水合膜,带来收干后的紧绷回弹肤感,在配方中既是功能料也是明显的流变贡献者,常用于保湿与舒缓方向,以及「即时膜感紧致」的肤感设计。','0.5–5%(公开配方学常见区间,非法规限值)','serum,essence,gel,mask,lotion,cream','4.0–7.5','阳离子聚合物与阳离子表活会与阴离子多糖形成复合物,轻则增稠失控,重则絮凝出丝。高浓度电解质会使体系粘度骤降。与卡波、黄原胶等增稠体系叠加时,粘度贡献互相放大,原有流变曲线完全不再适用,必须重新配平。高浓度乙醇会使多糖析出。pH 低于 3 长期储存会缓慢降解多糖,表现为粘度下降与膜感消失。在清洁类配方里与高浓度阴离子表活同用会产生拉丝感和冲洗后的假滑。','多糖类的典型问题是储存期粘度漂移:高温下粘度缓慢下降,低温下可能凝胶化或返稠。反复冻融容易相分离析水。见光影响较小,但遇氧与微生物污染影响很大——多糖是优良碳源,防腐一旦不足就会出现拉丝、变味、pH 下跌。常见防护:pH 控制在 4.5–6.5、加螯合剂、防腐挑战做完整版、储存期跟踪粘度曲线而不只看外观是否分层。','发酵多糖类常用原料,按已使用原料目录与备案要求核对菌株来源与规格;以最新官方文本为准。','常规使用方向,需完成安全评估与成分申报,微生物来源须提供菌株与工艺说明;以最新官方文本为准。','常规使用方向,按目标市场规则复核标签与宣称边界;以最新官方文本为准。','日韩与东南亚普遍使用,按各自原料目录与进口要求逐一复核;以最新官方文本为准。','微生物发酵来源,培养基不含动物源时通常可做 vegan,须供应商出具培养基声明;清真需供应商出具证明。','mid','粘度贡献显著,做配方时必须把它算进增稠总量:先把它加进去,再定增稠剂用量,不要先做好基质再补它,那样几乎一定做过头。建议 50℃ 以下加入,长时间高温加搅拌会剪切降解多糖,粘度和膜感一起丢。加入时低速搅拌,高剪切均质会明显降粘。放大生产的典型坑是设备剪切条件不同:小试用高剪切均质、大罐用低速桨叶,同一配方在两边做出的稠度会明显不同,必须按量产设备的剪切条件重新配平流变,并在工艺文件里写死搅拌转速与时长。喷雾头、滴管、细口泵头这类出料通道窄的包材,要单独做拉丝与堵头测试。','hydration','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('saccharomyces-xylinum-black-tea-ferment','Saccharomyces/Xylinum/Black Tea Ferment','红茶菌发酵产物(康普茶)','康普茶发酵物,红茶菌,Kombucha,Camellia sinensis','未确认','发酵物','antioxidant,soothing,hydrating,barrier','由酵母与醋酸菌共生体系发酵红茶得到的滤液,含有机酸(醋酸、葡糖酸类为主)、茶多酚类与微量多糖。配方里同时承接「茶」与「发酵」两条叙事,常用于抗氧化与舒缓方向,同时会给体系带来明显的酸度。','1–10%(公开配方学常见区间,非法规限值)','toner,essence,serum,mask,gel,lotion','3.5–5.5','本身偏酸并含有机酸,会把体系 pH 拉低,与不耐酸的活性(部分肽类、某些防腐体系、需要中性区间的酶类或部分植提)同用必须先测终点 pH 再定配方。茶多酚类遇铁离子显蓝黑或墨绿,遇碱变深棕,必须加螯合剂并避免与碱剂局部接触。与阳离子调理剂共用会与多酚形成沉淀。与高浓度蛋白或肽类同用可能因多酚与蛋白结合而出现浑浊与肤感变化。与卡波类增稠体系配合时,它的酸度会压低体系 pH 使卡波失去粘度,须重新中和配平。','见光与遇氧会让多酚氧化,颜色由浅黄向红棕、深棕漂移,这是它最直观的老化信号。高温大幅加速变色。若储存期 pH 上行,变色进一步加快。醋酸类气味在高添加量时明显,包材若密封不佳还会随时间挥发流失,导致前后批次气味不一致。常见防护:螯合剂配水溶性抗氧组分、避光包材、控制瓶内顶空、pH 锁定在偏酸区间,加速试验必须逐周记录颜色曲线。','按已使用原料目录与备案要求核对菌株与植物来源、规格及安全信息;以最新官方文本为准。','常规使用方向,需完成安全评估与成分申报,共生发酵体系须提供菌株与工艺说明;以最新官方文本为准。','常规使用方向,按目标市场规则复核标签写法与宣称边界;以最新官方文本为准。','各市场按自身原料目录与进口要求逐一复核,发酵含醇工艺在部分市场需额外说明;以最新官方文本为准。','茶叶底物加微生物共生发酵,通常可做 vegan,须供应商出具培养基与助剂声明;清真需供应商出具证明,并重点确认发酵过程中乙醇的产生与去除方式。','mid','后段加入,45℃ 以下;加完立即复测 pH,并在此基础上决定中和方案,不要先把 pH 调好再加它。与卡波或丙烯酸酯类增稠体系配合的正确顺序是:先加它 → 复测 pH → 再中和到目标粘度;顺序颠倒会出现「加完就塌粘」。所有接触料体的设备与管路要确认材质,避免被酸侵蚀或释放铁离子,铁污染在这支料上会直接显色。灌装前过滤。放大生产要注意大罐顶空更大、搅拌带氧更多,氧化变色比小试更快,建议减少空转搅拌时间,必要时充氮保护。','antioxidant','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('lactobacillus-ferment','Lactobacillus Ferment','乳酸杆菌发酵产物','乳酸菌发酵产物,后生元原料,Lactobacillus','未确认','发酵物','barrier,soothing,hydrating,repair','乳酸杆菌在特定培养基上发酵后得到的产物,含有机酸(以乳酸为主)、短肽、氨基酸与菌体代谢产物。它是后生元叙事的入口原料。需要向客户讲清楚的是:化妆品里用的是发酵代谢物与灭活菌体成分,不是活菌;后生元不等于益生菌,成品也不应按含活菌来沟通。','0.5–5%(公开配方学常见区间,非法规限值)','serum,essence,toner,lotion,cream,mask,gel','4.0–6.0','含乳酸,会拉低体系 pH,与不耐酸活性同用先测终点 pH。与阳离子体系同用可能絮凝。与高浓度电解质叠加会削弱卡波类体系的粘度。与强氧化剂同用会加速变色与气味变化。与含还原糖较高的其它发酵料叠加时,高温下更容易褐变。pH 高于 7.5 的碱性体系下气味变化明显并可能变色。','对常规工艺的耐受性中等,但仍怕长时间高温与强剪切带来的气味变化。见光影响中等,遇氧与金属离子会推动黄变。实际风险主要来自两处:一是它本身是营养源,防腐余量必须留足并做完整挑战;二是沟通口径——客户若按活菌理解,会追问活菌数与储存活性,而交付的是灭活体系,必须在规格书与沟通材料里写清「非活菌、无需冷链」,避免上市后被质疑。','按已使用原料目录与备案要求核对菌株来源、灭活工艺与规格;以最新官方文本为准。','常规使用方向,需完成安全评估与成分申报,须明确非活菌属性与灭活工艺;以最新官方文本为准。','常规使用方向,后生元相关宣称边界需按目标市场规则单独复核;以最新官方文本为准。','日韩后生元概念接受度高,各市场按自身原料目录与进口要求逐一复核;以最新官方文本为准。','微生物发酵来源,培养基若含乳源或动物源则不可做 vegan,须供应商出具培养基声明;清真需供应商出具证明。','low','建议 45℃ 以下后段加入,先预稀释再入罐。加入后复测 pH 并按需回调,不要凭上批经验直接定中和量——不同批次乳酸含量差异会改变终点 pH。若同一配方里还有二裂酵母溶胞物等更热敏的发酵料,把最热敏的排在最后加。规格书要单独写明三件事:非活菌属性、来料是否自带防腐、培养基是否涉及乳源或大豆源等潜在过敏原,这三项客户几乎必问,提前写好能省一轮往返。','postbiotic-barrier','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('bacillus-soybean-ferment-extract','入库前用官方 INCI 名录逐字核对「Bacillus/Soybean Ferment Extract」;核不上就整条换成有把握的写法(如以聚谷氨酸为主线改写为 Sodium Polyglutamate,并相应重写 mechanism_zh 与 aliases),同时把 confidence 维持在「中」以下。','芽孢杆菌/大豆发酵产物提取物','纳豆发酵提取物,聚谷氨酸发酵物,Natto,Bacillus subtilis,Glycine max','未确认','发酵物','hydrating,barrier,firming,conditioning','以大豆为底物、经芽孢杆菌(纳豆发酵路线)发酵得到的提取物,通常富含聚谷氨酸类高分子与发酵小分子。特点是在皮肤表面形成明显的保湿膜,带来厚润与收干后的紧致感,常用于保湿与膜感肤感方向的配方设计。','0.1–2%(公开配方学常见区间,非法规限值);高分子型在很低用量下肤感变化已很明显','serum,essence,gel,lotion,cream,mask','4.5–7.5','聚谷氨酸类属阴离子高分子,与阳离子表活及阳离子调理剂会形成复合物,出现絮凝或明显拉丝。高浓度电解质与多价金属离子(尤其钙、镁)会使其收缩、失去膜感甚至沉淀。高浓度乙醇会导致析出。pH 低于 3.5 长期储存会降解高分子,肤感变薄。与其它成膜剂(部分聚合物、天然胶)叠加容易把膜感做过头,出现收干紧绷、搓泥与后续彩妆浮妆。','高分子在高温与强剪切下会降解,表现是粘度与膜感同时下降,而外观往往看不出异常——这类隐性失效必须靠粘度跟踪与肤感评价才能发现,只看分层不够。冻融循环容易析水。遇氧与光的影响相对较小,微生物风险较大(发酵料加高分子等于优良碳源),防腐挑战必须做完整版。储存期建议同时跟踪粘度与铺展性。','按已使用原料目录与备案要求核对菌株与大豆来源、规格;以最新官方文本为准。','常规使用方向,需完成安全评估与成分申报,大豆来源建议保留过敏原与来源说明备查;以最新官方文本为准。','常规使用方向,大豆来源在下游沟通中可能涉及过敏原标示需求,按目标市场规则复核;以最新官方文本为准。','日本市场对纳豆发酵路线认知度高,各市场按自身原料目录与进口要求逐一复核;以最新官方文本为准。','植物底物加微生物发酵,通常可做 vegan,须供应商出具培养基与助剂声明;清真需供应商出具证明。','mid','后段加入,50℃ 以下,低速搅拌,避免长时间均质。粉体型必须先充分水合:沿涡流边缘慢速撒入,给足溶胀时间再入罐,直接倒入会结成鱼眼,后续再怎么搅也化不开。肤感调试的实操经验:它带来的膜感会拖慢吸收,做「清爽速吸」定位时应降到 0.3% 以下,并用轻质酯类和少量硅弹体配平铺展与收干速度;做「厚润紧致」定位时可到 1% 以上并配少量成膜多糖。搓泥风险主要来自它与阴离子增稠剂、部分防晒剂和其它高分子的叠加,量产前必须做与后续防晒和底妆的叠涂试验。大豆来源应在规格书注明,并向供应商索取过敏原与来源说明。','hydration','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('lactobacillus-ferment-lysate','Lactobacillus Ferment Lysate','乳酸杆菌发酵溶胞产物','乳酸菌溶胞物,乳酸杆菌溶胞发酵产物,Lactobacillus','未确认','发酵物','barrier,soothing,repair,hydrating','与乳酸杆菌发酵产物同源但工艺不同:发酵结束后不只取滤液或上清,而是把菌体破壁(溶胞),让胞内蛋白、肽、核酸片段与细胞壁碎片一并进入产品。相对滤液型,组分谱更复杂、固含通常更高,配方里常用于屏障与舒缓方向,也用来支撑更强的后生元叙事。','0.5–5%(公开配方学常见区间,非法规限值)','serum,essence,toner,lotion,cream,mask','4.5–6.5','含较多蛋白与核酸类组分,对热、强氧化剂和极端 pH 比滤液型更敏感。与阳离子体系的絮凝风险高于滤液型。与高浓度乙醇同用析出风险更大。与强还原剂或含硫醇原料同用会加重气味。pH 低于 3.5 长期储存易褐变并伴异味。与多价金属离子共存会交联起浑。含蛋白酶活性的其它原料(部分果蔬酶提取物)会降解其中的肽组分,应避免同配方直接叠加。','比滤液型更热敏、更易褐变,储存期气味加重也更明显。见光加深颜色。它是最优质的微生物营养源之一,防腐挑战必须做完整版,不能只做缩水版。常见防护:后段低温加入、加螯合剂、控制溶氧、避光包材、pH 锁在 4.5–5.5,加速试验做满并逐周记录颜色与气味变化。','按已使用原料目录与备案要求核对菌株来源、溶胞工艺与规格;以最新官方文本为准。','常规使用方向,需完成安全评估与成分申报,须明确非活菌属性与灭活、溶胞工艺;以最新官方文本为准。','常规使用方向,后生元相关宣称边界需按目标市场规则单独复核;以最新官方文本为准。','日韩后生元叙事接受度高,各市场按自身原料目录与进口要求逐一复核;以最新官方文本为准。','微生物发酵来源,培养基若含乳源或动物源则不可做 vegan,须供应商出具培养基声明;清真需供应商出具证明。','mid','40℃ 以下加入,是配方里最后加的一档;先预稀释再缓慢入罐,低速短时搅拌。客户最常见的一轮来回是把它与 Lactobacillus Ferment(滤液/发酵产物型)按单价直接对比,得出「贵一倍」的结论。要提前讲清三点差异:一是工艺不同,溶胞型多一道破壁与后处理,得率与成本结构不同;二是固含与组分谱不同,不能按等重量替换,换用必须重做稳定性、气味与防腐挑战;三是热敏性不同,溶胞型对投料温度要求更严,产线加料点要改。把这三点写进报价附页,通常能直接省掉一轮往返。不同供应商的溶胞程度与过滤精度差异大,来料应规定固含范围与浊度上限。','postbiotic-barrier','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('simmondsia-chinensis-seed-oil','Simmondsia Chinensis Seed Oil','荷荷巴籽油','霍霍巴油,油蜡树籽油,Jojoba Oil,Simmondsia chinensis','61789-91-1','植物油脂','conditioning,barrier,hydrating','它在化学上不是甘油三酯，而是长链脂肪酸与长链脂肪醇缩合成的液态蜡酯，分子里只有一个酯键，双键位置远离酯键，且几乎不存在两个双键夹着一个亚甲基的结构。常规植物油之所以容易酸败，正是因为那个夹在双键之间的活泼氢容易被夺走并引发链式自氧化；荷荷巴缺这个位点，所以氧化诱导期远长于普通植物油。铺展后在角质层表面形成半封闭的蜡质薄膜，用于降低经皮水分散失、改善油相的顺滑与延展。极性低、组成接近皮脂，常用于要求「油感轻、不闷」的方向。','乳霜、乳液油相常见 2–20%；精华油、按摩油可做 50–100% 主体。以上为公开配方学常见添加区间，非法规限值。','serum,essence,cream,lotion,oil,balm,stick,mask','3.0–9.0(蜡酯键在常规化妆品 pH 下水解极慢,对体系 pH 不敏感;pH 9 以上的皂基体系仍会缓慢皂化,见配伍第③条)','① 与高极性溶剂互溶性差：与丙二醇、丁二醇或乙醇含量超过约 20% 的体系直接混合会浑浊、静置分层，无水或高醇配方需要用中等极性酯（辛酸/癸酸甘油三酯、C12-15 醇苯甲酸酯）搭桥。② 极性太低导致对粉体润湿性不足：单独用它研磨二氧化钛、氧化锌或色粉会磨不开、返粗出色点，必须先用极性酯预分散。③ 皂基清洁体系里做超脂时，蜡酯皂化速度慢于甘油三酯，加多了会拖慢皂化终点并留下持续油腻感。④ 在 O/W 里超过约 15% 时，油滴界面张力低、粘度低，普通非离子 HLB 体系容易膏体发软、离心后析油，需要提高增稠或改走液晶乳化路线。⑤ 不与过氧化苯甲酰等强氧化性原料同处一相。','① 氧化稳定性属常用天然油脂里最好的一档，但「稳定」不等于「免抗氧化」：未精制的金黄色批次带少量色素与游离脂肪酸，长期见光会缓慢褪色并伴随酸值上升，仍建议加 0.05–0.1% 混合生育酚，配迷迭香提取物（脱味级）与螯合剂效果更好。② 对热耐受好，常规 75–85 ℃ 乳化温度不会造成可察觉劣化，但不建议 90 ℃ 以上长时间保温。③ 低温（约 7–10 ℃ 起）会浑浊并析出蜡状絮凝，属可逆现象，回温到 25 ℃ 轻搅即恢复；问题在于冬季海运到货的客户会把絮状物直接判为变质，必须提前在 COA 备注和客服话术里写明，这是最常见的无谓客诉来源。④ 避免与铁、铜接触，管路与料桶避免使用裸露碳钢件。','作为植物油脂类原料在国内化妆品中常规使用，投产前按原料目录收录情况与备案资料要求复核；以最新官方文本为准。','欧盟属常规化妆品油脂原料，按成品安全评估与 INCI 标注执行；以最新官方文本为准。','美国按化妆品成分常规使用，重点复核标签写法与宣称口径；以最新官方文本为准。','日韩及东南亚普遍使用，各地按当地原料目录与标签规则复核；以最新官方文本为准。','植物来源，通常可做 vegan；清真需供应商出具证明，并覆盖加工助剂与储运容器的交叉污染说明。','mid','① 归入油相，与乳化剂一同升温至 75–80 ℃ 即可，不需要更高温度。② 若配方含热敏活性或强调香气，可把约三分之一的荷荷巴留到降温至 45 ℃ 以下做「冷补油」，肤感更轻、香气释放更完整。③ 桶料冬季会半凝，投料前必须整桶在 30–40 ℃ 保温箱回温并充分搅匀；只取上层清液会造成批次间蜡酯组成漂移，是小作坊式操作最隐蔽的批差来源。④ 与无机防晒粉体或颜料共用时，先用极性酯预分散粉体，再兑入荷荷巴。⑤ 放大生产时粘度低、泵送顺畅，但灌装嘴挂丝滴液明显，高含量产品建议配防滴灌装嘴并适当降低灌装速度。','barrier-repair','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('squalane','Squalane','角鲨烷','鲨烷,氢化角鲨烯,植物角鲨烷,甘蔗角鲨烷,橄榄角鲨烷,Squalane','111-01-3','植物油脂','conditioning,barrier,hydrating','完全饱和的 C30 支链烷烃，由角鲨烯加氢得到，分子里既没有双键也没有酯键，所以既不酸败也不水解。极性极低、分子体积小，铺展快、渗透感强，用于把配方从「厚重拖沓」拉向「清爽好推」，同时在表面形成薄疏水膜以减少水分散失。常作为矿油与低粘硅油的天然来源替代油相。','精华、乳霜常见 1–20%；精华油可做主体。以上为公开配方学常见添加区间，非法规限值。','serum,essence,cream,lotion,gel,oil,balm,stick','2.0–10.0（惰性烷烃，对 pH 不敏感）','① 真正的坑不是化学反应而是极性落差：与高极性酯（PEG 类酯、二异硬脂醇苹果酸酯）或高浓度多元醇混合时容易出现「搅拌时看着均一、静置后分层」的假混匀，无水配方必须按极性梯度排布油相。② 对极性活性物溶解力差：油溶性维 C 衍生物、水杨酸、部分固体紫外线吸收剂在纯角鲨烷里溶不开，全靠角鲨烷做油相会导致结晶析出或防晒剂返粗。③ 单独作分散介质研磨粉体时润湿性差、易返粗结团，需配润湿剂或极性酯。④ 与蜂蜡、小烛树蜡做膏棒时相容性有限，晶网锁不住这么低粘度的液油，冷却后容易渗油（出汗），需要中高极性酯或高熔点酯配合。','① 本体极稳定：无双键，不酸败、不返味、不变色，是配方里少数可以不额外加抗氧化剂的油相。② 真正的风险来自氢化不彻底的批次——残留角鲨烯会带来快速氧化和油耗味，来料应核对碘值与角鲨烯残留指标，只看「纯度 ≥ 92%」这类笼统写法判不出来。③ 来源差异是报价争议的主因：甘蔗（发酵）来源通常纯度更高、几乎无味、批次一致性好；橄榄来源可能带轻微植物气息与更明显的批间色泽差，且价格随橄榄产季波动。两者不能按同一价格谈，也不能在打样与量产之间互换。④ 耐热、耐光，可承受常规乳化与热灌装。','作为常规化妆品原料使用，需在文件中明确来源（植物/发酵，非动物），并按备案资料要求复核；以最新官方文本为准。','欧盟常规使用，按成品安全评估与 INCI 标注执行；动物来源与植物来源在客户端要求差异大，来源声明须可追溯。以最新官方文本为准。','美国按化妆品成分常规使用；宣称 plant-derived 时须有供应商来源文件支撑。以最新官方文本为准。','日韩及东南亚广泛使用，各地按当地原料目录与标签规则复核；以最新官方文本为准。','必须先确认非动物（鲨鱼肝）来源；植物或发酵来源通常可做 vegan，清真需供应商出具覆盖来源与整条加工链的证明。','mid','① 油相常规投料，75–80 ℃ 无压力；也可完全冷兑，不受温度限制。② 报价与规格书必须写死来源（sugarcane / olive）和角鲨烯残留指标——客户拿橄榄来源的价格去比甘蔗来源的样品，是这支原料最常见的报价纠纷，写清楚比事后解释便宜得多。③ 打样与量产要锁同一来源、同一供应商：换来源会改变气味与初始色泽，客户会当成「你们把配方改了」。④ 与无机防晒或粉体共用时先用极性酯预分散，不要直接拿角鲨烷研磨。⑤ 粘度低、爬杆少，灌装顺畅但挂壁滴液明显，高比例配方建议配防滴嘴。','barrier-repair','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('argania-spinosa-kernel-oil','Argania Spinosa Kernel Oil','摩洛哥坚果油','阿甘油,摩洛哥坚果油,坚果树仁油,Argan Oil,Argania spinosa','未确认','植物油脂','conditioning,barrier,antioxidant,repair','以油酸和亚油酸为主的甘油三酯，并带有相对可观的生育酚与植物甾醇。铺展中等，渗透感介于荷荷巴与厚重油之间，用于补充皮脂中的不饱和脂肪酸并改善干燥粗糙的手感；在发用产品中用于降低梳理阻力与毛躁。出海线上认知度高，是少数客户会主动点名的植物油。','乳霜、护发常见 1–10%；精华油可做 20–100% 主体。以上为公开配方学常见添加区间，非法规限值。','serum,cream,lotion,oil,balm,mask','4.0–8.0','① 含亚油酸与游离甾醇，遇未螯合的铁、铜离子（水相硬水、含铁色粉、矿物粉体带入）会明显加速氧化并出现油耗味，必须配 0.05–0.2% EDTA 类或植酸类螯合剂，这一条不是可选项。② 与 pH 9 以上体系（皂基、部分染烫脱毛类）共存时甘油三酯缓慢皂化，体系变稠、气味走偏、pH 继续漂移。③ 与过氧化物类强氧化剂（过氧化苯甲酰、氧化型染发）同处一相会快速劣化，必须分包或独立后加。④ 与富含多酚、单宁的水相植物提取物在乳液里长期共存，界面处易发生氧化偶联，成品几个月内缓慢转褐。⑤ 未脱臭的传统烘焙级带明显坚果焙烤气，与清淡花香/柑橘香型冲突，且这股气味在存放中会走味。','与甾醇谱——阿甘油以 schottenol 与 spinasterol 为主的甾醇谱,和大豆、葵花、菜籽这些常见稀释油(以 β-谷甾醇、菜油甾醇为主)明显不同,是掺假筛查里最难伪造的一项;个别葫芦科籽油也含这两种甾醇,判定以完整甾醇谱与首样比对为准,不看单一峰。','作为植物油脂类原料常规使用，按原料目录收录情况与备案资料要求复核；以最新官方文本为准。','欧盟常规使用；坚果来源在部分品牌方的过敏原信息政策里需另行说明（属客户要求而非成分限制）。以最新官方文本为准。','美国按化妆品成分常规使用；tree nut 来源信息常被零售渠道问询，建议备好供应商声明。以最新官方文本为准。','日韩及东南亚普遍使用，各地按当地原料目录与标签规则复核；以最新官方文本为准。','植物来源，通常可做 vegan；传统供应链以当地合作社人工取仁为主，清真与社会责任类文件需供应商逐批提供。','high','① 建议冷补：主体乳化在 75–80 ℃ 完成，降温至 45–50 ℃ 时补入阿甘油，减少高温暴露、保住气味与生育酚。若工艺上必须与油相同升温，控制在 80 ℃ 以内、保温不超过 30 分钟。② 验收环节是这支油的重点：每批索取 GC 脂肪酸谱与甾醇谱，只给「感官 + 酸值 + 过氧化值」的 COA 不予接收。建立首样留样，后续批次逐批与首样比谱；报价明显低于市场行情的批次优先做掺假筛查而不是庆祝。③ 指定 deodorized / cosmetic grade 冷压，不要拿食用烘焙级打样——气味完全是两回事，客户会判为变质。④ 大罐分装避免反复开盖，分装后立即氮气覆盖；开桶后建议 3 个月内用完。⑤ 深色物料的泵管专管专用或彻底清洗，避免带味到浅色配方。','lipid-replenish','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('camellia-oleifera-seed-oil','Camellia Oleifera Seed Oil','油茶籽油','山茶油,茶油,茶籽油,Camellia Seed Oil,Camellia oleifera','未确认','植物油脂','conditioning,barrier,hydrating,antioxidant','(删掉末句,改为)国际客户对这支油认知度低,随样资料需要额外交代来源、部位与脂肪酸谱。','乳霜、身体乳常见 2–20%；纯油、按摩油可做主体。以上为公开配方学常见添加区间，非法规限值。','serum,cream,lotion,oil,balm,stick,mask','4.0–8.0','③ 压榨毛油或精炼不彻底的批次可能带入残留茶皂素,理论上会与阳离子调理剂(季铵盐类)相互作用,表现为护发产品滑感下降或体系浑浊——此条为低精炼批次的实务提示,尚未逐批验证,指定精炼级即可规避。','① 在常用植物油里属稳定的一档，单不饱和为主意味着氧化诱导期长，常规抗氧化保护下的货架期表现接近橄榄油、部分批次更好。建议仍配 0.05–0.1% 混合生育酚 + 螯合剂 + 避光包材 + 灌装控氧。② 主要风险来自精炼程度而非氧化本身：毛油带明显豆青气与较高游离脂肪酸，见光见热后会先「返生青味」再转哈喇。化妆品应指定脱胶脱酸脱色脱臭的精炼级，或低温压榨加脱臭级。③ 低温（约 0–5 ℃）会浑浊并析出蜡状絮凝，回温可逆，但冬季海运到货的客户容易误判为变质，需要在 COA 备注与客服话术里提前写明。④ 耐热性好，常规乳化温度无碍，但 90 ℃ 以上长时间保温会加重气味。','国内常见植物油脂原料，常规使用，按原料目录收录情况与备案资料要求复核；以最新官方文本为准。','欧盟按常规化妆品油脂原料处理，按成品安全评估与 INCI 标注执行；以最新官方文本为准。','美国按化妆品成分常规使用，重点复核标签与宣称口径；以最新官方文本为准。','日韩及东南亚可用，属认知度较低的原料，建议随资料附来源与脂肪酸谱说明；各地按当地规则复核，以最新官方文本为准。','植物来源，通常可做 vegan；清真需供应商出具证明，并覆盖精炼过程使用的加工助剂。','mid','① 油相常规 75–80 ℃ 投料，耐热性好；但若要保留那股淡淡的谷物-坚果气作为草本叙事的一部分，建议留一部分到 45 ℃ 冷补，全程高温会把这股辨识气味蒸掉。② 采购必须卡死拉丁名与部位：Camellia oleifera（油茶籽）、Camellia japonica（山茶花籽）、Camellia sinensis（茶树籽）在中文里都可能被叫成「山茶油/茶油」，三者 INCI 完全不同，下单写错、来料标错都会直接变成标签事故。下单单、来料 COA、成品标签三处要对同一个拉丁名。③ 桶料冬季半凝，整桶回温 30–40 ℃ 搅匀后再取样投料，不要只取上清液。④ 国际客户对这支油认知空白，建议随样品附一页脂肪酸谱与产地工艺说明，能显著减少「这是什么油、和橄榄油有什么区别」的往返沟通。','barrier-repair','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('rosa-canina-fruit-oil','Rosa Canina Fruit Oil','玫瑰果油','玫瑰果油,野蔷薇果油,犬蔷薇果油,玫瑰籽油,Rosehip Oil,Rosa canina','未确认','植物油脂','conditioning,repair,barrier,antioxidant','多不饱和脂肪酸占比很高，亚油酸与 α-亚麻酸合计通常在七成上下，另含少量类胡萝卜素与生育酚。用于补充屏障脂质中的必需脂肪酸方向，肤感轻、渗透快、不留油膜。代价是这一脂肪酸结构本身就是氧化的靶点，配方里必须按「高氧化风险油」对待。另需提醒：市面流传的「天然维 A 酸」说法缺乏可靠依据，宣称上不要沿用，否则是可预见的合规风险。','乳霜、精华常见 1–5%（上限主要由氧化风险而非成本决定）；纯油产品可做主体，但需强抗氧化体系与阻隔包材配合。以上为公开配方学常见添加区间，非法规限值。','serum,essence,oil,cream,lotion,balm,mask','4.5–7.5','① 未螯合的铁、铜离子会显著加速自氧化，几周内即可闻到油耗味；含矿物粉体、天然色素或用非去离子水配制时，螯合剂是强制项。② 与高浓度乙醇或高浓度 AHA/BHA 的酸性体系共处，会加速游离脂肪酸释放并放大酸败气味，酸性精华里加玫瑰果油必须额外提高抗氧化剂并主动缩短保质期承诺。③ 与阳离子表活、季铵盐护发体系配伍时，氧化产生的醛酮会与胺类反应导致黄变，长期存放尤其明显。④ 不与过氧化苯甲酰、氧化型染烫等含氧化性活性的体系同处一相。⑤ 与香精共存要特别小心：氧化产生的醛类会改变香型走向，同一支香精在含玫瑰果油的基质里三个月后闻起来会明显不同，香型评估必须做加速后复评，不能只评刚做完的样。','① 典型的「卖点原料带工艺代价」：α-亚麻酸的双烯丙基氢是自氧化链反应的起点，无保护时室温下几周就能测出过氧化值上升，气味先转青草-鱼腥，再转哈喇。② 温度是最强的加速因子，方向性判断是每升高 10 ℃ 氧化速率成倍上升（仅作工艺决策方向，不作为定量依据），因此不建议与油相同升温到 80 ℃。③ 保护组合：0.1–0.3% 混合生育酚 + 脱味级迷迭香提取物 + 0.1% 螯合剂 + 氮气顶空 + 不透光包材（深色玻璃或阻隔管，避免透明 PET）。④ 见光褪色明显，初始橙金色会转浅黄再转褐，客户往往先因为颜色变化而判定变质。⑤ 保质期承诺要保守：即使做满保护，成品也建议按 12 个月以内谈，PAO 写短。⑥ 来料到货即测过氧化值与酸值，不要只看颜色，超阈值不入库。','作为植物油脂类原料常规使用，按原料目录收录情况与备案资料要求复核；宣称口径需避开药理表述。以最新官方文本为准。','欧盟常规使用，按成品安全评估与 INCI 标注执行；宣称须符合功效宣称通用准则。以最新官方文本为准。','美国按化妆品成分常规使用；涉及「A 酸/视黄酸」类表述属高风险宣称，须删除。以最新官方文本为准。','日韩及东南亚普遍使用，各地按当地原料目录与标签规则复核；以最新官方文本为准。','植物来源，通常可做 vegan；清真需供应商出具证明。','mid','① 一律冷补：乳化完成、降温至 40–45 ℃ 以下再加入，绝不与油相同升温。② 抗氧化剂要先溶进玫瑰果油本身再一起入体系，不要指望它从别的相扩散过来——这是很多「加了生育酚还是返味」案例的真正原因。③ 配制罐抽真空或氮气置换，搅拌避免打入空气，高速均质时间尽量压短。④ 开桶后强制氮气覆盖并分装小桶，避免大桶反复开盖；开桶后建议一个月内用完，超期重测过氧化值再决定是否投料。⑤ 包材必须在打样阶段定死：透氧高的薄壁 PE 软管、薄壁 PET 会把配方里做好的抗氧化保护在货架上慢慢耗光，深色玻璃、EVOH 阻隔管或真空瓶才匹配。⑥ 稳定性试验必须用真实包材，只用玻璃瓶跑 45 ℃ 得到的结论会系统性偏乐观。','lipid-replenish','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('hippophae-rhamnoides-fruit-oil','Hippophae Rhamnoides Fruit Oil','沙棘果油','沙棘果油,沙棘果肉油,醋柳果油,Sea Buckthorn Fruit Oil,Hippophae rhamnoides','未确认','植物油脂','antioxidant,barrier,repair,conditioning','由果肉（不是籽）压榨得到，特征是棕榈油酸 C16:1 比例很高，并富集类胡萝卜素与生育酚，因此呈深橙红色。用于补充皮肤脂质中较少见的单不饱和 C16:1 方向，同时在配方里兼作天然色泽与油相抗氧化补强。由于着色力极强，实务上应按「功能性着色油」设计用量，而不是当普通基础油。注意它与沙棘籽油（Hippophae Rhamnoides Seed Oil）是两支原料：籽油颜色浅、亚油酸与亚麻酸为主，二者不能互换。','乳霜、精华常见 0.05–1%，上限由颜色而非成本决定；纯油类产品另议。以上为公开配方学常见添加区间，非法规限值。','serum,essence,oil,cream,lotion,balm,mask,stick','4.5–7.5','① 最大的配伍冲突是颜色而不是化学：0.1% 就能把白霜带成明显杏色，0.5% 以上接近橙色，与二氧化钛/珠光配的浅色配方、以及任何要求「纯白卖相」的产品基本互斥。② 类胡萝卜素在 pH 4 以下与高氧条件下会先褪色再转暗褐，与高浓度 AHA/水杨酸精华同处会造成前后色差大到客户认为换了配方。③ 与高浓度抗坏血酸及其盐共存时颜色变化路径难以预测，浅色配方要先做长期色卡跟踪再决定是否组合。④ 与三乙醇胺等胺类中和体系、与阳离子护发体系共存易走黄褐化路径。⑤ 未螯合的金属离子会同时加速色素降解与油相氧化，螯合剂是必配项。','① 见光褪色快：透明包材在货架灯下几周即可肉眼看出变浅，深色瓶或不透光管是硬要求。② 70 ℃ 以上长时间保温会同时损失颜色与气味并使色泽变暗。③ 氧化倾向中偏高——果油不饱和度低于籽油，但类胡萝卜素本身就是氧化靶点，需 0.1% 级生育酚 + 螯合剂 + 控氧灌装。④ 染色是这支原料最容易被客诉的点，也是最容易被忽略的：即便千分之几的添加量，成品也会在毛巾、白色衣物、浅色浴室台面上留下橙色印记且不易洗掉，深色料在皮肤上停留几分钟也可见淡黄。这一点必须写进客户确认单并体现在产品说明里，不写清楚上市后必投诉。⑤ 产线同样会被染色：管道、泵、灌装嘴、密封圈会着色，橡胶与硅胶密封件基本洗不回原色。','作为植物油脂类原料常规使用；若在功能或宣传上按着色用途使用，需另按着色剂相关规则复核。按原料目录收录情况与备案资料要求核对，以最新官方文本为准。','欧盟按常规化妆品油脂原料处理；若实质承担着色功能，需按着色剂相关规则另行复核。以最新官方文本为准。','美国按化妆品成分常规使用；实质用作着色时须按着色剂相关规则复核。以最新官方文本为准。','日韩及东南亚可用，各地按当地原料目录、着色剂规则与标签规则复核；以最新官方文本为准。','植物来源，通常可做 vegan；清真需供应商出具证明。','high','① 冷补：降温到 40–45 ℃ 以下加入，边加边看颜色，颜色到位就停——不要按配方表死加百分比，不同批次色深差异可以大到肉眼可辨。② 当作色浆管理：每批来料先打 0.1% / 0.3% / 0.5% 三档色板，与首样色卡比对，用比例微调而不是固定用量，这是唯一能把批次色差压住的办法。③ 产线安排在浅色产品之后、深色产品之前；用完立即用辛酸/癸酸甘油三酯之类油相溶剂冲洗管路再走常规清洗，硅胶与橡胶密封件建议专用不混用。④ 灌装嘴与料桶专用，避免带色污染下一批浅色料。⑤ 打样阶段就把「会不会染衣服和毛巾」写进客户确认单，让品牌方在包装或说明书上体现，这一句话能省掉后面成批的退货争议。','antioxidant','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('butyrospermum-parkii-butter','Butyrospermum Parkii Butter','乳木果脂','乳木果油,牛油果树果脂,雪亚脂,Shea Butter,Vitellaria paradoxa,Butyrospermum parkii','未确认','植物油脂','barrier,conditioning,repair,hydrating','以油酸和硬脂酸为主的半固态脂，另含数个百分点的不皂化物（三萜醇酯、植物甾醇）。它在配方里同时干两件事：提供厚重的封闭性膜以降低经皮水分散失，以及作为结构脂支撑膏体骨架并贡献「上脸化开」的肤感。它的脂肪结晶能在不同晶型之间转变，这既是肤感的来源，也是批次颗粒问题的根源——理解这一点，返砂问题就从玄学变成了工艺问题。','面霜、身体霜常见 2–15%；膏棒与身体脂类可到 30% 以上。以上为公开配方学常见添加区间，非法规限值。','cream,lotion,balm,stick,mask,serum','4.0–8.0','① 与高比例低极性液油（角鲨烷、异十二烷、硅油）搭配时，硬脂形成的结晶网络锁不住液油，静置后渗油出汗；需要中极性酯或高熔点蜡把体系拉住。② 与 pH 9 以上体系共存会皂化，膏体变稠发黏、气味走偏。③ 未精炼批次带明显烟熏-坚果气，与清淡花香、柑橘香型冲突，且这股气味在存放中会走味；浅色浅香配方必须指定精炼脱臭级。④ 与任何要求透明的凝胶、啫喱体系互斥，哪怕少量也会带来白浊与结晶点。⑤ 在 O/W 里与高盐、高浓度氨基酸盐等强电解质水相共存时乳化稳定性下降，一旦叠加硬脂结晶重排就更容易先分层。','① 化学上相当稳定（饱和度高，不皂化物本身有抗氧化贡献），常温货架期长；它的问题不是酸败，而是物理稳定性。② 返砂（graininess）是身体霜最常见的批次问题：油酸/硬脂酸甘油酯在缓慢冷却或存储温度反复波动时会重结晶成粗大晶体，成品出现砂粒感与白点，而且往往在出货一两个月后才在客户端显现，那时已经全批发完。③ 触发条件很明确：冷却太慢、冷却过程中静置不搅、成品在 25–32 ℃ 区间反复升降温（夏季海运、无空调仓库）。④ 应对是快速冷却穿过结晶敏感区间并持续搅拌；必要时对原料做回火处理——先完全熔化到 80–85 ℃ 抹掉记忆晶核，再急冷至 25 ℃ 附近保持搅拌数小时后升回工作温度。⑤ 加速稳定性必须补一档温度循环（例如 4 ℃ 与 40 ℃ 之间、或 25 ℃ 与 35 ℃ 之间反复若干次），只跑 45 ℃ 恒温测不出返砂，这是最常见的「加速试验全过、市场端全砂」的原因。','作为植物油脂类原料常规使用，按原料目录收录情况与备案资料要求复核；以最新官方文本为准。','欧盟常规使用；坚果类来源在部分品牌方的过敏原信息政策里需另行说明（属客户要求）。以最新官方文本为准。','美国按化妆品成分常规使用；tree nut 来源信息常被零售渠道问询，建议备好供应商声明。以最新官方文本为准。','日韩及东南亚普遍使用，各地按当地原料目录与标签规则复核；以最新官方文本为准。','植物来源，通常可做 vegan；部分供应链带产地合作社相关文件，清真需供应商另出证明并覆盖精炼助剂。','low','① 投料：油相必须加热到 80–85 ℃ 让乳木果脂完全熔化并消除晶核，这一步不能省。只熔到「看起来化了」（约 45–50 ℃）会保留晶核，成品必返砂——这是最高频的翻车点。② 冷却曲线是关键：乳化后以尽可能快的速度降温，全程慢速刮壁搅拌，重点是快速通过约 30–20 ℃ 这一段，不要在这个区间停留或静置。③ 大罐生产比小样更容易返砂：罐心降温慢、罐壁降温快，必须用夹套冷却加刮板搅拌，不能靠自然冷却过夜；小样不返砂不等于量产不返砂，这是放大生产最典型的坑。④ 灌装温度写进工艺卡定死；灌装后的托盘不要堆叠捂热，摊开冷却到室温再打托。⑤ 成品仓储运输条件要写进给客户的文件：避免 30 ℃ 以上长期存放与反复温度循环，高温季走海运要提前书面提示。⑥ 未精炼级与精炼级不可互换打样，气味与熔程都不同，换级别等于换配方。','barrier-repair','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('oenothera-biennis-oil','Oenothera Biennis Oil','月见草油','月见草油,晚樱草油,夜来香油,Evening Primrose Oil,Oenothera biennis','未确认','植物油脂','barrier,repair,soothing,conditioning','亚油酸为主体，并含少量 γ-亚麻酸（GLA），后者是它相对其他常用植物油的差异点，也是客户点名要它的原因。用于补充屏障脂质中 ω-6 系必需脂肪酸的方向，肤感轻、渗透快。分子中双烯丙基结构比例高，氧化风险明显高于油酸型油脂——卖点和工艺代价是绑在一起的，接单时就该一起谈。','乳霜、精华常见 1–5%；油类产品做主体时需强抗氧化体系与阻隔包材配合。以上为公开配方学常见添加区间，非法规限值。','serum,essence,oil,cream,lotion,mask,balm','4.5–7.5','① 未螯合的金属离子显著加速自氧化，含矿物粉体、天然色素或用非去离子水配制时螯合剂是强制项。② 与三乙醇胺、氨甲基丙醇等胺类中和剂长期共存，氧化生成的醛类与胺反应会导致黄变，浅色乳液上尤其刺眼。③ 不与过氧化苯甲酰、氧化型染烫等含氧化性活性的体系同处一相。④ 与含醇的清爽型精华共配时，酒精挥发会把油耗味顶出来，气味阈值被拉低，香精遮盖的效果比在膏霜里差得多。⑤ 与香精的相互作用必须提前验证：氧化产物会改变香型走向，含月见草油的配方一定要做加速后香型复评，不能只评刚做完的样。','① 属高氧化风险油脂，GLA 与亚油酸的活性亚甲基是链反应起点；无保护时数周即可测出过氧化值上升，气味先转生青后转哈喇。② 光、热、氧、金属四个因子权重相当，缺任何一条防护，其余三条的投入都会被抵消。③ 包材是这支油的成败关键，必须在选瓶阶段决定而不是配方定稿后再补：透氧率高的薄壁 PE 软管、薄壁 PET、带敞口滴管的透明瓶会让抗氧化体系在货架上被慢慢耗尽；深色玻璃、EVOH 多层阻隔管、真空瓶、单剂量安瓿才是匹配的选项。④ 保护组合：0.1–0.3% 混合生育酚 + 脱味级迷迭香提取物 + 0.1% 螯合剂 + 氮气顶空。⑤ 保质期承诺保守：常规建议 12 个月并配短 PAO；客户若坚持透明 PET，必须书面下调保质期预期，把责任说在前面。⑥ 来料到货即测过氧化值与酸值，并核对 COA 的检测日期——在供应商仓库压了几个月的桶货不能按新油用。','作为植物油脂类原料常规使用，按原料目录收录情况与备案资料要求复核；以最新官方文本为准。','欧盟常规使用，按成品安全评估与 INCI 标注执行；以最新官方文本为准。','美国按化妆品成分常规使用，重点复核标签与宣称口径；以最新官方文本为准。','日韩及东南亚普遍使用，各地按当地原料目录与标签规则复核；以最新官方文本为准。','植物来源，通常可做 vegan；清真需供应商出具证明。','mid','① 冷补：降至 40–45 ℃ 以下加入；抗氧化剂先预溶于月见草油本体再入体系，不要靠它从别的相扩散过去。② 配制过程控氧：氮气置换或抽真空搅拌，避免长时间高速均质把空气打进膏体。③ 开桶后立刻氮气覆盖并分装小桶，开桶后建议一个月内用完。④ 稳定性试验必须用真实包材，并同时跑常温实时与 40–45 ℃ 加速；只用玻璃瓶跑加速会得到系统性偏乐观的结论。⑤ 打样阶段就把候选包材列出来做平行稳定性，把「选瓶」变成配方交付的一部分——这是避免上市后返味投诉最有效的一步，也是最容易被客户催进度催掉的一步。','lipid-replenish','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('perilla-ocymoides-seed-oil','Perilla Ocymoides Seed Oil','紫苏籽油','紫苏籽油,白苏籽油,苏子油,Perilla Seed Oil,Perilla frutescens,Perilla ocymoides','未确认','植物油脂','barrier,soothing,repair,conditioning','α-亚麻酸(ω-3)含量在常用植物油里位居最高的一档(与亚麻籽油相当),通常占一半以上,具体以来料 GC 结果为准。','乳霜、精华常见 0.5–3%，上限由氧化风险而非成本决定。以上为公开配方学常见添加区间，非法规限值。','serum,essence,oil,cream,lotion,mask','5.0–7.5','① 对金属离子极敏感，不加螯合剂时痕量铁铜即可在数周内引发明显酸败；含矿物粉体、植物提取物或用非去离子水的配方尤其危险。② 与 pH 4 以下的 AHA/BHA 去角质体系共处会加快游离脂肪酸释放与返味，实务上不建议组合。③ 与胺类中和剂、阳离子调理剂共存会走黄变路径。④ 与面向热带市场、无空调仓储渠道的产品基本不兼容，除非上单剂量或强阻隔包材。⑤ 与「无添加、不加抗氧化剂」的品牌诉求互斥：这支油没有抗氧化保护根本交付不了，客户若坚持无添加，正确做法是换一支油，而不是硬做然后在货架上翻车。','① 常用植物油里最难稳的一支：室温、有氧、透明包材条件下，几周就能闻到鱼腥-青草味，这是 ω-3 氧化的典型走向，客户会直接判为变质。② 光与氧的权重大于温度，但温度会同时放大两者；产线暴露时间要按分钟计，不是按小时计。③ 必需的组合：0.2–0.5% 混合生育酚 + 脱味级迷迭香提取物 + 0.1% 螯合剂 + 氮气覆盖 + 完全避光高阻隔包材（深色玻璃、真空瓶、单剂量安瓿），少任何一样都可能不够。④ 保质期承诺要格外保守：即使做满保护，成品也建议按 12 个月谈，热带市场按 9–12 个月谈，PAO 写 3–6 个月，绝不能用其他植物油的经验去推。⑤ 来料必须是低温压榨、氮封、冷藏储存的批次，到货即测过氧化值；常温运输两个月的桶货开桶时可能已经不合格。⑥ 加速试验要同时看气味（安排专人闻香）与过氧化值——它通常在外观完全正常、不分层不变色的时候就已经返味了，只看外观必然漏判。','作为植物油脂类原料常规使用，按原料目录收录情况与备案资料要求复核；以最新官方文本为准。','欧盟常规使用，按成品安全评估与 INCI 标注执行；以最新官方文本为准。','美国按化妆品成分常规使用，重点复核标签与宣称口径；以最新官方文本为准。','日韩及东南亚可用；高温高湿渠道需在包材与保质期上另行评估。各地按当地规则复核，以最新官方文本为准。','植物来源，通常可做 vegan；清真需供应商出具证明。','mid','① 放在最后一步冷补：降至 35–40 ℃ 以下加入，加完立即收料灌装，绝不让料在敞口罐里过夜。② 抗氧化剂预溶于紫苏籽油，且要在开桶后第一时间加，不要等到配料当天——桶里那几天的氧化是不可逆的。③ 配制罐必须氮气置换；均质时间压到最短，能不高速就不高速。④ 原料 2–8 ℃ 冷藏储存，投料前只回温当天要用的小桶，不要整桶反复升降温。⑤ 开桶即分装小瓶并氮封，开桶后两周内用完为宜。⑥ 稳定性必须用真实包材，并额外跑一档模拟真实使用的场景（开盖后每天开合、放在浴室），常规密闭加速试验测不出这种情形下的返味。⑦ 商务上：报价时就把「必须配深色或高阻隔包材、保质期偏短」写进技术条款，避免客户自己配了透明瓶再回头追责。','soothing','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('oryza-sativa-bran-oil','Oryza Sativa Bran Oil','米糠油','米糠油,稻米糠油,玄米油,Rice Bran Oil,Oryza sativa','未确认','植物油脂','antioxidant,conditioning,barrier,hydrating','油酸与亚油酸比例大致相当的甘油三酯，真正的特点是天然伴随的谷维素（γ-oryzanol）、生育酚与生育三烯酚。除了作基础油相，这些伴随成分对油相自身的氧化有抑制作用，因此常被当成「自带抗氧化补强」的性价比油相，用来整体或部分替代更贵的油脂。肤感中等偏轻、铺展平顺，在成本敏感客户的替代方案讨论里是最先被摆上桌的一支。','乳霜、乳液常见 2–20%，可做油相主体。以上为公开配方学常见添加区间，非法规限值。','serum,cream,lotion,oil,balm,mask,foam','4.0–8.0','① 谷维素在中性偏碱条件下溶解性与稳定性下降，且见光会让体系逐步转黄；要求浅色或透明卖相的产品必须控制用量或选低谷维素的精炼级。② 与 pH 9 以上皂基体系共存会皂化并释放游离脂肪酸，同时谷维素的颜色变化会更明显。③ 含较高天然米糠蜡，未充分冬化脱蜡的批次低温会析出白色蜡状絮凝，与需要清澈外观的油类产品互斥。④ 与要求完全无色无味基质的高端精华油互斥：即便精炼级也带轻微谷物气。⑤ 天然抗氧化物不能替代螯合剂，未螯合的金属离子仍会加速其中亚油酸部分的氧化。','① 氧化稳定性明显优于亚油酸/亚麻酸主导的油脂（玫瑰果、月见草、紫苏），原因是自带生育三烯酚与谷维素的内源保护。② 但「自带抗氧化」不等于免加：仍建议 0.05–0.1% 混合生育酚 + 螯合剂，尤其当配方里还有其他易氧化油时——它保护不了别人，先保护的是自己。③ 见光会缓慢转黄（与谷维素相关），在白色乳霜上会被放大成明确的变色投诉，深色包材或控制用量可缓解。④ 冬化不彻底的批次低温浑浊析蜡，回温可逆但外观不可接受，来料必须指定 winterized（冬化）级别。⑤ 耐热性尚可，常规 80 ℃ 乳化无碍，但长时间高温会加深颜色。','作为植物油脂类原料常规使用，按原料目录收录情况与备案资料要求复核；以最新官方文本为准。','欧盟常规使用，按成品安全评估与 INCI 标注执行；以最新官方文本为准。','美国按化妆品成分常规使用，重点复核标签与宣称口径；以最新官方文本为准。','日韩及东南亚普遍使用，各地按当地原料目录与标签规则复核；以最新官方文本为准。','植物来源，通常可做 vegan；清真需供应商出具证明，并覆盖精炼过程使用的加工助剂。','low','① 油相常规 75–80 ℃ 投料，不需要冷补；若配方追求浅色，可把一部分留到 50 ℃ 以下加入，推迟黄变的起点。② 采购要卡死三个规格：是否冬化脱蜡、谷维素含量、脱色脱臭级别。这三项直接决定成品颜色、低温外观和气味，同一个 INCI 名下差异极大，也正是「便宜替代方案」最容易被偷换规格的地方。③ 作为降本提案时不要只比单价：米糠油可能带来轻微黄变和谷物气，必须在打样阶段就让客户签色卡和闻香确认，否则量产被打回的返工成本远高于省下的料价——这是成本替代讨论里最值钱的一句话。④ 与深色植提、金属粉体同配方时，先加螯合剂再进油相。⑤ 大罐存放会分层析蜡，取样前必须搅匀，不要从桶口舀。','antioxidant','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('melaleuca-alternifolia-leaf-oil','Melaleuca Alternifolia Leaf Oil','茶树(叶)油','茶树精油,互叶白千层油,澳洲茶树油,Tea Tree Oil,Melaleuca alternifolia','68647-73-4(茶树油通用登记号;以供应商 COA 批次文件为准)','精油','oil-control,conditioning','主成分为萜品烯-4-醇与 γ-萜品烯,亲油、能与皮脂互溶,常用在油性与粉刺倾向肌肤的清洁与局部护理方向。在配方里同时承担草本药感香气与油相功能组分两个角色,通常不作唯一功能主体,而与水杨酸、锌盐或控油粉体组合使用。','驻留型 0.1–1%,冲洗型可到 2%(公开配方学常见区间,非法规限值);局部点涂型另行评估','gel,serum,cream,lotion,toner,foam,stick','4.5–7.0(本身不参与调 pH;强酸体系下萜烯类更易异构与氧化)','1)与过氧化苯甲酰同处方:氧化性组分会加速萜品烯-4-醇与 γ-萜品烯氧化,生成过氧化物与对伞花烃,气味转酸、刺激性上升。2)与铁、铜离子(硬水、矿物色素、部分植提带入)接触:催化萜烯自氧化,料体变黄并生成刺激性更强的氧化产物,必须配螯合剂。3)与不饱和植物油(葵花油、亚麻籽油)同处高油相:互相促氧化,哈败味会被茶树的药感香放大。4)水基体系里所需的非离子增溶剂(PEG-40 氢化蓖麻油等)在高浓度阳离子聚合物体系中会拉低黏度并导致精油相分离,瓶口出现油圈。5)与高浓度乙醇的水醇体系:初期澄清,但乙醇挥发后精油在瓶口析出油膜,喷头容易堵。6)与高浓度 AHA/BHA 叠加:属刺激性叠加而非化学不相容,用于敏感或屏障受损人群时须做人体耐受,报价阶段要向品牌方提示。','关键失效路径是自氧化:萜烯类遇氧、光、热生成过氧化物与对伞花烃,氧化后的茶树油刺激与致敏风险明显高于新鲜油,这是行业公认风险点。外观上表现为由无色淡黄转深黄,气味由清新药草转松节油或酸败味,过氧化值上升。防护做法:原料桶充氮、满桶存放、棕色避光瓶、25℃ 以下仓储;料体内配 0.05–0.2% 生育酚或迷迭香提取物做油相抗氧,配 0.05–0.1% 螯合剂锁金属离子;成品优先不透明或深色包材,避免透明泵瓶长期货架照射。来料建议按批索取过氧化值与萜品烯-4-醇含量,长期库存要复检。','作为香料/精油类原料常规使用,须确认在国内已使用原料目录范围内并按备案资料要求填报;抗菌、消炎方向的表述涉及功效宣称与品类边界,须按当前规则评估,以最新官方文本为准。','常规使用;安全评估中通常关注氧化产物与过氧化值,所含致敏性香料组分达到标示门槛时需在成分表单独列出,按当前致敏物清单复核,以最新官方文本为准。','作为化妆品原料常规使用;若同时以祛痘方向宣传,可能进入非处方药路径,须由法规评估后确定标签与品类,以最新官方文本为准。','日韩及东南亚主要市场常规使用,部分市场对精油总量与致敏组分标示另有要求,按目标国规则逐一复核,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。注意稀释规格常以乙醇或植物油作载体,清真与无醇线要先确认载体。','mid','归油相但不跟油相一起加热:油相 75–80℃ 乳化完成后降温到 40℃ 以下再加,避免挥发损失与香气走样。水基体系(爽肤水、啫喱)必须先增溶,常用 PEG-40 氢化蓖麻油或聚山梨醇酯-20,精油与增溶剂常见 1:3–1:5 先预混成透明相,再在搅拌下缓慢加入水相;顺序反了会立刻出现油珠与乳光。放大生产的坑:中试澄清、量产浑浊多半是水相温度偏低使增溶体系浊点变化,量产必须控水相温度;敞口长时间搅拌损耗大,建议密闭低速短时。萜烯类会溶胀部分塑料,储罐与管路优先不锈钢,软管选氟橡胶或三元乙丙,不用普通丁腈;PS、部分 PET 与普通 PP 泵头长期接触可能应力开裂或吸香,必须做成品与包材相容性试验。茶树气味强,与花香型产品共线要排产隔离并彻底清线。','oil-control','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('lavandula-angustifolia-oil','Lavandula Angustifolia Oil','薰衣草油','真薰衣草精油,狭叶薰衣草油,Lavender Oil,Lavandula angustifolia','8000-28-0(薰衣草油通用登记号;另见 90063-37-9,以供应商 COA 批次文件为准)','精油','soothing,conditioning','主要成分为芳樟醇与乙酸芳樟酯,气味接受度高,常用于放松、舒缓的香气方向设计。在草本配方里还常被用来调和植物提取物的本底气味。它在配方中主要承担感官角色,不宜作为功能主体。','驻留型 0.05–0.5%,沐浴与香氛类可到 1%(公开配方学常见区间,非法规限值)','cream,lotion,serum,essence,balm,foam,mask','4.5–7.0(低于 4.0 时酯类水解加快,香型会变)','1)与高浓度 AHA/BHA 的酸性体系:乙酸芳樟酯在低 pH 下缓慢水解为芳樟醇,香气从清甜柔和变生涩木质,三个月后的成品和刚打样的不是同一支——这是酸性精华里最常见的翻车点。2)与胺类中和剂或高 pH 皂基:碱性下香气发闷,并可能与体系中的醛类副组分反应而变黄。3)与已经氧化(过氧化值偏高)的柑橘油或不饱和油脂同处方:互相促氧化,芳樟醇氧化生成的氢过氧化物是薰衣草油最主要的致敏来源。4)与卡波类增稠剂的水体系:精油需增溶,增溶剂过量会显著拉低卡波黏度,水感变稀。5)与阳离子调理剂(护发):无化学冲突,但香气在冲洗型里留存差,靠加量硬补是浪费,应改用定香策略。6)标签风险:芳樟醇、柠檬烯等致敏组分随加量上升会跨过多个市场的单独标示门槛,这一支最常出问题的环节在标签而不在料体。','见光与遇氧是主要风险:芳樟醇氧化后气味变涩、致敏风险上升,长期在透明玻璃货架下会变黄。高温加速乙酸芳樟酯水解,使香型由清甜转生涩。pH 漂移影响明显,体系从 5.5 掉到 4.0 时香型会有可感知的变化,做酸性精华必须做六个月的香气跟踪,而不是只看外观与 pH 数据。防护做法:棕瓶或不透明包材、避光仓储、25℃ 以下、原料满瓶充氮;料体内配生育酚做油相抗氧并加螯合剂。每批留香气标样,量产按标样比对。','作为香料类原料常规使用,须确认在国内已使用原料目录范围内并按备案资料要求填报;安神、助眠类表述超出化妆品范畴,须回避,以最新官方文本为准。','常规使用;所含致敏性香料组分达到标示门槛时须在成分表单独列出,加量上去后极易跨过门槛,按当前清单复核,以最新官方文本为准。','作为化妆品香料原料常规使用;香气与放松方向的表述须避免进入药效范畴,以最新官方文本为准。','日韩及东南亚主要市场常规使用,部分市场对香料致敏组分标示与精油总量另有要求,按目标国规则复核,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。稀释规格若以乙醇为载体,清真线须换载体或索取相应说明。','mid','降温至 40℃ 以下加入;沐浴、洗发类高表活体系可与香精一起在降温阶段加。若客户要求做天然无香精定位,薰衣草油实际就在承担香精角色,报价时要把成本与批次香气波动一并说清:不同产地(法国高海拔、保加利亚、新疆)酯含量差异大,香型不可能靠一次打样锁死,合同里要保留香型复核环节与标准留样条款。高浓度会溶胀 PS 与部分密封垫,滴管胶头选丁基胶或氟胶。与薄荷、茶树共线必须清线,与其它花香型共线风险较小。','soothing','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('rosa-damascena-flower-oil','Rosa Damascena Flower Oil','大马士革玫瑰花油','玫瑰精油,奥图玫瑰,保加利亚玫瑰油,Rose Otto,Rosa damascena','8007-01-0(玫瑰油通用登记号;另见 90106-38-0,以供应商 COA 批次文件为准)','精油','conditioning','由大马士革玫瑰花蒸馏所得,主要含香茅醇、香叶醇、橙花醇与微量 β-突厥酮,香气强度极高,通常以万分之几的加量就决定整支产品的香型。在配方中是感官与价值感组分,不承担功能主体角色。它与玫瑰纯露、玫瑰净油是三种不同原料,不能互换。','0.005–0.05%(公开配方学常见区间,非法规限值);超过 0.1% 香气会压过整体香型设计并显著抬高成本','serum,essence,cream,oil,balm','4.5–7.5','1)最大的冲突不在化学而在概念:玫瑰纯露(Rosa Damascena Flower Water)与玫瑰花油价格差两三个数量级,客户常拿纯露的预算谈精油,或者希望成分表里出现 Flower Oil 却只肯付纯露的钱。报价前必须把 INCI 写到部位与形态,并在报价单上分行列示。2)掺假普遍:常见以合成香叶醇/香茅醇、天竺葵油、棕榈玫瑰(Cymbopogon martinii)勾兑,仅凭气味无法判定,须 GC-MS 指纹图谱加产地与蒸馏批次证明。3)与高 pH 皂基或含醛香料共处:醇类主组分与醛发生缩合,香气发闷发苦。4)与含铁的植提或矿物色素:微量酚类与铁离子络合,浅色乳霜出现灰粉调。5)与高浓度乙醇的水醇体系:澄清度好,但乙醇纯度不足(含醛类杂质)会让玫瑰香在两个月内明显衰减。','香气组分对氧与光敏感,高温下 β-突厥酮等微量组分损失最快,香型会变平变薄。一个必须写进来料标准的常识:玫瑰花油在低温下会因所含蜡质(硬脂脑)析出而凝固变浑,回温摇匀即恢复,这是正常现象,不写清楚仓库会当作变质退货。防护做法:2–20℃ 避光、满瓶充氮保存,开封后尽快分装小瓶使用;成品避免长期强光货架。来料按批索取 GC-MS 图谱、产地与蒸馏批次。','作为香料类原料常规使用,须确认在国内已使用原料目录范围内并按备案要求填报;以最新官方文本为准。','常规使用;所含致敏性香料组分达标示门槛时须单独列出,由于加量极低通常压力较小,仍按当前清单复核,以最新官方文本为准。','作为化妆品香料原料常规使用,以最新官方文本为准。','日韩及中东市场接受度高,常规使用;部分市场对香料致敏组分标示另有要求,按目标国规则复核,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。中东线客户对玫瑰油的来源文件要求普遍较严,建议一并准备产地与蒸馏说明。','high','加量极低,必须先做成 1% 或 10% 的载体预混母液(常用辛酸/癸酸甘油三酯或香精基)再按母液投料;直接称量克级原油会造成批次间香型明显差异。降温到 40℃ 以下、乳化完成后加入。计量器具专用,不与其它香型共用,残留会串味。成本沟通上有个实用做法:很多客户要的是标签上出现玫瑰花油的效果,可以用极低量精油加纯露加可控香精的组合达成目标香型与成本,前提是标签逐项如实标注——这件事应该在报价环节主动说,而不是等客户看到 BOM。高价原料建议按小包装采购,减少开封后氧化与挥发损耗。','二选一,不要保留现状:(a) 先把 aroma-signature / warming-sensorial / cooling-sensorial 三个 slug 正式登记进 trends.claim_tag 与 CLAIM_LABEL(给出中英文名,如 aroma-signature=香气标识/Signature aroma),再入库;(b) 词表不扩时,这 6 条的 claim_tag 按 schema 默认留空 "",不要写一个下游解析不了的值。','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('anthemis-nobilis-flower-oil','Anthemis Nobilis Flower Oil','罗马洋甘菊花油','罗马洋甘菊精油,果香菊油,Roman Chamomile Oil,Anthemis nobilis,Chamaemelum nobile','8015-92-7(罗马洋甘菊油通用登记号;另见 84649-86-5,以供应商 COA 批次文件为准)','精油','soothing,conditioning','主要成分是当归酸酯类(异丁基当归酸酯等),香气偏甜果苹果调、扩散性极强,常用于放松与舒缓的香气方向。必须注意它与常见的洋甘菊提取物(Chamomilla Recutita 花提取物)不是同一原料:后者是水或醇提物,按提取物用量投料,两者的常用加量差 10 到 100 倍。','0.01–0.1%(公开配方学常见区间,非法规限值);做淡香或无香定位时建议控制在 0.02% 以下','serum,cream,lotion,oil,mask','4.5–7.0','1)与洋甘菊提取物混谈是这一支最常见的失误:客户拿着写有洋甘菊 2% 的方案过来,若照搬到花油上就是 20 到 200 倍过量,香型完全崩掉、刺激与成本同时失控。写方案与报价必须把 INCI 写全到部位与形态。2)香气扩散性强,与柑橘调、皂感香精同用会直接盖过对方,整支产品的香型设计会被它一家改写。3)与高浓度阴离子表活的洁面、沐浴体系:当归酸酯在偏碱条件下水解,三个月后甜果香转酸味。4)与含醛香料共存:甜果调变成药感,是很多打样通过、量产被否的原因。5)与德国洋甘菊油(Chamomilla Recutita 油,含母菊天蓝烃、呈蓝色)混用:颜色会明显偏蓝绿,浅色配方必须重新配色,两者不能互相替代。','见光变深、遇氧香气变钝;当归酸酯类在偏碱与高温下水解,pH 超过 7.5 长期存放香气衰减明显。防护做法:棕瓶避光、25℃ 以下、满瓶保存,料体内配生育酚;成品优先不透明包材。产地与年份造成的香气差异明显,打样与量产尽量用同一批原料,换批必须做香气比对并留标样。高浓度长期与 PE 内壁接触会被吸附而使香气衰减,长期存放优先玻璃或带涂层内衬的包材。','作为香料类原料常规使用,须确认在国内已使用原料目录范围内并按备案要求填报;舒缓、镇静类表述涉及功效宣称管理,按当前规则评估,以最新官方文本为准。','常规使用;所含致敏性香料组分达标示门槛时须单独列出,按当前清单复核,以最新官方文本为准。','作为化妆品香料原料常规使用,以最新官方文本为准。','日韩及东南亚主要市场常规使用,部分市场对香料致敏组分标示另有要求,按目标国规则复核,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。稀释规格的载体要单独确认。','high','用量极小,必须先配成 1% 到 10% 母液再投料,称重计量,不用体积估量。降温至 40℃ 以下加入。这一支的产地与年份差异大,打样与量产要用同批或经过香气比对的批次,并保留标样。计量器具与管路专用,残留会把下一批次带成甜果调,共线必须彻底清线。高浓度与聚乙烯部件长期接触会有香气吸附,内衬与滴管材质要做相容性试验。','soothing','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('pogostemon-cablin-oil','Pogostemon Cablin Oil','广藿香油','广藿香精油,藿香油,Patchouli Oil,Pogostemon cablin','8014-09-3(广藿香油通用登记号;另见 84238-39-1,以供应商 COA 批次文件为准)','精油','conditioning,soothing','主要成分是广藿香醇与多种倍半萜,分子量大、挥发慢,是东方调与中式草本香型的定香骨架,能把上层的柑橘与花香拖住,延长整体留香。颜色深、气味强,自身带明显的木土调性格,加量稍高就会主导整支产品的香气结构。','0.02–0.3%(公开配方学常见区间,非法规限值);仅作定香用途时 0.05% 上下常已足够','cream,balm,oil,lotion,stick','4.0–8.0','1)颜色是头号问题:原油呈深琥珀到棕色,加到 0.1% 以上就会把白色乳霜带成米灰或浅褐调,做纯白膏体的客户会直接判色差不良。配色必须按最终加量在打样阶段确认,不能用低浓度小样去推断量产颜色。2)与二氧化钛、氧化锌等白色粉体同处方:粉体盖不住这层灰调,反而会让色调看起来更脏。3)与含铁离子的体系或铁质设备接触:倍半萜氧化产物与铁络合,颜色进一步加深。4)与柑橘类精油共用:广藿香会压住柑橘头香,清爽定位的产品要控在 0.03% 以下。5)与阳离子调理体系(护发)无化学冲突,但会显著提高发上残留香强度,留香设计要重算。6)气味残留极强,是车间、储罐与管路串味的高风险原料。','相对稳定,不易酸败,长期存放反而会陈化使香气更圆润,这是它区别于柑橘类精油的重要特点。主要变化是颜色随时间与光照加深,以及低温下黏度上升、取料困难。pH 4.0 到 8.0 内香气基本稳定,对碱性体系耐受性好于酯类为主的花油。建议避光常温保存,不需要冷藏,但仍要满瓶避免长期敞口。浅色配方要把颜色随时间加深这件事纳入稳定性考核项,而不是只看分层与 pH。','作为香料类原料常规使用,须确认在国内已使用原料目录范围内并按备案要求填报,以最新官方文本为准。','常规使用;所含致敏性香料组分达标示门槛时须单独列出,按当前清单复核,以最新官方文本为准。','作为化妆品香料原料常规使用,以最新官方文本为准。','东南亚为主要产地,区域内常规使用;部分市场对香料致敏组分标示另有要求,按目标国规则复核,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。','mid','挥发性低,可在 40 到 45℃ 以下加入,损失不大,但仍不要走全程加热段。黏度大,冬季会变稠,取料前建议 35 到 40℃ 温和水浴整桶回温混匀,不要局部高温或明火加热。计量器具、储罐、软管专用,含广藿香的批次建议排在当日最后,生产完必须彻底清线,残留会在下一批浅香型产品里被立刻闻出来。放大生产的坑:小样用移液枪加、量产用泵送,管路残留会让实际加量高于设计值,颜色与香气一起偏——要按管路容积做补偿或改用称重投料。',NULL,'高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('citrus-aurantium-amara-flower-oil','Citrus Aurantium Amara Flower Oil','橙花油','苦橙花精油,内洛里油,Neroli Oil,Citrus aurantium amara,Citrus aurantium var. amara','8016-38-4(橙花油通用登记号;另见 72968-50-4,以供应商 COA 批次文件为准)','精油','conditioning,soothing','由苦橙花蒸馏所得,主要含芳樟醇、乙酸芳樟酯、橙花叔醇与微量吲哚,香气清透带绿感,是高端天然香气路线常用的花油。它在配方中是感官与品牌调性组分,负责建立香型与价值感,不承担功能主体角色。','0.02–0.2%(公开配方学常见区间,非法规限值)','serum,essence,cream,oil,toner','4.5–7.0','1)最贵的一次误会是与苦橙叶油(Citrus Aurantium Amara Leaf/Twig Oil,petitgrain)混谈:后者价格低一个量级、香气偏绿木,不能等量替换,报价与合同必须把 INCI 写到部位。2)成本陷阱:做天然无香精定位的客户常要求单靠橙花油撑起整支香型,加到 0.3% 到 0.5% 时香料成本可能超过整个料体成本,这一点应当在报价阶段主动点破,而不是等客户看到 BOM 再解释。3)与柑橘皮类精油同用:头香冲突,会把橙花的花感压成柑橘香皂调。4)与含醛香料或高 pH 皂基:酯类水解、吲哚类变味,香型发闷甚至带出动物感。5)与高浓度乙醇体系:澄清度好,但会放大绿感,与柔和花香的目标不符,需要重新调配比而不是加量。6)芳樟醇、柠檬烯等致敏组分随加量上升会跨过多市场的单独标示门槛,标签要同步更新。','见光变黄、遇氧香气变钝;酯类在偏酸与高温下水解使香型走样,微量吲哚在碱性与高温下容易带出不受欢迎的动物感异味。防护做法:棕瓶避光、15 到 25℃、满瓶充氮保存,开封后分装小瓶;成品用不透明包材。掺假常见(以合成芳樟醇加苦橙叶油勾兑),仅凭香气无法判定,来料须按批索取 GC-MS 图谱与产地证明。年用量小的客户建议一次只备一个批次,避免不同批陈化差异带来的香型跳变。','作为香料类原料常规使用,须确认在国内已使用原料目录范围内并按备案要求填报,以最新官方文本为准。','常规使用;所含致敏性香料组分达标示门槛时须单独列出,按当前清单复核,以最新官方文本为准。','作为化妆品香料原料常规使用,以最新官方文本为准。','日韩及中东市场接受度高,常规使用;部分市场对香料致敏组分标示另有要求,按目标国规则复核,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。稀释规格若以乙醇为载体,清真与中东线须换载体。','high','高价原料,按 1% 到 10% 母液投料并采用称重计量。降温到 40℃ 以下加入,不进乳化加热段。小包装采购,开封后按周期复检香气。报价上有个有效做法:同一配方同时给出橙花油主导版与橙花油加可控香精版两套报价,把香型与成本的取舍交给客户自己选,比反复解释单价更容易推进。计量器具专用,共线需清线。',NULL,'中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('citrus-aurantium-bergamia-fruit-oil','Citrus Aurantium Bergamia Fruit Oil','佛手柑(果)油','香柠檬油,佛手柑精油,Bergamot Oil,Citrus aurantium bergamia,Citrus bergamia','8007-75-8(佛手柑油通用登记号;另见 89957-91-5,以供应商 COA 批次文件为准)','精油','conditioning','佛手柑果皮冷压所得,主要含柠檬烯与乙酸芳樟酯,香气清亮,是柑橘调头香的主力。冷压规格同时带入呋喃香豆素类(以佛手柑内酯为代表),这是它区别于其它柑橘油的关键点,也决定了它必须按规格分开采购与报价。','去呋喃香豆素(FCF)规格驻留型 0.1–0.5%;含呋喃香豆素的冷压规格用于驻留型时须显著更低并单独做安全评估(公开配方学常见区间,非法规限值)','cream,lotion,gel,oil,foam,balm','4.0–7.0','1)最经典的翻车点:含呋喃香豆素的冷压佛手柑油用在驻留型产品上会带来光敏风险,与防晒、亮肤方向的产品定位直接冲突。驻留型一律优先 FCF(去佛手柑内酯)规格,并在报价单与 BOM 上把两种规格分开列价、给不同物料编码——采购常常只看佛手柑油五个字下单,拿到便宜的冷压规格就出事。2)与其它柑橘油、松节类精油叠加:体系柠檬烯总量上去,氧化产物增多,刺激与致敏叠加。3)与不饱和油脂共处高油相:互相促氧化,产生哈败味。4)与铁、铜离子:催化柠檬烯自氧化,香气从清亮转旧橘子皮味。5)与阳离子表活体系:无化学冲突,但柑橘头香在冲洗型里几乎留不住,靠加量补是浪费,应改用定香策略。6)与高浓度乙醇:澄清但氧化更快,必须配抗氧剂并缩短保质期设计。','柑橘类里最不稳定的一支:柠檬烯遇氧、光、热迅速自氧化,气味由清亮转酸旧,过氧化值上升,刺激与致敏风险随之上升。冷压规格含天然色素与蜡质,低温会析出而浑浊,回温后恢复,这一点要写进来料标准避免仓库误判为变质。防护做法:充氮满瓶、2 到 15℃ 冷藏避光、开封后尽快用完;料体内配 0.1% 左右生育酚与 0.05 到 0.1% 螯合剂;成品用不透明包材并适当缩短保质期设计。建议按批检过氧化值,长期库存复检。','作为香料类原料常规使用,须确认在国内已使用原料目录范围内并按备案要求填报;呋喃香豆素与光敏相关的安全评估须一并提供,以最新官方文本为准。','常规使用,但多个市场对化妆品中呋喃香豆素总量有明确关注与限制方向,驻留型产品须按当前规则核算并优先 FCF 规格,以最新官方文本为准。','作为化妆品香料原料常规使用;光敏相关风险须在安全评估与标签警示中体现,按当前规则处理,以最新官方文本为准。','日韩及东南亚主要市场常规使用;呋喃香豆素与致敏组分标示按目标国规则逐一复核,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。','mid','改为「是否 FCF、是否去萜(无萜/折叠规格)、冷压还是蒸馏」。',NULL,'高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('zingiber-officinale-root-oil','Zingiber Officinale Root Oil','姜根油','生姜精油,姜油,Ginger Root Oil,Zingiber officinale','8007-08-7(姜油通用登记号;另见 84696-15-1,以供应商 COA 批次文件为准)','精油','conditioning','把热感相关内容统一收口到规格上。incompatible 第 1、2 条改为:「1)与薄荷脑、薄荷油同用:蒸馏姜油本身的热感有限,冷热同用的卖点通常要靠 CO2 萃取物或姜油树脂实现;若配方里同时存在这两类姜原料与凉感剂,主观刺激会明显强于各自单用,眼周与颈部产品不建议同时上量。2)与辣椒素类(Capsicum 提取物、壬酰香草胺):热感叠加最容易出事故的一组,但叠加风险主要来自姜油树脂/CO2 萃取物一侧;总热感组分须按最低有效量设计并做梯度人体测试。」stability 末句改为:「一是长期存放后的颜色变化对浅色配方的影响,二是辛辣香气强度随存放时间的衰减(热感诉求若由姜油树脂承担,则该项应对树脂规格单独考核)。」factory_note 中「打样阶段就要做梯度…把热感刚好的点定下来」改为「打样阶段就要做梯度(如 0.05/0.1/0.2%)人体耐受与感官对照,把辛辣香气与刺激的可接受点定下来;若客户诉求是明确热感,应改用姜油树脂或 CO2 萃取物并单独评估,不要靠拉高蒸馏油加量硬凑。」','驻留型 0.05–0.3%,按摩油类可到 0.5%(公开配方学常见区间,非法规限值);刺激阈值窄,提高加量前必须有人体耐受数据支持','oil,balm,cream,lotion,stick','4.0–7.5','1)与薄荷脑、薄荷油同用:冷热同用是常见卖点,但两条感觉通路叠加后主观刺激明显强于各自单用,眼周与颈部产品不建议两者同时上量;要做先凉后热应通过释放速度(包裹、油相分配)来实现,而不是靠单纯加量。2)与辣椒素类(Capsicum 提取物、壬酰香草胺):热感叠加最容易出事故的一组,同用时总热感组分必须按最低有效量设计并做梯度人体测试,不能在配方阶段凭经验定。3)与高浓度乙醇或高比例丙二醇等渗透促进体系:渗透加快,刺激阈值下降,原本可耐受的加量会变刺痛。4)与阴离子表活的洁面、沐浴:冲洗时残留在眼周等敏感部位风险高,冲洗型建议加量减半并加强警示语设计。5)与铁离子或高 pH 体系:颜色加深发暗,浅色乳液会转米黄。6)与含醛香精:辛辣感被放大成药味,香型设计要重做。','倍半萜为主,不易酸败,但见光与高温下颜色加深、香气变钝,长时间高温加热会损失头段香只剩闷辣。pH 4.0 到 7.5 内相对稳定,强碱体系下香气变化明显。建议棕瓶避光、25℃ 以下、满瓶保存,料体内配生育酚。稳定性考核要额外关注两点:一是长期存放后的颜色变化对浅色配方的影响,二是热感强度是否随存放时间衰减——热感衰减会直接引发客户投诉配方没做到位,应在保质期设计里做感官跟踪而不只做理化跟踪。','作为香料/植物精油类原料常规使用,须确认在国内已使用原料目录范围内并按备案要求填报;发热、活血类表述超出化妆品范畴,须回避,以最新官方文本为准。','常规使用;所含致敏性香料组分达标示门槛时须单独列出,安全评估中须体现刺激性评价,按当前规则复核,以最新官方文本为准。','作为化妆品原料常规使用;若以缓解酸痛等方向宣传可能进入非处方药路径,须由法规评估,以最新官方文本为准。','日韩及东南亚主要市场常规使用,部分市场对刺激性原料与致敏组分标示另有要求,按目标国规则复核,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。','mid','降温到 40℃ 以下加入。用量小且刺激阈值窄,必须用母液法投料并采用称重计量,严禁体积估量;管路残留会让实际加量偏高,这一支偏高就是投诉。打样阶段就要做梯度(如 0.05 / 0.1 / 0.2%)人体耐受与感官对照,把热感刚好的点定下来再放大,不要等量产后再调。原油直接接触皮肤会刺痛,操作时须戴手套并做好眼部防护。气味强,与花香型共线必须清线。高浓度对部分密封垫有溶胀,滴管与泵头做相容性试验。',NULL,'中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('mentha-piperita-oil','Mentha Piperita Oil','薄荷油','胡椒薄荷精油,欧薄荷油,Peppermint Oil,Mentha piperita','8006-90-4(薄荷油通用登记号;另见 84082-70-2,以供应商 COA 批次文件为准)','精油','cooling,conditioning','主要成分为薄荷脑与薄荷酮,通过作用于皮肤的冷觉感受通路产生即时清凉感,是头皮、足部与身体清爽线最直观的感官加分项。它提供的是感觉信号而不是实际降温,文案上不应写成降温或退热。','驻留型 0.05–0.3%,头皮与足部产品 0.1–0.5%;眼周产品建议不使用,确需使用应控制在 0.02% 以下(公开配方学常见区间,非法规限值)','gel,foam,toner,lotion,stick,balm','4.0–8.0','1)眼周是这一支的红线:薄荷脑挥发性高,即便不直接接触眼睛,眼霜、眼膜在使用过程中的挥发也足以造成流泪刺痛。眼部产品要么不用,要么用包埋缓释体系并显著降低加量,同时单独做眼刺激评估。2)与薄荷脑单体或 WS-3 等合成清凉剂同用:凉感是叠加的,很多配方两个地方都加了凉却只按一处算量,量产后被投诉太冲——BOM 上要统一折算凉感当量再定总量。3)与姜、辣椒、肉桂类热感组分:冷热叠加会明显提高主观刺激强度,参见姜根油条目。4)与乙醇、高浓度多元醇:挥发与渗透加快,凉感更冲,刺激阈值下降。5)与硅油、高含量油相或阳离子调理剂:无化学冲突,但会拖慢薄荷脑释放使凉感变钝,客户会误以为没加够而要求加量,正确做法是调整释放而不是加量。6)与高含量固体油脂的膏体同处方:冷藏后表面可能出现薄荷脑白色结晶点,被判外观不良。','首要问题是挥发损失:敞口搅拌、高温投料、投料后到灌装的长时间等待都会显著降低成品凉感,是批次间凉感不一致的主因。薄荷酮在光照与氧下变化,气味转闷,颜色由无色转淡黄。低温析晶也要注意:原料在约 10℃ 以下可能析出薄荷脑结晶,取料前需整桶温和回温混匀,不可只取上层清液,否则批次浓度不均。建议密闭避光、25℃ 以下、满桶保存;成品用密封性好的包材,喷雾与敞口罐装形式凉感衰减更快,保质期设计要考虑这一点。','作为香料/植物精油类原料常规使用,须确认在国内已使用原料目录范围内并按备案要求填报;清凉、镇痛类表述涉及品类边界,须回避,以最新官方文本为准。','常规使用;所含致敏性香料组分达标示门槛时须单独列出,安全评估中须体现眼刺激与皮肤刺激评价,按当前规则复核,以最新官方文本为准。','作为化妆品原料常规使用;若以止痒、镇痛方向宣传可能进入非处方药路径,须由法规评估,以最新官方文本为准。','日韩及东南亚清凉型产品接受度高,常规使用;部分市场对儿童产品中的薄荷类原料另有关注,按目标国规则复核,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。','low','必须在 35 到 40℃ 以下、密闭低速搅拌加入,搅拌时间尽量短——每多一次敞口搅拌,凉感就掉一档。投料完成到灌装的等待时间要写进工艺卡并固定下来,否则同一配方不同批凉感不同这个投诉永远解决不了。水基体系需增溶,增溶不足时薄荷脑会在瓶壁析出白点。原料桶低温析晶时整桶温和回温混匀后再取,不要只取上层。对 PS、部分 PET 与部分印刷油墨有溶胀或褪色风险,直接接触料体的部件与内印必须做相容性试验。气味极强且扩散快,必须独立排产并彻底清线,共线后下一批产品带凉味是常见事故。',NULL,'高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('santalum-album-oil','Santalum Album Oil','檀香油','东印度檀香精油,白檀油,Sandalwood Oil,Santalum album','8006-87-9(檀香油通用登记号;另见 84787-70-2,以供应商 COA 批次文件为准)','精油','conditioning,soothing','以 α-檀香醇与 β-檀香醇为主,分子量大、挥发极慢,是东方调的核心底香与定香材料,极少量就能改变整支产品的香气结构与留香曲线。在配方中是感官与品牌调性组分,不承担功能主体角色。','0.05–0.5%(公开配方学常见区间,非法规限值);仅作底香时 0.1% 上下常已足够','oil,balm,cream,serum,stick','4.0–8.0','1)物种混淆是第一大坑:澳洲檀香(Santalum spicatum)、太平洋檀香(Santalum austrocaledonicum),以及被叫作西印度檀香但根本不是檀香属的 Amyris balsamifera,INCI 不同、香气不同、价格差数倍,合同与 BOM 上不能只写檀香油三个字。2)掺假极普遍:合成檀香醇类香料、蓖麻油、Amyris 油勾兑常见,仅靠香气无法判定,须 GC-MS 加手性或同位素分析,并配合供应链文件。3)与浅色配方:原油呈淡黄到黄色,高加量会带黄调,白色膏体需预留配色空间。4)与柑橘头香:檀香会把柑橘拖沉,做清爽定位时应改用更轻的木质材料。5)与含醛香精:结合过度会出现肥皂加木质的混浊感,调香阶段必须试配。6)与高 pH 皂基:整体耐受,但长期存放檀香醇缓慢氧化会使香气变干柴。','挥发性极低,是精油里最稳定的一类,常温避光可长期保存,陈化后香气更圆润。主要变化是黏度随温度波动明显、低温取料困难,以及长期强光下颜色加深。pH 4.0 到 8.0 内香气基本稳定。建议避光常温、满瓶保存,不需要冷藏。稳定性考核重点放在颜色随时间的变化(影响浅色配方)与包材吸香,而不是氧化酸败。','作为香料类原料常规使用,须确认在国内已使用原料目录范围内并按备案要求填报;来源合法性文件建议随备案资料一并留档,以最新官方文本为准。','常规使用;所含致敏性香料组分达标示门槛时须单独列出,同时须确认原料来源符合当前的濒危物种与木材来源相关要求,按当前官方名录与规则核实,以最新官方文本为准。','作为化妆品香料原料常规使用;进口环节可能涉及植物来源申报与来源合法性证明,按当前规则核实,以最新官方文本为准。','印度、澳大利亚为主要来源地,区域内常规使用;出口环节的来源与采伐许可要求各国不同,按目标国规则逐一核实,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。中东与南亚客户对檀香的来源国与合法性文件要求普遍较严,建议随样品一并提供。','high','供应链文件是这一支的交付重点:出海高端线客户几乎一定会索取植物来源国、种植园或采伐许可、可追溯批号、GC-MS 图谱,以及供应商关于来源合法性的书面声明。印度天然林檀香受严格管制,商业供应主要来自澳大利亚等地的人工种植 Santalum album 与合法种植园,是否涉及国际贸易管制名录须按当前官方文本核实,不要凭经验答复客户。这些文件应在接单阶段就向上游要齐,不要等客户审厂时才补。工艺上:黏稠,冬季取料前 35 到 40℃ 温和整桶回温混匀,不要局部加热或明火;40 到 45℃ 以下加入,挥发损失小但仍不进加热段;高价料按母液法投料并称重计量,管路与器具残留的损耗在高价料上直接体现在成本,建议小批次专用管路或小包装直投。气味留存久,共线需彻底清线。',NULL,'中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('tremella-fuciformis-polysaccharide','Tremella Fuciformis Polysaccharide','银耳多糖','aliases 改为「银耳多糖,白木耳多糖,雪耳提取物,Tremella fuciformis,Tremella Fuciformis Extract」','未确认','多糖','hydrating,barrier,soothing','银耳子实体水提得到的高分子量酸性杂多糖,水溶后形成黏度很高的假塑性溶液,在皮肤表面留下连续的柔性水膜,有助于减缓表层水分散失并带来滑而不腻的铺展感。在配方里同时承担保湿方向与流变调节两个角色,常被用作合成保湿聚合物的天然替代路线。','0.1–1%(以固体粉计;公开配方学常见区间,非法规限值)','serum,essence,toner,mask,gel,cream,lotion','4.0–7.5','呈阴离子性,与阳离子聚合物(聚季铵盐-7/-10、瓜尔胶羟丙基三甲基氯化铵)或阳离子表活混合会电荷中和,出现絮状浑浊、挂壁沉积,黏度骤降。高浓度电解质(氯化钠、硫酸镁、盐形式的活性物、含盐海藻提取物)会压缩分子链,黏度明显下降。乙醇超过约 20% 会使多糖脱水析出、体系返浊。与卡波姆或丙烯酸酯类增稠剂叠加时黏度不是线性相加,常出现过稠、拉丝、涂抹起白条,必须重新配平两者用量而不是各自照抄单用量。高浓度过氧化物类氧化性原料会切断多糖链,存放期黏度持续下滑。','干粉吸湿性强,开封后必须密封干燥保存,受潮后结块并难以完全水合。水溶液在 80 ℃ 以上长时间保温会发生链段降解,黏度不可逆下降;pH 低于 3.5 或明显偏碱同样引起水解。溶液本身营养丰富,是良好的微生物培养基,配好的胶浆不可隔夜存放,必须在防腐体系内配制并做防腐挑战。见光影响相对小,但与游离金属离子共存时氧化降解加快,建议配合螯合剂。最关键的一点是批次间分子量与黏度差异明显,同样百分比做出的成品稠度可能差一个档,应按目标黏度而不是固定百分比投料。','作为真菌来源提取物类原料常规使用,需与供应商核对该原料在中国的已使用原料信息与来源物种一致性,以最新官方文本为准。','作为化妆品原料常规使用,由供应商提供安全数据与规格支持,以最新官方文本为准。','常规使用,按目标市场规则复核,以最新官方文本为准。','日韩与东南亚常规使用,部分市场对真菌来源原料要求补充来源与工艺说明,以最新官方文本为准。','食用真菌来源,通常可做 vegan;清真需供应商出具证明,并确认提取、沉淀与干燥环节使用的助剂与乙醇残留说明。','mid','干粉必须先用冷水或甘油/丙二醇预分散再撒入水相,直接倒入静止水中表面瞬间水合会结成鱼眼,一旦形成搅不开只能过筛。推荐先配 1–2% 母液,慢搅后静置过夜让其完全水合,再按比例并入主锅,批次一致性明显更好。水相加热控制在 70–75 ℃ 以内并缩短保温时间;乳化体系建议在降温到 45 ℃ 以下并入母液。水合完成后只用桨式慢搅,高速均质会剪切降黏且不可恢复。放大生产最大的坑是每批原料黏度不同,必须在小样阶段建立黏度—添加量对照曲线,并把成品黏度写进过程检验项,而不是只核对投料百分比。','hydration','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('laminaria-digitata-extract','Laminaria Digitata Extract','掌状海带提取物','掌状海带提取物,海带提取物,褐藻提取物,Laminaria digitata,Oarweed,Kelp Extract','未确认','植物提取物','soothing','褐藻来源的水溶性提取物,主要携带褐藻胶(藻酸盐)、岩藻多糖等多糖组分以及天然存在的矿物离子,在配方中提供轻度成膜、保湿与柔滑铺展。常作为海洋来源叙事的载体原料,与草本体系搭配用于质地补充和方向性宣称的支撑。','0.5–3%(以液体提取物计;公开配方学常见区间,非法规限值)','essence,serum,toner,mask,gel,lotion,cream','4.5–8.0','核心坑是自带盐分。海藻类提取物天然含钠、钾、钙、镁等电解质,加入卡波姆或丙烯酸酯类中和体系后会屏蔽羧基电荷,凝胶明显变稀甚至化水,这正是客户说的加了就变稀最常见的元凶;要么改用耐电解质增稠剂(黄原胶、丙烯酰基二甲基牛磺酸铵类共聚物),要么选脱盐型号。其中的钙离子还会与藻酸盐、果胶、低甲氧基果胶、卡拉胶交联,叠加时可能出现颗粒、局部结块或胶皮。阴离子性质使其与阳离子聚合物、阳离子表活配伍容易絮凝沉淀。部分批次带明显海藻腥味,低用量花香型香精盖不住,会在成品放置后返味。','水溶液见光遇氧容易加深颜色(黄褐向深褐漂移),内含酚类与色素对氧化敏感,建议避光包装并配合螯合剂。长时间高温加热会降解多糖、削弱成膜感并加速色变。pH 低于 4 时藻酸类成分容易析出成絮。天然盐分与有机物含量高,微生物负荷是重点风险,来料必须看菌检,配方要留足防腐余量;含较高比例多元醇或乙醇的提取物形态相对稳定。碘与重金属含量随产地与采收季波动,需要每批核对 COA。','海藻类提取物常规使用,需核对原料的中国已使用原料信息与来源物种一致性,以最新官方文本为准。','常规使用,需重点关注碘、砷等元素的来料控制与安全评估资料,以最新官方文本为准。','常规使用,按目标市场规则复核,以最新官方文本为准。','日韩接受度高,常规使用,部分市场要求提供产地与污染物检测资料,以最新官方文本为准。','藻类来源,通常可做 vegan;清真需供应商出具证明,并确认载体溶剂(甘油、丙二醇或乙醇)的来源。','low','属于典型的后加原料,建议乳化或增稠完成、体系降温到 40 ℃ 以下再细流加入,避免长时间受热变色。拿到新批次先做电解质预判:测电导率,或直接做提取物加目标增稠剂的小试黏度对照,再决定增稠体系和用量,不要等主锅做完才发现变稀。若客户坚持卡波体系,把提取物拆分加入或改用耐盐增稠剂,并重新配平中和剂用量。带腥味的批次可先与香精、掩味剂在小锅预混再并入。放大生产中颜色批差比黏度批差更容易被客户投诉,建议保留标准色板做每批比对,并在规格书上写明色泽范围。','hydration','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('tamarindus-indica-seed-gum','Tamarindus Indica Seed Gum','罗望子籽胶','罗望子胶,罗望子籽多糖,酸豆胶,木葡聚糖,Tamarind Seed Polysaccharide,TSP,Tamarindus indica','未确认','多糖','hydrating,barrier,conditioning,soothing','该句改为「因为不带电荷,耐盐、耐 pH 波动的能力比卡波与多数阴离子胶好,肤感顺滑、拉丝感弱,常被用于天然认证配方中替代合成流变剂的手感需求。」','0.2–1.5%(公开配方学常见区间,非法规限值)','serum,essence,gel,lotion,cream,mask,toner','3.5–9.0','非离子性质让它对电解质和 pH 都比较宽容,真正的坑在协同与手感叠加:与黄原胶、卡拉胶、瓜尔胶复配时黏度会协同上升,直接把各自单用量相加常常做出过稠、拉丝或明显胶感的体系。与高分子量透明质酸钠同用会显著加重成膜黏腻和搓泥风险。乙醇超过约 20–25%,或大量多元醇争夺水分,会导致析出与返浊。强氧化性原料(过氧化物、高浓度次氯酸类)会降解多糖链,存放期黏度断崖式下降。含淀粉酶、纤维素酶活性的植物提取物或酶制剂长期共存会缓慢降黏。与阳离子调理剂配伍相对温和,但仍需小试确认外观。','干粉需防潮,受潮后结块难分散。溶液的耐酸碱范围较宽,但 pH 低于 3 或高于 10 长期存放仍会水解降黏。持续 85 ℃ 以上保温会降低黏度,应避免长时间高温和二次返工加热。溶液是微生物易感体系,配好的胶浆不宜隔夜,成品需完整防腐并通过防腐挑战。冻融相对稳定,反复冻融后可能有轻微析水。原料天然带浅黄至米色,高浓度时会影响透明水剂的澄清度与色泽,长期存放可能轻微加深,做全透明产品前要先确认最高可用浓度。','作为植物胶类原料常规使用,需确认原料的中国已使用原料信息,以最新官方文本为准。','常规使用,常见于天然与有机认证配方(是否收录以认证机构清单为准),以最新官方文本为准。','常规使用,按目标市场规则复核,以最新官方文本为准。','日本、印度等地使用历史较长,常规使用,以最新官方文本为准。','植物种子来源,通常可做 vegan;清真需供应商出具证明并确认提取与纯化工艺中的助剂。','mid','分散决定成败:干粉必须与甘油/丙二醇打浆,或与配方中其它粉体干混后再撒入,一次性倒进静水必结团。冷水溶解慢,建议 50–60 ℃ 温水搅拌 20–30 分钟完全水合后再降温;水合未完成时判断黏度必然低估,是过量投料的主要原因。水合阶段可用高速分散头,水合完成后转慢搅,避免过度剪切降黏。与其它胶复配时坚持各自配母液再合并,不要干粉混投,否则局部浓度不均会出胶粒。放大生产同样存在批次黏度差异,建议按目标黏度调整用量,并把黏度与 pH 一起列入过程检验;大锅要防止锅壁挂胶皮,建议配循环泵。','texture-rheology','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('linum-usitatissimum-seed-extract','Linum Usitatissimum (Linseed) Seed Extract','亚麻籽提取物','亚麻籽提取物,亚麻胶,胡麻籽提取物,Flaxseed Extract,Linseed Extract,Linum usitatissimum','未确认','植物提取物','hydrating,soothing,barrier,conditioning','亚麻籽外层水提得到的酸性黏液多糖(以阿拉伯木聚糖、鼠李半乳糖醛酸聚糖为主),在水中形成滑腻的黏液体系,干燥后留下柔软连续的膜,给配方带来水润拉丝的即时肤感和轻微的紧绷收敛感。常用于免洗精华、啫喱与洗护中的天然成膜方向。','液体提取物 0.5–3%,粉状亚麻胶 0.1–0.5%(公开配方学常见区间,非法规限值)','essence,serum,toner,gel,mask,lotion,foam','4.0–7.5','对电解质高度敏感是它最大的限制:高浓度氯化钠、镁盐、盐形式的活性物,以及含盐量高的海藻或发酵提取物,会让黏液脱水收缩,表现为黏度骤降、絮凝甚至分层,和高盐组分同锅必须先小试。阴离子性质使它与阳离子聚合物、阳离子表活(季铵盐类调理剂)复配时产生絮状沉淀。乙醇浓度偏高会直接析出。钙、镁、铝、锌等多价金属离子可能与其交联成粒。与卡波体系叠加时黏度和触感变化不可预测,通常建议二选一,若必须共用则重新配平中和剂用量并做长期观察。','水提黏液耐热性一般,80 ℃ 以上长时间加热会降解并失去特征成膜感,应作为低温后加原料。见光遇氧容易变色(浅黄转黄褐)并可能出现哈味,与来料中残留亚麻籽油脂的氧化有关,建议避光包装、控制来料油脂残留、必要时配合抗氧化与螯合体系。天然营养丰富,微生物风险高,来料菌检与成品防腐挑战都要做足,稀释后的中间体不可存放。pH 明显偏离中性时黏度下降。冻融后可能析水,冬储前要做低温循环考察。','常规使用,需确认原料的中国已使用原料信息与提取部位一致,以最新官方文本为准。','常规使用,由供应商提供安全评估资料与规格,以最新官方文本为准。','常规使用,按目标市场规则复核;若客户有过敏原相关标注需求,需另行向供应商索取来源信息,以最新官方文本为准。','常规使用,按目标市场规则复核,以最新官方文本为准。','植物种子来源,通常可做 vegan;清真需供应商出具证明并确认提取溶剂与防腐载体。','low','做后加:乳化或增稠完成、体系降到 40 ℃ 以下再加入,先用部分水或甘油稀释后细流并入,直接倒进高黏体系会形成局部胶团且搅不散。投料前把配方里所有含盐组分点一遍,把它和高盐活性物分开阶段加入,并在盐加完之后再补加,同时观察黏度变化,这一步能避免大部分放大失败。若使用粉状亚麻胶,预分散方式与罗望子胶相同,先与多元醇打浆。水合完成后不要再高速均质,剪切会破坏黏液特有的拉丝感。批次间黏度与颜色差异较大,加料速度过快会造成局部过浓结块,建议用计量泵细流加入并全程中速搅拌。','hydration','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('carrageenan','Carrageenan','角叉菜胶','卡拉胶,鹿角菜胶,角叉菜提取物,爱尔兰苔,Chondrus crispus,Irish Moss,kappa 卡拉胶,iota 卡拉胶,lambda 卡拉胶','9000-07-1','多糖','hydrating,barrier,soothing','红藻来源的硫酸化半乳聚糖,按硫酸基位置与数量分为三型:kappa 型遇钾离子形成脆硬凝胶,iota 型遇钙离子形成弹性触变凝胶,lambda 型不成胶只增稠。配方中用于构建面膜液与凝胶的骨架结构、悬浮粉体与油滴,并提供水润顺滑的铺展。','0.1–1.5%(按型号与目标质地差异很大;公开配方学常见区间,非法规限值)','mask,gel,essence,lotion,cream,toner','5.0–9.0(酸性条件下会逐步降解)','离子敏感是最典型的翻车点。钾离子(氯化钾、山梨酸钾、含钾的调 pH 剂)会让 kappa 型迅速成刚性凝胶、结块并脱水收缩析水;钙离子(硬水、氯化钙、乳酸钙、含矿物的植提)会让 iota 型过度成胶。因此生产用水的硬度直接决定成品质地,不同车间用不同水源就会出批次差。酸性条件(pH 低于 4.5)下硫酸酯键水解,黏度与凝胶强度随存放时间不可逆下降,酸性加高温同时存在最伤。阴离子性质使其与阳离子聚合物、阳离子表活絮凝沉淀。与高浓度乙醇不相容会析出。与刺槐豆胶、魔芋胶存在强协同,叠加后凝胶强度远超预期。','干粉稳定,溶液稳定性由 pH 主导:中性至微碱最稳,pH 低于 4 存放会持续降解,货架末期黏度显著衰减,酸性配方要么换胶,要么接受衰减并做完整加速考察。溶解需要 75–80 ℃,单纯高温可耐受,但酸性条件下加热会成倍加速降解。成胶后的体系在储运震动与温度波动下可能脱水收缩析水,通常靠调整型号比例或复配少量其它胶抑制。冻融性差,凝胶结构一旦破坏不可恢复。微生物易感,需要完整防腐体系与来料菌数控制。','常规使用,以最新官方文本为准。','常规使用,由供应商提供规格与安全评估资料,以最新官方文本为准。','常规使用,按目标市场规则复核,以最新官方文本为准。','常规使用,以最新官方文本为准。','红藻来源,通常可做 vegan;清真需供应商出具证明并确认加工助剂。','low','必须在 75–80 ℃ 充分搅拌溶解至溶液透明,溶解不完全会在冷却后出现颗粒或局部胶块,后期无法补救。凝胶是在冷却过程中形成的,降温速率与是否静置直接决定最终质地,大锅慢冷与小样快冷手感不同,放大时要把降温曲线固定下来写进工艺卡。干粉与糖、甘油或其它粉体预混后撒入,不可直接倒进热水。生产用水必须统一为纯化水并监测电导率。含钾、钙的原料(氯化钾、山梨酸钾、乳酸钙、含矿物植提)一律安排在胶完全溶解并降温后再慢加分散。柠檬酸、乳酸等调 pH 放在最后、温度降到 45 ℃ 以下再做。凝胶形成后避免高剪切。面膜液灌装必须在凝胶点以上的温度完成,否则拉丝挂壁、装量不准。','texture-rheology','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('pectin','Pectin','果胶','果胶,柑橘果胶,苹果果胶,高甲氧基果胶 HM,低甲氧基果胶 LM,Citrus Pectin,Citrus spp.','9000-69-5','多糖','hydrating,barrier,soothing,conditioning','来自柑橘皮或苹果渣的半乳糖醛酸聚合物,按甲酯化度分为高甲氧基(HM)与低甲氧基(LM)两类:HM 在低 pH 与较高糖或多元醇含量下成胶,LM 依靠钙离子交联成胶。配方中用作天然增稠与成膜组分,在酸性精华、果酸类与发酵体系里的表现好于多数胶体。','0.2–1.5%(公开配方学常见区间,非法规限值)','essence,serum,gel,mask,lotion,toner,cream','3.0–6.0(酸性体系表现最好)','钙与多价离子是双刃剑:LM 果胶遇钙立即交联,微量硬水钙或含钙提取物就足以让体系起颗粒、结块,若要利用它成胶,钙必须做成缓释形式或在强搅下极缓慢加入。pH 高于约 6.5 时果胶发生 β-消除降解,黏度快速下降,因此不适合皂基与高 pH 体系,和碱性调理剂同用要重新评估。阴离子性质使其与阳离子聚合物、阳离子表活絮凝。与卡拉胶、海藻酸盐、刺槐豆胶等其它胶体叠加时协同效应明显,黏度与凝胶强度常远超线性叠加,必须先做流变配平再定用量,不能沿用单用数据。高浓度乙醇会使其析出。含果胶酶活性的植物提取物会缓慢降解它。','干粉稳定,吸湿后结块。溶液在 pH 3–4 最稳,pH 升高或长时间高温都会降解,高温加中性是最差组合;反复加热或返工二次加热会造成不可逆降黏,应在工艺上禁止。原料天然带浅黄色,受热与长期存放会加深,做浅色或透明产品要先确认色泽上限。冻融性一般,可能析水。体系中糖类或多元醇含量高时,HM 型的耐受性与成胶稳定性提升。微生物易感,需完整防腐并控制来料菌数。','常规使用,以最新官方文本为准。','常规使用,常见于天然与有机认证配方(是否收录以认证机构文本为准),以最新官方文本为准。','常规使用,按目标市场规则复核,以最新官方文本为准。','常规使用,以最新官方文本为准。','果蔬来源,通常可做 vegan;清真需供应商出具证明,并确认沉淀纯化环节是否使用乙醇及其残留说明。','low','干粉极易结团,必须与甘油、丙二醇或糖类预混打浆后再撒入,或使用粉液混合装置;水温 60–70 ℃ 搅拌溶解,溶解完全前不要判断黏度。生产用水必须是纯化水,含钙的自来水会直接让 LM 型出颗粒,这是最常见的现场事故。含钙原料(乳酸钙、葡萄糖酸钙、含矿物植提)不能与果胶同时高浓度直投,要稀释后细流加入并全程强搅。pH 调节顺序是先溶胶再调酸,避免在极低 pH 下溶解造成局部降解。与其它胶复配时分别配母液再合并。放大生产的坑在于小样用磁力搅拌很容易分散,大锅靠桨叶容易在锅壁形成胶皮,建议加循环泵或分散头,并延长水合时间。','texture-rheology','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('beta-glucan','Beta-Glucan','β-葡聚糖','β-葡聚糖,贝塔葡聚糖,酵母葡聚糖,燕麦葡聚糖,Yeast Beta-Glucan,Oat Beta-Glucan,Saccharomyces cerevisiae 来源','未确认','多糖','soothing','由葡萄糖以 β-糖苷键连接而成的多糖,来源决定结构:酵母来源以 β-1,3/1,6 支链为主,分子量高,水溶液明显黏稠带拉丝;燕麦来源以 β-1,3/1,4 线性结构为主,分子量与黏度低得多,肤感清爽。配方中主要提供成膜保湿与舒缓方向的感官与质地支持。','0.1–1%(按纯度与固含量折算,不同来源差异很大;公开配方学常见区间,非法规限值)','serum,essence,cream,lotion,mask,gel,toner','4.0–7.5','高分子量酵母 β-葡聚糖溶液黏且拉丝,与卡波、丙烯酸酯类增稠剂叠加后常出现胶感重、涂抹起球搓泥,与高分子量透明质酸钠同用尤其明显,叠加时必须减量。乙醇超过约 20% 会析出返浊。强氧化剂与部分酶类会降解链段,导致存放期黏度下降。与阳离子聚合物配伍需逐批小试,不同纯化工艺带来的杂质与残留电荷差别很大。最容易出事的其实不是配伍而是报价比对:酵母来源、燕麦来源、以及 1% 稀溶液与 70% 粉体,在报价单上都写作 β-葡聚糖,但黏度、肤感与实际用量完全不同,询价与打样必须锁定来源、分子量级别与固含量。','干粉稳定;水溶液在 80 ℃ 以上长时间加热会降解降黏。酵母来源溶液常带浅黄至浅褐色并带特征气味,受热与见光会加深,建议避光包装并在小样阶段就确认色泽与香型的匹配。溶液营养丰富、微生物易感,来料菌检与成品防腐挑战都要做足。反复冻融可能析出。pH 低于 3 或高于 9 长期存放会水解。若采购的是稀溶液形态,必须核算其自带防腐体系与配方防腐的兼容性和总量,避免叠加超量或体系冲突。','常规使用,需确认具体来源物种对应的中国已使用原料信息,以最新官方文本为准。','常规使用,由供应商提供安全评估资料,以最新官方文本为准。','常规使用,按目标市场规则复核,以最新官方文本为准。','日韩市场常见,常规使用,以最新官方文本为准。','酵母或谷物来源,通常可做 vegan;清真需供应商出具证明并确认发酵培养基是否含动物源成分。燕麦来源涉及麸质相关表述时,由客户与供应商另行确认。','mid','液体形态直接后加,体系降到 40 ℃ 以下加入最稳。粉体必须预分散(甘油或丙二醇打浆,或冷水撒入慢搅),高分子量酵母葡聚糖水合慢,建议单独配母液静置过夜。采购与打样阶段必须在规格书上写清三件事:来源(酵母、燕麦或其它)、分子量或黏度指标、固含量或纯度;只写 β-葡聚糖 0.5% 的配方单在换供应商时几乎必然对不上肤感,客户会认为配方被改过。切换供应商要重做黏度与稳定性验证,不能等量替换。水合完成后避免长时间高速均质。带色带味的批次要提前评估对成品色泽与香型的影响。','barrier-repair','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('xanthan-gum','Xanthan Gum','黄原胶','黄原胶,汉生胶,三仙胶,Xanthan Gum,Xanthomonas campestris 发酵多糖','11138-66-2','多糖','hydrating,conditioning','由野油菜黄单胞菌发酵得到的阴离子杂多糖,水溶液具有很高的低剪切黏度与强假塑性:静置时能悬浮粉体、色粉与油滴,涂抹时迅速变稀。是天然与无卡波类配方里最通用的增稠与稳定组分,通常与其它流变剂复配来修饰手感。','0.1–1.0%(公开配方学常见区间,非法规限值)','serum,essence,cream,lotion,gel,mask,toner,foam','3.0–11.0','耐酸碱与耐盐都不错,主要矛盾在手感与协同:单用黏度高但拉丝,用量超过约 0.3–0.4% 后涂抹起白条、搓泥感明显,通常要与纤维素类、罗望子胶或丙烯酸酯类复配掩盖。与刺槐豆胶、瓜尔胶存在强协同,叠加后黏度远超预期甚至成胶,配平时不能按单用量相加。阴离子性质使其与高电荷阳离子聚合物、阳离子表活可能絮凝,阳离子体系要选专用型号并小试。强氧化剂(过氧化物、高浓度次氯酸)会切断链段,表现为放置一段时间后体系突然变稀。与高浓度乙醇(超过约 50%)不相容会析出。二价金属离子在高 pH 下可能造成胶凝或沉淀。','干粉稳定但极易吸潮结块,分装后要密封。溶液在宽 pH 范围与常见盐浓度下都相当稳定,是本类里最耐折腾的一支;但不耐强氧化与酶,含酶或高活性氧化物的体系会在存放期出现黏度断崖式下降。耐热性好,可短时 80–90 ℃ 加热,长时间高温仍会缓慢降黏。冻融稳定性较好。微生物可以降解它,防腐失效的第一个外观信号往往就是变稀,因此成品变稀应优先排查微生物与氧化,而不是先怀疑配方比例。','常规使用,以最新官方文本为准。','常规使用,广泛见于天然与有机认证配方(是否收录以认证机构文本为准),以最新官方文本为准。','常规使用,按目标市场规则复核,以最新官方文本为准。','常规使用,以最新官方文本为准。','微生物发酵来源,通常可做 vegan;清真需供应商出具证明,并确认发酵培养基不含动物源成分及沉淀用乙醇的残留说明。','low','预分散是工厂端最实用的一条经验:干粉直接撒入水中必起鱼眼(外层瞬间水合把干粉包在里面),一旦形成就搅不开,只能过筛报废。三种可靠做法:一是与甘油或丙二醇按 1:5 至 1:10 打成浆再并入水相;二是与配方中其它粉体干混后经粉液混合器或漩涡撒入;三是用高速分散头制造漩涡,沿涡壁细流撒粉。水合温度 40–60 ℃ 更快,完全水合需要 20–30 分钟,水合不足会导致灌装后继续增稠,出现打样偏稀、放几天变稠的假象。真空脱泡很关键,黄原胶浆里的气泡不易自行消除,直接灌装会造成装量不足与外观气泡。放大时注意锅壁挂料,建议先配母液再并锅;高盐与强氧化性活性物一律在胶完全水合之后加入。','texture-rheology','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('sodium-hyaluronate','Sodium Hyaluronate','透明质酸钠','透明质酸钠,玻尿酸钠,玻尿酸,HA,高分子量透明质酸钠,低分子量透明质酸钠,寡聚透明质酸','9067-32-7','多糖','hydrating,barrier,soothing','由 N-乙酰葡糖胺与葡萄糖醛酸交替连接的直链多糖钠盐,目前主流为微生物发酵法生产。高分子量在表面形成连续膜、黏弹感与拉丝明显;中分子量兼顾铺展与保湿;低分子量与寡聚形态黏度极低、肤感清爽。配方中主要承担保湿方向与肤感调节,是草本体系里最常见的搭档组分。','0.05–0.5%(高分子量常见 0.05–0.2%,低分子量可到 0.5% 以上)(公开配方学常见区间,非法规限值)','serum,essence,toner,cream,lotion,gel,mask','4.0–8.0','阴离子聚合物,与阳离子聚合物(聚季铵盐类)、阳离子表活及季铵化调理剂配伍会形成复合物,出现浑浊、絮凝或黏度骤降。高浓度电解质会压缩分子链,高盐配方里高分子量透明质酸钠的黏弹感会大打折扣。乙醇超过约 20–25% 会析出,醇含量高的爽肤水要选耐醇型号或降低用量。在低 pH 且存在游离金属离子或过氧化物的体系(例如高浓度抗坏血酸配方)中,链断裂加快,表现为存放期黏度持续下降,必须做加速验证。与卡波、黄原胶叠加时黏弹协同,容易出现拉丝与搓泥,叠加要重新配平。','干粉在干燥避光下稳定,吸湿结块后既难分散又已开始降解。水溶液对氧化敏感,游离金属离子、过氧化物与高温都会加速链断裂,通常配合螯合剂并控制加热温度与时间。不建议长时间 70 ℃ 以上加热。pH 低于 3 或高于 9 加速水解。溶液极易被微生物利用,母液不可隔夜存放,必须现配现用或在含防腐的水相中配制。最常见的稳定性投诉是黏度衰减而不是外观变化,因此加速试验必须把黏度作为判据之一,只看外观会漏判。','常规使用,以最新官方文本为准。','常规使用,以最新官方文本为准。','常规使用,按目标市场规则复核,以最新官方文本为准。','常规使用,以最新官方文本为准。','目前主流为微生物发酵来源,通常可做 vegan;需向供应商确认确为发酵法(而非动物来源)并出具清真证明与培养基说明。','mid','粉体先用少量水或甘油、丙二醇预分散再撒入水相,静置水合 30–60 分钟,高分子量还要更久;不要靠升温和高速均质催熟,高剪切会直接降黏且不可恢复。建议在水相配制早期加入完成水合,或单独配母液在降温到 45 ℃ 以下并入。报价与规格书必须写清分子量区间(或特性黏度)与来源:同样写 0.1% 透明质酸钠,高分子量做出来是黏滑成膜,低分子量做出来是清爽无感,客户比价或换供应商时几乎必然产生纠纷,认为配方被换。多种分子量复配时分别配母液再合并,并把各自牌号写进配方单而不是笼统写 HA。高盐或高醇配方要提前做兼容小试。','hydration','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('inulin','Inulin','菊粉','菊粉,菊糖,菊苣根提取物来源果聚糖,Chicory Root Inulin,Cichorium intybus,Fructan','9005-80-5','多糖','hydrating,conditioning,soothing','主要来自菊苣根的果聚糖,由果糖单元连接、末端带一个葡萄糖,聚合度从几到六十不等。水中不形成高黏度溶液,在配方里主要作为益生元概念的落点原料以及保湿与肤感调节组分,常与乳酸菌发酵物、后生元一起出现在皮肤微生态方向的配方中。','0.5–3%(公开配方学常见区间,非法规限值)','essence,toner,serum,lotion,cream,gel,foam,mask','4.5–8.0','主要矛盾是溶解度而不是电荷。高聚合度(长链)菊粉冷水溶解度低,浓度偏高或存放温度下降时会缓慢结晶析出,水剂出现絮状白点或瓶底沉积,澄清度投诉多半出在它身上;做透明水剂必须选短链高溶解型号并控制上限用量。pH 低于 4 时果聚糖水解为果糖与低聚糖,益生元结构消失,并可能带来甜味、褐变与更多可被微生物利用的糖。与高浓度乙醇同用降低溶解度、加速析晶。高浓度多元醇会与它争夺水分,同样促进结晶。含果聚糖酶或转化酶活性的发酵提取物共存会将其分解。作为可发酵糖源,防腐体系不足时它会成为微生物的养料,这是它与其它增稠胶体最本质的不同。','干粉稳定但吸湿。溶液最怕低温存放析晶,冬储或冷链运输后出现浑浊、结晶是典型投诉,配方定型前必须做低温循环(如 5 ℃ 存放与冻融)考察,只做常温与高温会漏判。酸性加高温会水解并可能出现轻微褐变与气味变化。中性偏碱、常温条件下相对稳定。作为易被利用的碳源,必须搭配可靠防腐体系并通过防腐挑战,同时严格控制来料菌数与配制卫生;不要一边把防腐削到极限一边加高浓度菊粉。','常规使用,以最新官方文本为准。','常规使用,以最新官方文本为准。','常规使用,按目标市场规则复核;益生元相关表述属于宣称范畴,需另行评估证据支持,以最新官方文本为准。','常规使用,以最新官方文本为准。','植物根茎来源,通常可做 vegan;清真需供应商出具证明并确认提取与干燥工艺助剂。','low','用 60–70 ℃ 温水搅拌溶解,溶解完全后不要急着判断澄清度,必须冷到室温甚至放 5 ℃ 观察 24–48 小时,很多析晶在热态完全看不出来。溶解温度高于 80 ℃ 且体系偏酸会造成水解,反而影响后期色泽与气味。加入顺序放在水相溶解阶段,与其它糖类、多元醇分先后加入避免局部过饱和,含多元醇的配方建议先溶菊粉再加多元醇。放大生产要注意大锅降温慢且锅壁局部过冷,容易先在壁上析出,应控制降温速率并保持搅拌。与后生元、发酵液组合时二者都提高体系可利用营养,防腐体系要按最不利情况设计并做挑战试验。客户要做完全透明水剂时,先把菊粉的最高可用浓度做成上限曲线再定配方。','microbiome','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('vitis-vinifera-seed-extract','Vitis Vinifera Seed Extract','葡萄籽提取物','葡萄籽萃取物,葡萄核提取物,原花青素OPC来源,Grape Seed Extract,Vitis vinifera','未确认(植物提取物,随规格与载体不同,以供应商COA标注为准)','多酚','antioxidant,anti-aging,firming,soothing','主要活性是原花青素(OPC)与低聚儿茶素类,在配方中承担水相还原性抗氧化组分的角色,延缓油脂与其他易氧化活性物的氧化链式反应,也常与维生素类构成还原缓冲体系,用于抗氧化与紧致方向。报价的核心变量是OPC含量,不同检测方法给出的数值不可直接比较,同一INCI名下规格差异可达数倍,谈价前必须先统一规格口径。','0.1–2%(按粉体计;公开配方学常见添加区间,非法规限值)','serum,essence,toner,cream,lotion,mask,gel','3.5–6.0','雷点密集,四类要重点防。一、蛋白与肽类:与水解胶原、丝蛋白、明胶、多肽及酶制剂共用会发生多酚-蛋白络合,先增稠后絮凝,静置数天出现絮状沉淀,同时把肽类活性拉低。二、阳离子体系:与聚季铵盐-10/-7、季铵盐类调理剂电荷中和,体系浑浊、粘度塌陷,洗护配方里尤其明显。三、金属离子:与铁离子生成深蓝黑色络合物,硬水、锅体锈点、含铁色粉都可能让整批发黑,铜离子则加速氧化变褐。四、pH与氧化剂:pH高于6.5快速氧化成醌类,颜色由浅红棕转深棕甚至墨绿;与过氧化物、次氯酸盐等氧化性原料互为消耗,两边同时失效。此外与高浓度电解质共用会降低澄清度,做透明水剂前必须先测澄清度。','光、氧、pH三条线同时施压。见光见氧持续氧化,颜色单向变深且不可逆;pH上移是最主要的变色驱动,超过6.5后一天内即可见变化;温度每上升10℃氧化速率明显加快。常见防护做法:pH控在4.0–5.5并用柠檬酸/柠檬酸钠一类缓冲对锁住,不要只调一次pH;加0.05–0.1%螯合剂(EDTA二钠或植酸)拦截微量金属;必要时配少量还原型辅助抗氧化剂;包材用不透光或深色瓶,优先真空泵、按压泵减少顶空氧。留样必须同时跑45℃与光照两个条件,只做高温会漏判光致变色。验收标准建议事先与客户约定色差上限,而不是写成不得变色。','作为化妆品原料常规使用,需确认原料已被收录并具备可追溯的原料安全信息,配方与宣称按目标品类复核;以最新官方文本为准。','欧盟框架下作为化妆品成分常规使用,需在安全评估文件中覆盖该原料及其溶剂载体,并核对是否落入限用清单;以最新官方文本为准。','美国按化妆品管理常规使用,关注成分安全支持文件、标签成分表准确性以及设施与产品的登记义务;以最新官方文本为准。','日韩及东南亚主要市场普遍可用,需按各国原料目录与宣称管理制度逐一复核;以最新官方文本为准。','植物来源,通常可做vegan主张,但需确认载体(如麦芽糊精、甘油)与工艺助剂无动物源;清真需供应商出具证明。','mid','粉体先用5–10倍量的水或水/丙二醇(1:1)在40℃以下预分散,搅拌溶清后过滤再投,直接撒进主锅会结团挂壁并造成局部高浓度变色。属后加料:乳化体系必须降温至40℃以下再投,超过50℃长时间保温颜色会往深里走。生产用水建议软化处理或先加螯合剂;乳化锅、管道、过滤网若有锈点会直接把料体染黑,开工前查一遍。称量与暂存环节避免与含铁色粉、蛋白类原料共用器具。放大生产真正的坑是停留时间:小样100g三分钟搅完,500L罐从投料到灌装可能几个小时,顶空氧更多、剪切时间更长,大生产的颜色普遍比小样深,打样阶段就要按大生产的搅拌与静置时长模拟一次,否则客户会拿小样色卡来对大货。','antioxidant','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('polygonum-cuspidatum-root-extract','Polygonum Cuspidatum Root Extract','虎杖(根)提取物','虎杖提取物,虎杖根提取物,白藜芦醇天然来源,Polygonum cuspidatum,Reynoutria japonica','提取物未确认;标志物反式白藜芦醇 501-36-0','多酚','antioxidant,anti-aging,brightening,soothing','主要标志物为白藜芦醇与虎杖苷(白藜芦醇苷),属二苯乙烯类多酚,在配方中作为抗氧化组分使用,也常见于抗老与亮白方向的复配。客户习惯按白藜芦醇含量(5%、50%、98%)比价,但含量越高越难溶,颜色、气味与析晶风险同步上升,选规格实质上是在选溶解方案。','0.05–1%(按提取物计;公开配方学常见添加区间,非法规限值)','serum,essence,cream,lotion,mask,toner','4.0–6.5','最常见的翻车不是变色而是析晶。高规格白藜芦醇在纯水相中几乎不溶,与高浓度电解质(氯化钠、氯化钾、盐增稠体系)共用会盐析,析出白色针状结晶,而且往往灌装后一两周才显现,那时货已经发出去了。与阳离子调理剂配伍因单宁背景出现浑浊絮凝;与铁、铜离子生成深色络合物;与强碱段(氢氧化钠调节、皂基体系)接触时白藜芦醇快速氧化并显黄至棕。与高比例乙醇搭配虽然溶得好,但在喷雾、无水精华这类会挥发的剂型里,乙醇跑掉后局部过饱和照样析晶。与含活性氯、过氧化物的体系互相消耗。','反式白藜芦醇见光会异构成顺式并逐步降解,这是它最主要的失效路径,透明瓶在货架灯下两三个月即可见颜色转黄与含量下降;遇氧、遇碱加速。常见做法:溶剂用丙二醇/丁二醇/乙醇与水的混合相,并且刻意留出溶解余量而不是踩着溶解极限做;pH控在4.0–5.5;加0.05–0.1%螯合剂;配少量还原型辅助抗氧化剂;外包用不透光材质。稳定性留样必须包含光照组,只做45℃会漏掉最关键的一条;同时要加做5℃冷循环两周,专门看返晶。','作为化妆品原料常规使用,需确认原料收录状态与原料安全信息,并核对提取溶剂与载体的申报口径;以最新官方文本为准。','欧盟框架下作为化妆品成分常规使用,安全评估需覆盖提取溶剂与标志物含量区间;以最新官方文本为准。','美国按化妆品管理常规使用,关注成分安全支持文件与标签准确性,以及设施与产品登记义务;以最新官方文本为准。','日韩及东南亚主要市场普遍可用,需按各国原料目录与宣称管理制度逐一复核;以最新官方文本为准。','植物来源,通常可做vegan主张;若使用乙醇提取规格,清真需供应商就溶剂来源与残留出具证明。','mid','先做预溶液再谈投料。高规格粉体用丙二醇或丁二醇(必要时补少量乙醇)在50–60℃下搅拌溶清,然后冷却到室温静置观察是否返晶——这一步是判断能不能上到目标添加量的关键,冷却返晶就说明已超溶解极限,只能降量或改增溶方案,不要靠热投料硬压进去。属后加料,乳化体系降温到40℃以下再并入。避免高温直投主锅,70℃以上长时间保温会同时带来降解与色深。放大时的坑在冷却速率:实验室100g降温快,过饱和窗口短,不容易看出问题;500L罐降温慢,反而更容易在缓慢冷却过程中长出晶核,所以打样阶段必须留一支放5℃两周做冷循环,并在SOP里写明灌装前目视检查有无结晶。','antioxidant','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('epigallocatechin-gallate','Epigallocatechin Gallate','表没食子儿茶素没食子酸酯','EGCG,绿茶儿茶素单体,Epigallocatechin Gallate,Camellia sinensis 来源','989-51-5','多酚','antioxidant,soothing,oil-control,anti-aging','把「单体纯度高、起效添加量低,但氧化速度也快得多」改为「单体纯度高、公开配方中的常见添加量更低,但氧化速度也快得多」。','0.01–0.5%(公开配方学常见添加区间,非法规限值)','serum,essence,toner,gel,mask,lotion','3.5–5.5(偏酸更稳)','对金属离子敏感到近乎苛刻:微量铁、铜即生成深色络合物,料体从淡黄转褐甚至墨绿,这是最常见的翻车形式,而且往往在放大生产时才第一次出现。与蛋白、多肽、水解胶原、酶类络合沉淀,并把肽的活性一起拖下去。与阳离子调理剂配伍浑浊絮凝。与碳酸氢钠、氨甲基丙醇、三乙醇胺等碱性中和剂直接接触时,滴入点的局部高pH会造成瞬间不可逆变色,搅匀也回不来。与高浓度L-抗坏血酸同体系时二者互为竞争性氧化底物,文献上说得好听,实际常表现为整体黄变更快,必须以实测为准而不是照搬。与含氧化性成分的体系不可共用。','这是全库里最不稳的品类之一。水溶液在pH高于6时降解以小时计;遇氧发生自氧化并伴随明显黄变褐变;高温、光照、微量金属三者叠加会成倍加速。工程上几乎是必须的三件套:pH锁在4.0–5.0并用缓冲对稳住、螯合剂用足(EDTA二钠一类,约0.1%)、包材必须惰性——不透光、低透氧,优先安瓶、次抛或真空泵。配料时尽量减少顶空,有条件上氮气保护。去离子水也建议照加螯合剂。稳定性判定必须用含量法跟踪,不能只看外观,因为含量掉了一半外观可能还只是淡黄。','作为化妆品原料常规使用,需确认原料收录状态与原料安全信息;若涉及功效方向的宣称,按对应品类的评价要求准备资料;以最新官方文本为准。','欧盟框架下作为化妆品成分常规使用,安全评估需覆盖纯度与残留溶剂;以最新官方文本为准。','美国按化妆品管理常规使用,关注成分安全支持文件与标签准确性,以及设施与产品登记义务;以最新官方文本为准。','日韩及东南亚主要市场普遍可用,需按各国原料目录与宣称管理制度逐一复核;以最新官方文本为准。','多为茶叶提取纯化所得,通常可做vegan主张;需确认纯化工艺助剂无动物源,清真需供应商出具证明。','high','投料顺序是死规矩:先把体系pH调到目标值、螯合剂加完、温度降到35℃以下,最后才投EGCG,绝不能在中和碱液附近下料。粉体在室温或不超过40℃的水/丁二醇中溶解,溶解时避免长时间高速剪切带气。不锈钢锅体有点蚀、管道有锈迹先处理再开工,取样勺与过滤网建议用非金属或316以上材质。真正的放大生产坑不是配方而是等待时间:料体配好后在罐里过夜,第二天颜色就和昨天不一样,批间色差多半出在这里,所以SOP必须写死从溶解到灌装的时限,建议当班配当班灌完。留样的第一支要取自灌装线的最后一桶,而不是罐里的第一勺。','antioxidant','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('punica-granatum-fruit-extract','Punica Granatum Fruit Extract','石榴(果)提取物','石榴提取物,石榴果提取物,鞣花单宁来源,Pomegranate Extract,Punica granatum','提取物未确认;标志物鞣花酸 476-66-4','多酚','antioxidant,soothing,anti-aging,brightening','主要含鞣花单宁(如安石榴苷)及其水解产物鞣花酸,属水解型单宁,在配方中作为水相多酚抗氧化组分,同时带来一定的收敛型肤感。单宁含量直接决定配伍难度:含量越高,和阳离子、蛋白冲突越剧烈,所以来料规格里必须写明单宁或鞣花酸的检测口径。','0.1–2%(公开配方学常见添加区间,非法规限值)','serum,essence,toner,mask,cream,lotion,foam','3.5–6.0','洗护里最典型的配好了就浑浊。与季铵盐类调理剂(聚季铵盐-10、聚季铵盐-7、山嵛基三甲基氯化铵等)直接电荷中和,先出现丝状絮凝,再整体浑浊、粘度崩塌,二合一洗发水、护发素、阳离子调理型沐浴露里几乎必然发生,而且絮凝之后基本救不回来。阳离子瓜尔胶同理。与水解小麦蛋白、丝蛋白、胶原等蛋白类高浓度共存络合沉淀。与铁离子生成蓝黑色单宁铁,这是墨水的老反应,同样会发生在料体里。与卡波姆体系在低pH下可能出现粘度下降。pH升到7以上鞣花酸溶解度上升但氧化变色明显加快。','见光见氧变深棕;高温加速鞣花单宁水解生成鞣花酸,而鞣花酸在水中溶解度很低,水解到一定程度会出现细小悬浮或瓶底沉积。这不是微生物污染,但客户一定会当质量问题投诉,所以稳定性必须跑满三个月并把析出作为独立判据。常见做法:pH控在4.0–5.5、加0.05–0.1%螯合剂、避光包材;必要时用丙二醇、甘油或少量PEG-40氢化蓖麻油提高对鞣花酸的容忍度。留样要同时看颜色、澄清度和瓶底,不要只拍一张正面照。','作为化妆品原料常规使用,需确认原料收录状态与原料安全信息;以最新官方文本为准。','欧盟框架下作为化妆品成分常规使用,安全评估需覆盖果源部位与提取溶剂;以最新官方文本为准。','美国按化妆品管理常规使用,关注成分安全支持文件与标签准确性,以及设施与产品登记义务;以最新官方文本为准。','日韩及东南亚主要市场普遍可用,需按各国原料目录与宣称管理制度逐一复核;以最新官方文本为准。','植物来源,通常可做vegan主张;需确认载体与工艺助剂无动物源,清真需供应商出具证明。','mid','洗护配方的加料顺序必须写死:先把阳离子调理剂在主体表活中彻底分散、体系稀释到位、pH调好,再在低速搅拌下把已经稀释十倍的石榴提取液缓慢滴加进去,滴加时间不少于十分钟。把浓提取液直接倒进含阳离子的锅里,滴入点局部浓度过高会立刻起絮,起絮之后整锅报废。高阳离子的护发素类建议直接放弃水相直投,改用低添加或换成非单宁型植提,这一点在方案阶段就要跟客户讲,不要等打样失败再解释。膏霜类属后加料,降温至40℃以下投。设备上避免与含铁污渍接触。放大的坑就在滴加速度:小试倒得快看不出问题,大罐一定翻车,所以稀释倍数和滴加时长要作为正式工艺参数写进SOP。','antioxidant','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('vaccinium-myrtillus-fruit-extract','Vaccinium Myrtillus Fruit Extract','欧洲越橘(果)提取物','欧洲越橘提取物,山桑子提取物,花青素来源,Bilberry Extract,Vaccinium myrtillus','提取物未确认(以供应商COA标注为准)','多酚','antioxidant,soothing,anti-aging','主要活性为花青素类(矢车菊素、飞燕草素等苷元的糖苷)与有机酸,在配方中作为水相多酚抗氧化组分,同时天然带色,常被用作不加合成色素也有颜色的卖点。但这份颜色本身就是它最大的配方风险:花青素是天然的pH指示剂,配方的颜色管理难度远高于活性管理。','0.1–1%(公开配方学常见添加区间,非法规限值)','serum,essence,toner,mask,gel,lotion','3.0–4.5(颜色可控窗口,超出即变色,这个窗口必须给死)','pH是第一杀手:pH小于3偏红,3–5由红转粉紫,6–7转紫至蓝,大于7转蓝绿并很快褪成黄褐。任何会推高pH的原料——氨甲基丙醇、三乙醇胺、氢氧化钠、碱性皂基、高pH的烟酰胺水溶液、部分碱性防腐体系——都会直接改变成品颜色,这不是稳定性问题而是配方设计问题。与铝、铁离子形成蓝紫色络合物,颜色跑偏且批间不可复现。与亚硫酸盐类抗氧化剂发生加成褪色,等于把颜色直接洗掉,所以这类配方不能用亚硫酸盐做抗氧。与高浓度抗坏血酸共存时二者相互加速降解,颜色掉得比各自单放还快。视规格中的单宁背景,与阳离子调理剂、蛋白类同样有络合浑浊风险。','三大杀手是光、氧、pH漂移,其次是温度。透明包装在货架灯下一两个月就能看出明显褪色。工程上必须用缓冲体系(柠檬酸/柠檬酸钠或乳酸/乳酸钠)把pH锁死在3.2–4.2,而不是只调一次pH——没有缓冲的体系pH会随时间上漂,颜色跟着一起走。配合避光包材、螯合剂防金属变色、避免亚硫酸盐。如果客户既要浅色又要稳定,更现实的方案是低添加加外用耐光色素,把活性和颜色两件事拆开做,这个取舍必须在打样前谈,不能等三个月留样出来再谈。','作为化妆品原料常规使用,需确认原料收录状态与原料安全信息;若颜色被当作着色效果宣称,需另行核对着色剂管理口径;以最新官方文本为准。','欧盟框架下作为化妆品成分常规使用,若作为着色用途需另行核对着色剂清单;以最新官方文本为准。','美国按化妆品管理常规使用,若涉及着色用途需另行核对着色剂管理要求;以最新官方文本为准。','日韩及东南亚主要市场普遍可用,需按各国原料目录与着色剂管理制度逐一复核;以最新官方文本为准。','植物来源,通常可做vegan主张;需确认载体与工艺助剂无动物源,清真需供应商出具证明。','mid','提取液或粉体先在冷水或水-丁二醇中溶解,全程不超过40℃,禁止跟水相一起加热。属后加料,乳化降温到35–40℃再投。pH的主体调节必须在加入花青素之前完成,加入之后只做微调,而且要用稀酸稀碱缓慢滴加、边加边搅——浓碱滴进去的一瞬间会出现蓝斑,搅匀之后颜色也回不到原样,这种批只能报废。灌装线上避免长时间明场停留。放大生产的坑在pH复测点:小样调完就灌了,大生产从调pH到灌装可能隔六到二十四小时,pH会漂、颜色会跟着变,SOP必须写明灌装前复测pH并与标准色卡比对,不合格先回调再灌。留样要留在与成品同款的包材里,用透明瓶留样得出的结论对不透明成品没有参考价值。','antioxidant','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('pinus-pinaster-bark-extract','Pinus Pinaster Bark Extract','海岸松(树皮)提取物','法国海岸松树皮提取物,滨海松树皮提取物,松树皮OPC,Maritime Pine Bark Extract,Pinus pinaster','提取物未确认(以供应商COA标注为准)','多酚','antioxidant,anti-aging,soothing,firming','主要为低聚原花青素(OPC)与酚酸类,是海岸松树皮的水或醇提取物,在配方中作为水相多酚抗氧化组分,欧美高端抗老线常用作有叙事价值的成分。规格按OPC含量分级,价格跨度大,来料规格书里要写清检测方法,否则不同供应商的数字没有可比性。','0.05–1%(公开配方学常见添加区间,非法规限值)','serum,essence,cream,lotion,mask,gel','3.5–6.0','OPC类通性照单全收:与蛋白、多肽、阳离子调理剂络合浑浊或沉淀;与铁离子显深色;pH高于6.5快速氧化变深;与高浓度电解质体系降低澄清度;与氧化性原料互相消耗。但这条记录最实际的一条不兼容是颜色:原料本身就是明显的红棕色,1%添加即可把白色乳霜带成米棕色,0.3%在透明精华里也已经是可见的琥珀色。也就是说它和任何要求浅色、透明外观的配方在物理上就是冲突的,这一条比化学配伍更常导致返工。','见光见氧逐步转深棕,pH上移与金属离子是主要加速因素,高温下的颜色变化不可逆。常见做法:pH控在4.0–5.5、加0.05–0.1%螯合剂、避光包材、后加料并缩短热停留时间。要提前说明的是,颜色随时间加深是这类原料的正常表现而不是失效,所以稳定性的验收口径必须在打样阶段就与客户约定ΔE上限或色卡范围,否则三个月留样出来一定有争议,而这类争议往往发生在已经备好包材之后。','作为化妆品原料常规使用,需确认原料收录状态与原料安全信息,并核对提取溶剂申报口径;以最新官方文本为准。','欧盟框架下作为化妆品成分常规使用,安全评估需覆盖提取部位与溶剂;以最新官方文本为准。','美国按化妆品管理常规使用,关注成分安全支持文件与标签准确性,以及设施与产品登记义务;以最新官方文本为准。','日韩及东南亚主要市场普遍可用,需按各国原料目录与宣称管理制度逐一复核;以最新官方文本为准。','植物来源,通常可做vegan主张;需确认载体与工艺助剂无动物源,清真需供应商出具证明。','high','先谈颜色再谈配方。开工前把0.1%、0.3%、0.5%、1%四个添加量的实物色卡做出来交客户确认,让客户在高添加加深色调和低添加加浅色之间做取舍,做完整支再返工的代价是包材和周期一起赔进去。工艺上粉体先在水或水/丙二醇中40℃以下预溶并过滤,乳化降温到40℃以下再投。如果配方必须保持浅色,可考虑改用微囊或包裹型规格,或者干脆把整个配方基调定成米色、杏色,把原料色变成设计语言。放大时注意原料本身的批间色泽差异,来料检验里要加一项色泽比对,不能只看含量。','antioxidant','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('ginkgo-biloba-leaf-extract','Ginkgo Biloba Leaf Extract','银杏(叶)提取物','银杏叶提取物,白果叶提取物,黄酮苷类提取物,Ginkgo Leaf Extract,Ginkgo biloba','提取物未确认(以供应商COA标注为准)','多酚','antioxidant,soothing,anti-aging,conditioning','主要活性为黄酮醇苷(槲皮素、山柰酚、异鼠李素的糖苷)与萜内酯类,在配方中作为水相类黄酮抗氧化组分,也常见于头皮护理与舒缓方向。客户认知度高,但市面规格从普通叶提取物到高黄酮苷高萜内酯的药用级差别极大,不同规格的提取溶剂与酸类残留背景也不同,不写清规格等于没有标准。','0.1–2%(按提取物计;公开配方学常见添加区间,非法规限值)','serum,essence,toner,lotion,cream,mask,gel','4.0–7.0','最需要盯的不是配伍而是杂质:高规格提取物常带银杏酸(ginkgolic acid)残留背景,这是致敏关注点,化妆品级通常要求低残留规格,具体限值以供应商COA与限值声明及目标市场要求为准,来料必须逐批管控而不是只看首批。配伍上,视单宁与酸类背景与蛋白、阳离子体系有络合浑浊风险;与铁离子生成深色;高pH下黄酮苷易水解并变色。另外不同规格的提取溶剂不同(水提、乙醇提、丙酮提),把乙醇提规格直接加进主打无醇的配方里会破坏宣称,这类问题往往在标签审核阶段才被发现。','相对同类多酚偏稳,但仍会见光缓慢黄变、遇氧变深;高温加速黄酮苷水解成苷元,苷元水溶性更差,可能出现微浑或细小悬浮。常见做法:pH控在4.5–6.5、加螯合剂、避光包材、后加料。留样要跑光照与40℃三个月,重点看澄清度而不是只看颜色,因为这条原料的典型失效表现是慢慢变浑而不是明显变色。若配方是透明精华或化妆水,澄清度必须作为独立的放行指标。','作为化妆品原料常规使用,需确认原料收录状态与原料安全信息,并关注银杏酸类残留的控制要求;以最新官方文本为准。','欧盟框架下作为化妆品成分使用,安全评估需覆盖银杏酸残留与提取溶剂;以最新官方文本为准。','美国按化妆品管理常规使用,关注成分安全支持文件、杂质控制与标签准确性;以最新官方文本为准。','日韩及东南亚主要市场普遍可用,需按各国原料目录与宣称管理制度逐一复核;以最新官方文本为准。','植物来源,通常可做vegan主张;若为乙醇提取规格,清真需供应商就溶剂来源与残留出具证明。','mid','这条的重点在来料标准而不是工艺。采购规格书必须写清五项:黄酮醇苷含量与检测方法、萜内酯含量(客户若有对应宣称)、银杏酸残留上限、提取溶剂及溶剂残留、载体类型(麦芽糊精、环糊精或丙二醇)。同一个INCI名下换供应商,颜色、气味、溶解度、澄清度会全变,等于重做配方,所以替代料必须走完整的小试与稳定性,不能凭COA换。工艺上粉体在40–50℃的水或水/丁二醇中溶解并过滤,常有不溶性载体残渣;乳化降温至45℃以下投料。放大生产的坑在过滤这一步:小样用滤纸随手一滤就清了,大生产不设过滤工序就会有肉眼可见悬浮,产线上要固定滤网目数并写进SOP。','antioxidant','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('curcuma-longa-root-extract','Curcuma Longa Root Extract','姜黄(根)提取物','姜黄提取物,姜黄根茎提取物,姜黄素来源,Turmeric Root Extract,Curcuma longa','提取物未确认;主成分姜黄素 458-37-7','多酚','antioxidant,soothing,brightening','主要活性为姜黄素类(姜黄素、去甲氧基姜黄素、双去甲氧基姜黄素),属二酮类多酚,在配方中作为抗氧化与舒缓方向的组分。它的技术特征比功效方向更值得先讲:着色力极强、见光快速降解,做姜黄概念的项目,一半以上的工作量实际花在颜色管理上,而不是配方性能上。','0.01–0.2%(按含姜黄素规格折算;公开配方学常见添加区间,非法规限值)','serum,cream,lotion,balm,mask,oil,stick','4.0–6.5','和浅色配方在物理上就不兼容:0.01%就足以把白霜带成明显黄色,与二氧化钛体系混合还会显出脏黄。会染色包材与内衬——PE软管、白色泵头、无纺布面膜布都会被染上洗不掉的黄,使用中还会短暂染肤、染毛巾与枕巾,这是客诉高发点,必须在说明书上提前写清。化学上:强碱性体系(pH大于8)中姜黄素由黄转红棕并快速降解,颜色不可逆;与铁离子生成深褐色络合物;与高浓度阴离子表活的洗护体系混合后颜色分布不均,冲洗后残留黄渍;与含氧化性成分共用加速降解褪色。','见光降解是它的标志性问题:透明包装在窗边放几天就能看到明显褪色,料体从鲜黄褪成浅米甚至发灰,而这时客户会同时投诉变色和失效两件事。遇氧、遇碱、高温均加速。常见做法:用不透光包材,外加纸盒并在标签写明避光保存;pH控在4.5–6.0;加螯合剂;必要时改用环糊精包合物或脂质体、纳米分散规格,提高光稳定性与水分散性。稳定性方案必须把光照组作为主判据,并且事先与客户约定可接受的色差范围和褪色描述,否则三个月后必起争议。','作为化妆品原料常规使用,需确认原料收录状态与原料安全信息;若颜色被当作着色效果使用或宣称,需另行核对着色剂管理口径;以最新官方文本为准。','欧盟框架下作为化妆品成分常规使用,若作为着色用途需另行核对着色剂清单;以最新官方文本为准。','美国按化妆品管理常规使用,若涉及着色用途需另行核对着色剂管理要求;以最新官方文本为准。','日韩及东南亚主要市场普遍可用,需按各国原料目录与着色剂管理制度逐一复核;以最新官方文本为准。','植物来源,通常可做vegan主张;若使用油相或增溶载体,需确认载体无动物源,清真需供应商出具证明。','low','姜黄素几乎不溶于水,常规做法是溶于油相,或用增溶剂(聚山梨醇酯-80、PEG-40氢化蓖麻油)配合辛酸/癸酸甘油三酯预分散,也可以直接采购水分散型或环糊精包合规格,避免自己在车间里试溶。现场三条硬规矩:一、姜黄类原料单独区域称量、单独器具,否则会污染下一批白霜,黄点极难清除;二、乳化锅、管道、灌装嘴清洗必须用醇类而不是只用水,水洗洗不掉黄渍;三、投料在降温段40℃以下加入,避免长时间热停留加速降解。排产上把姜黄批次放在一天的最后,清线后隔夜再上浅色产品——放大生产被低估的成本不是原料而是清线,这笔账要在报价时就算进去。','soothing','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('glabridin','Glabridin','光甘草定','光甘草定,光果甘草活性单体,异黄烷类,Glycyrrhiza glabra 来源,Licorice-derived Glabridin','59870-68-7','多酚','brightening,antioxidant,soothing,anti-aging','光果甘草根中的异黄烷类单体,在配方中常作为亮白方向的活性组分与抗氧化组分使用,文献研究的机理方向涉及黑色素生成相关酶活的调节。市售规格从4%、10%、40%到90%以上跨度极大,单价随纯度陡增,报价时必须把以纯品折算的实际添加量讲清楚,否则客户按提取物百分比横向比价会得出完全错误的结论。','折纯 0.01–0.1%(按提取物计需按规格换算;公开配方学常见添加区间,非法规限值)','serum,essence,cream,lotion,oil,balm','4.5–6.5','几乎不溶于水,直接投水相必定析出,表现为料体发花、瓶底出现白色或浅黄颗粒,而且常在灌装一周后才被发现,那时已经没法补救。与高电解质、高离子强度体系共存会加剧析出。与阴离子表活的洗去型体系搭配时,活性大部分随冲洗流失,做洗面奶、沐浴露的亮白宣称性价比极低,这一条应该在方案阶段就劝退客户而不是配完再说。化学上与强氧化性成分共用加速黄变;pH偏碱时氧化变色加快;与铁、铜离子接触变色。','见光、遇氧逐步黄变至棕黄,酚羟基是主要氧化位点,高温加速。常见做法:先溶于油相或用增溶体系再入配方、pH控在5.0–6.0、加0.05–0.1%螯合剂、配合油溶性抗氧化剂如生育酚、包材避光。留样的判据要包含外观是否发花、有无颗粒和瓶底沉积,不能只看颜色——这条原料最典型的失效是物理析出而不是化学降解,而析出往往在低温循环后才显形,所以5℃冷藏两周的循环测试是必做项。','作为化妆品原料使用需确认原料收录状态与原料安全信息;若用于美白/亮白方向宣称,该方向在国内属受管理的功效类别,需按目标市场当时的管理口径与资料要求逐项复核;以最新官方文本为准。','欧盟框架下作为化妆品成分使用,安全评估需覆盖纯度与残留溶剂,宣称需有对应支持;以最新官方文本为准。','美国按化妆品管理使用,注意亮白类表述不得越界为药品宣称,并关注成分安全支持文件与登记义务;以最新官方文本为准。','日韩及东南亚主要市场需按各国原料目录与功效宣称管理制度逐一复核,亮白类宣称在部分市场属受管理类别;以最新官方文本为准。','植物来源,通常可做vegan主张;需确认油相载体与工艺助剂无动物源,清真需供应商出具证明。','high','典型的贵原料投错就浪费。标准做法:先取配方中的一部分油脂(辛酸/癸酸甘油三酯、异壬酸异壬酯之类)或增溶剂,在60–70℃下把光甘草定完全溶清成澄清液,冷却观察不返晶,再并入油相或作为后加增溶相;绝不能把粉直接撒入水相或成品。称量用万分之一天平并两人复核,按纯度折算的差错在这个单价下就是直接的钱。溶解容器与转移损耗必须计入投料量,高纯度品挂壁损耗占比可观,建议用配方内油脂洗涤容器并全部转入。放大的坑是假溶解:小试用60℃水浴几分钟就溶清,大生产油相升温慢、搅拌弱,常出现看着溶了实际有微晶,建议溶解液过100–200目筛并取样对光检查后再并料。','brightening','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('ferulic-acid','Ferulic Acid','阿魏酸','阿魏酸,反式阿魏酸,4-羟基-3-甲氧基肉桂酸,Ferulic Acid','1135-24-6(反式构型另见 537-98-4,以供应商COA标注为准)','多酚','antioxidant,anti-aging,brightening','存在于米糠、燕麦等植物中的羟基肉桂酸类酚酸,在配方中最常见的用途是作为维C与维E体系的稳定化组分:它自身容易被氧化,从而延缓体系里其他更贵、更易氧化的活性物被消耗,同时调节体系整体的还原电位。也单独用于抗氧化方向。','0.1–0.5%(公开配方学常见添加区间,非法规限值)','serum,essence,toner,lotion,cream','3.0–5.0(与L-抗坏血酸体系搭配时通常压到更低)','根子上的问题是水溶性差:冷水中基本不溶,必须靠乙醇、丙二醇、丁二醇增溶,或用碱调成盐才能进水相。碱溶会显著推高体系pH,如果在维C体系里先加碱溶阿魏酸再加维C,维C会在那段高pH窗口里快速氧化,整批发黄甚至发橙——这是这条原料最典型也最贵的顺序错误。反过来若把pH压得过低(低于2.5),阿魏酸溶解度下降会析出针状结晶。与铁离子生成有色络合物;与阳离子体系相对温和但仍需实测;溶剂里含水比例高时冷藏易返晶,配方必须留出溶解余量而不是踩线做。','见光会发生顺反异构与降解,溶液由无色或淡黄逐步转深黄;pH上移与氧气加速氧化;高温加速。经典的维C加维E加阿魏酸体系必须整体低pH、低氧、避光,优先用不透光安瓶、真空泵或次抛。常见做法:pH控在3.0–3.5、加螯合剂、有条件做氮气保护灌装、包材避光。要提前跟客户说明的是,这个体系正常也会随时间轻微加深,所以稳定性验收标准必须事先约定颜色上限,写成不得变色的合同条款是不可能达成的。','作为化妆品原料常规使用,需确认原料收录状态与原料安全信息;若涉及功效方向宣称,按对应品类的评价要求准备资料;以最新官方文本为准。','欧盟框架下作为化妆品成分常规使用,安全评估需覆盖纯度、来源(植物提取或合成)与残留溶剂;以最新官方文本为准。','美国按化妆品管理常规使用,关注成分安全支持文件与标签准确性,以及设施与产品登记义务;以最新官方文本为准。','日韩及东南亚主要市场普遍可用,需按各国原料目录与宣称管理制度逐一复核;以最新官方文本为准。','来源可为植物提取或合成,通常可做vegan主张,但需向供应商确认来源与工艺助剂;清真需供应商出具证明。','mid','加料顺序就是这条记录的核心。路线一(醇溶法,优先):先用乙醇或1,3-丙二醇、丁二醇在40–50℃下把阿魏酸溶清,再并入已配好的酸性水相,全程不加碱,pH用柠檬酸或乳酸微调。路线二(碱溶法,慎用):必须单独用极稀的氢氧化钠或氨甲基丙醇把阿魏酸溶成盐,随即用酸把这份预溶液回调到接近目标pH,再并入主体;绝不能把碱直接加进含维C的主锅。无论走哪条路线,L-抗坏血酸都应在体系pH已稳定在3.0–3.5、温度降到30℃以下之后最后加入,加完立即封罐减少顶空。放大的坑有两个:大罐调pH慢、局部碱度高,pH计要多点取样确认均匀;配好到灌装的等待时间越长颜色越深,SOP必须卡死时限,建议当班灌完,并把灌装线末端的料作为留样。','antioxidant','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('hydrolyzed-soy-protein','Hydrolyzed Soy Protein','水解大豆蛋白','大豆蛋白水解物,大豆肽,大豆多肽,Glycine max,Soy Peptide','未确认','蛋白与肽','hydrating,conditioning,barrier,firming','大豆蛋白经酶解或酸解后得到的多肽与游离氨基酸混合物,分子量分布是它唯一重要的选型参数。较大分子量段倾向在角质层与毛发表面形成连续的亲水膜,带来即时的紧绷与顺滑手感;较小分子量段水溶性更好、更容易分散进水相,常用于保湿与肤感调理方向。同一个 INCI 名下不同分子量的原料在配方里的表现差别很大,采购时必须向供应商索取分子量分布数据,不能只看名称。','1–5%(以原料液计,商品化牌号固含通常 20–40%;公开配方学常见区间,非法规限值)','serum,essence,lotion,cream,mask,toner,foam','4.5–7.0','最典型的翻车点是与富含单宁的草本提取物同用。绿茶、金缕梅、五倍子、石榴皮、橡树皮这一类多酚含量高的提取物会与蛋白发生络合,体系先发浑、再出现丝絮状悬浮物,静置几小时到几天就分层析出,浓度越高发生得越快;要么把两者拆到不同产品里,要么先做 1:1 稀液小样相容测试并同时压低两者用量。在接近蛋白等电点的偏酸 pH 下,阴离子表活(月桂醇聚醚硫酸酯钠、月桂醇硫酸酯钠一类)会与蛋白形成不溶复合物,洗护体系表现为浊度上升与粘度突然下降。高浓度电解质(氯化钠、硫酸镁)与乙醇超过约 20% 会让蛋白脱水析出,做澄清型水剂时尤其明显。与阳离子调理剂(聚季铵盐类)在特定比例区间会形成凝聚物,少量凝聚有利于沉积,过量则起絮、冲洗后发涩,必须按比例扫一遍。与过氧化物、过硫酸盐这类强氧化体系同用会使蛋白氧化,伴随异味与颜色加深。','水解蛋白是整个配方里微生物营养价值最高的原料之一,防腐必须按广谱足量设计并做防腐挑战测试,这一点没有商量余地。常温、pH 4–7 区间相对稳定;pH 低于 3.5 或高于 9 长期放置会继续水解,分子量下移,同时伴随色泽加深与豆腥味、氨味增强。热是它最主要的外观风险:超过 80℃ 长时间受热会促发美拉德类反应,料体由浅黄逐步转为棕黄,这是这类原料最常见的客诉来源,而且小样放一个月往往看不出来,必须做 45℃ 三个月的加速跟踪。见光影响相对有限,但当配方里同时有还原糖或氨基酸类保湿剂时,高温储存的黄变会被明显放大。反复冻融后可能出现轻微浑浊,冻融测试要单独列一组。','属常见已用于化妆品的植物蛋白方向,按现行原料目录与备案要求核对来源、规格与安全信息资料,以最新官方文本为准。','作为化妆品成分常规使用,需注意大豆致敏性的沟通口径,并在产品信息文件中保留完整的原料档案与供应商资料,以最新官方文本为准。','常规使用方向。大豆属主要食物致敏原之一,标签措辞与客服应答口径需在打样阶段就与品牌方对齐,以最新官方文本为准。','日韩及东南亚常规使用方向,部分买家会额外问询转基因来源与产地证明,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。出海订单还需提前确认品牌方是否要求非转基因来源文件。','low','按水相原料管理,但建议放到冷却阶段投:乳化完成、料温降到 45℃ 以下再补入,能同时避开黄变和异味两个坑。原料多为 20–40% 固含的粘稠水溶液,极易挂壁,称量后必须用配方内的水冲洗容器残留并一并入锅,否则实际投料量会系统性偏低。溶解时先用部分配方水稀释 5–10 倍再入主锅,直接倒进高剪切区会打出大量泡沫,泡沫带到灌装环节就是装量不足和液位不齐。与草本提取物同配方时,把提取物和蛋白各自稀释后缓慢互加并边加边观察,不要两股浓液直接对冲,局部高浓度产生的絮块搅不开。桶装料开封后染菌极快,分装必须密封冷藏并规定开封效期,放大生产优先安排整桶用完的批量。','hydration','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('hydrolyzed-rice-protein','Hydrolyzed Rice Protein','水解米蛋白','大米蛋白水解物,水解大米蛋白,大米肽,Oryza sativa,Rice Peptide','未确认','蛋白与肽','hydrating,conditioning,barrier','大米蛋白酶解后的多肽混合物,水溶性好、刺激性低,在配方里主要承担成膜保湿与肤感、发感调理方向。它与东亚「米」的产品叙事契合度高,是米主题产品线里最常被点名的蛋白原料。和其它水解蛋白一样,分子量段决定它偏成膜还是偏渗透,选型时应先看分子量分布再谈用量。','1–5%(以原料液计;公开配方学常见区间,非法规限值)','essence,serum,toner,lotion,mask,cream,foam','4.5–7.0','与单宁类多酚提取物(绿茶、金缕梅、五倍子等)同用会络合起浊起絮,现象和大豆蛋白一致,是首要排查项。与高浓度阴离子表活在偏酸 pH 下形成复合物,做透明洁面或透明水剂时会直接发白,是这一支最常见的外观事故。乙醇含量超过约 15–20% 时容易析出,做喷雾和爽肤水前必须先做乙醇梯度试验。与含铁、铜杂质较高的植提或天然色素共用会加速黄变与色偏,建议同时引入螯合剂。阳离子聚合物过量时同样起絮,洗护体系里要按比例扫窗口。','这一支本体带天然的浅黄至浅棕黄色,这是原料属性不是变质,但做透明水剂时会直接决定成品色号,客户确认样品前必须提前说明,否则会被当成品控问题投诉。微生物风险高,防腐要足量并做挑战测试。超过 80℃ 长时间加热会加深颜色并放大米糠样气味,尽量避免与油相一起长时间受热。pH 漂到强酸或强碱区会继续水解并加深颜色。批间的浊度与色度波动比大豆蛋白更明显,这是它做澄清体系时的真正难点,建议来料检验里直接加验浊度(NTU)与色度两项,而不是只看 COA 上的固含与氮含量。','常见已用于化妆品的植物蛋白方向,按现行原料目录与备案要求核对来源与规格,以最新官方文本为准。','作为化妆品成分常规使用,产品信息文件中需保留完整原料档案与供应商溯源资料,以最新官方文本为准。','常规使用方向,标签与宣称按目标渠道规则复核,以最新官方文本为准。','日韩市场对米类原料接受度高,属常规使用方向,按目标市场规则复核,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。','mid','做透明水剂有一套可复制的工艺:原料先按 1:10 稀释,经 1–5 μm 滤芯预过滤后再入主锅,成品灌装前再走一道精滤,澄清度和批间一致性都会明显改善,这一步比换牌号更有效。气味是绕不开的现实约束,米糠样气味在无香或淡香配方里一定会被闻出来,所以香精评估必须放在含蛋白的实际基质里做,在空白基质里选好的香精上机后经常翻车。投料放在冷却阶段(45℃ 以下),和防腐剂同段加入,减少热暴露。稀释液不要过夜存放,当班用完。特别注意它与米发酵滤液(Rice Ferment Filtrate)完全不是一类原料,规格书、物料编码和检验项都要分开管理,不要因为都叫「米」就在仓库串料。','hydration','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('hydrolyzed-wheat-protein','Hydrolyzed Wheat Protein','水解小麦蛋白','小麦蛋白水解物,水解麦蛋白,小麦肽,Triticum vulgare,Wheat Peptide','未确认','蛋白与肽','hydrating,conditioning,barrier,firming','小麦面筋蛋白水解后得到的多肽混合物,与毛发角蛋白亲和性好,是洗护线里用量最大的一类植物蛋白。较大分子量段在发丝表面成膜、改善梳理与湿发手感;较小分子量段更偏保湿方向。护肤配方里多用于即时的成膜紧致肤感方向,而不是长期作用方向。','1–5%(以原料液计;公开配方学常见区间,非法规限值)','foam,lotion,cream,essence,serum,mask','4.0–7.0','与单宁类草本提取物络合起絮,现象同其它植物蛋白。洗护体系里若同时含高浓度阴离子表活与阳离子调理剂,三者容易形成过量凝聚物,表现为冲洗后发涩、长期使用堆积,必须按三元比例做窗口试验而不是两两试。高电解质与高乙醇会使其脱水析出。与染烫体系的过氧化氢、过硫酸盐同用会被氧化降解并产生明显异味,如果客户要做染烫配套线,这一组合必须单独验证。还有一个容易被忽略的点:市面上不少商品化牌号其实是水解小麦蛋白的阳离子化衍生物或复配物,这类衍生物的电荷性质、配伍规则和稳定性与普通水解小麦蛋白不同,不能照抄经验,报价与配方表上要写清具体是哪一种。','微生物营养源,防腐必须足量并做挑战测试。加热黄变与 pH 极端下继续水解的规律与大豆蛋白一致:超过 80℃ 长时间受热会明显加深颜色,pH 低于 3.5 或高于 9 会持续降解。长期高温储存时,黄变往往先出现在瓶口与液面接触空气的位置,做稳定性观察时要连同包材一起放,不要只放烧杯。冻融后可能轻微浑浊,需单列一组。','属常见已用于化妆品的植物蛋白方向,按现行原料目录与备案要求核对来源与规格,以最新官方文本为准。','market_eu 改为:「欧盟对水解小麦蛋白类原料设有与肽分子量相关的限制条件,不属于无条件常规使用,采用前必须逐项核对原料规格是否落在允许范围内,并在产品信息文件中保留分子量分布数据与供应商资料;具体条件以最新官方文本为准。」同时把 confidence 由「高」降为「中」。','常规使用方向。小麦属主要食物致敏原之一,麸质相关的标签与客服口径必须在打样阶段就定下来,相关判断以供应商检测文件与最新官方文本为准。','日韩及东南亚常规使用方向,部分买家同样会问询麸质检测数据,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。麸质问题与 vegan 无关,需分开回答,不要混为一谈。','low','出海客户几乎必问麸质,所以开单前就要向供应商索取麸质残留检测数据(以 ppm 计)以及产线是否与含麸质原料共线的书面说明,把文件先备齐,否则打样后期一定卡在这里。帛卉的处理原则是把供应商检测报告原样转交品牌方,由品牌方按目标市场规则自行判断能否作无麸质表述,我们不代为下结论。如果品牌方明确要做无麸质方向,最省事的做法不是在小麦蛋白上做文件,而是直接换成水解豌豆蛋白或水解米蛋白。投料与其它水解蛋白一致:冷却到 45℃ 以下加入,先稀释再入锅,控制泡沫。洗护线放大生产时要注意,蛋白加入后体系粘度会下降,盐或增稠剂的用量必须在含蛋白的实际体系里重新标定,沿用空白基质的加盐曲线会导致成品粘度整批偏低。','conditioning','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('hydrolyzed-oat-protein','Hydrolyzed Oat Protein','水解燕麦蛋白','燕麦蛋白水解物,燕麦肽,Avena sativa,Oat Peptide','未确认','蛋白与肽','hydrating,soothing,barrier,conditioning','燕麦蛋白水解后的多肽混合物,水溶性好、刺激性低,是婴童与敏感肌温和线里常选的成膜保湿组分。必须和「胶体燕麦 / 燕麦提取物」区分开:后者以 β-葡聚糖等多糖和燕麦生物碱为主,走的是成膜舒缓方向;前者是蛋白肽,走的是成膜保湿与调理方向。两者可以同用,但功能定位、检测指标和法规身份都不一样。','1–4%(以原料液计;公开配方学常见区间,非法规限值)','lotion,cream,essence,serum,mask,foam,gel','4.5–7.0','与单宁类植提络合起絮,同其它水解蛋白。与高浓度阴离子表活在偏酸 pH 下形成复合物,温和洁面若同时追求透明外观要提前做浊度试验。高电解质与高浓度乙醇会导致析出。与高浓度锌盐、铝盐体系(部分控油与止汗方向)同用可能出现沉淀,需先做小样。温和线还有一个隐性冲突:为了温和常会削减防腐体系,而水解蛋白恰恰是微生物营养源,这两件事在同一支配方里天然对立,必须在立项阶段一起定,不能等配方定稿再补防腐。','微生物风险高,防腐要足量并做挑战测试,婴童线尤其要提前锁定可用的防腐组合。加热到 80℃ 以上长时间受热会黄变,pH 极端下继续水解,规律与其它植物蛋白一致。燕麦来源原料普遍带谷物气味,在无香温和线里会更突出,香精或遮味方案要在含蛋白的实际基质里评估。冻融后可能出现轻微浑浊,需单列观察。','属常见已用于化妆品的植物蛋白方向,按现行原料目录与备案要求核对来源与规格,并注意与胶体燕麦类原料的身份区分,以最新官方文本为准。','作为化妆品成分常规使用,与胶体燕麦类原料的定位差异需在文件中写清,以最新官方文本为准。','常规使用方向,注意燕麦相关原料在部分表述上与胶体燕麦不同,不可互相套用,以最新官方文本为准。','常规使用方向,按目标市场规则复核,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。','mid','这一支最大的成本不在原料而在沟通:客户十有八九会把「燕麦蛋白」和「胶体燕麦」当成一回事。报价单和规格书上写清 INCI 与检测指标,并在样品说明里各写一句作用定位,能省掉大量来回。判断口径也很简单:客户真正想要的如果是舒缓成膜,应该用胶体燕麦或燕麦提取物;想要的如果是蛋白肽的成膜与调理,才用这一支;两者也可以低浓度组合,但不要用一个去顶另一个的定位。另一个实务点是燕麦常与小麦共线种植与加工,若客户同时想要无麸质表述,交叉污染的检测文件同样要向供应商索取,不能因为原料名里没有小麦就默认没有问题。投料方式与其它水解蛋白相同:冷却到 45℃ 以下加入,先稀释再入锅,控制泡沫。','soothing','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('hydrolyzed-pea-protein','Hydrolyzed Pea Protein','水解豌豆蛋白','豌豆蛋白水解物,豌豆肽,Pisum sativum,Pea Peptide','未确认','蛋白与肽','conditioning,firming','豌豆蛋白水解后的多肽混合物,天然不涉及麸质,也不牵扯大豆致敏原议题,是近年替换水解小麦蛋白与水解大豆蛋白的主流方案。成膜与保湿的作用逻辑与其它植物蛋白一致,真正的差别在手感与气味上,这也是替换时最容易被客户挑出来的地方。','1–5%(以原料液计;公开配方学常见区间,非法规限值)','serum,essence,lotion,cream,mask,foam,toner','4.5–7.0','与单宁类植提络合起絮、与高浓度阴离子表活形成复合物、高电解质与高乙醇析出,这三条与其它水解蛋白一致。真正的替换陷阱在 pH:豌豆蛋白的等电点区间与大豆、小麦不完全一样,直接沿用原配方的 pH 设定,常会在 pH 4.0–4.5 附近出现浊度上升甚至微沉,所以换料之后必须重新扫一遍 pH 曲线,而不是只把料换掉、pH 照旧。与阳离子聚合物的相容比例也要重新标定,不能沿用小麦蛋白的窗口。','微生物营养源,防腐必须足量并做挑战测试。加热黄变与 pH 极端下继续水解的规律同其它水解蛋白,建议控制在 80℃ 以下。豌豆来源带轻微豆青气味,从小麦蛋白替换过来之后,原有的香精可能需要微调,这一步经常被漏掉,导致客户觉得「香味变了」。冻融后需单列观察浊度。','属常见已用于化妆品的植物蛋白方向,按现行原料目录与备案要求核对来源与规格,以最新官方文本为准。','作为化妆品成分常规使用,无麸质相关表述仍需以供应商检测文件为依据,以最新官方文本为准。','market_us 改为:「常规使用方向。过敏原相关的标签与客服口径以供应商检测资料与目标市场规则为准,不预设豌豆属于强制标示的过敏原类别,以最新官方文本为准。」','常规使用方向,按目标市场规则复核,以最新官方文本为准。','植物来源,vegan 友好度高,是纯素线常选的蛋白;清真需供应商出具证明。','mid','替换小麦蛋白时最常见的客户反馈是「肤感或发感变了」:豌豆蛋白的成膜更轻、紧绷感更弱,洗护线里的梳理性下降尤其明显。正确做法不是 1:1 等量替换,而是要么提高用量,要么补一个阳离子调理组分把手感补回来,并且在打样单上事先写明会有差异,让品牌方带着预期评估,而不是收到样品之后才发现。无麸质是这一支的主要卖点,但仍要向供应商确认产线共线情况并索取检测文件,不能仅凭原料名下结论。投料方式与其它水解蛋白相同:冷却到 45℃ 以下加入,先用配方水稀释 5–10 倍再入锅,控制泡沫,称量后冲洗容器残留。','hydration','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('hydrolyzed-corn-protein','Hydrolyzed Corn Protein','水解玉米蛋白','玉米蛋白水解物,玉米肽,玉米醇溶蛋白水解物,Zea mays,Corn Peptide','未确认','蛋白与肽','hydrating,conditioning,barrier','玉米蛋白(以醇溶蛋白为主)水解后的多肽混合物,氨基酸组成中疏水性残基比例较高,成膜后的手感偏干爽而不是偏黏,是植物蛋白里成本最友好的一档。多用于需要压成本的洗护与基础护肤方案,也常与米蛋白、豌豆蛋白少量复配,用来在控制成本的同时把手感和叙事拉平。','1–5%(以原料液计;公开配方学常见区间,非法规限值)','foam,lotion,cream,essence,toner,mask','4.5–7.0','与单宁类植提仍会络合起浊,程度通常比大豆蛋白略轻,但不能当作没有,依然要做小样。高电解质与高浓度乙醇会析出。与过氧化物、过硫酸盐类强氧化体系同用会降解并产生异味。值得单独记一笔的是,相较其它植物蛋白,它与阳离子调理体系(聚季铵盐-7、聚季铵盐-10、瓜尔胶羟丙基三甲基氯化铵)的相容窗口更宽,不容易起絮,这在二合一洗护和护发素类产品里有实际价值;但这是相对优势不是免检理由,具体比例仍要在实际体系里验证。','微生物营养源,防腐必须足量并做挑战测试。加热黄变、pH 极端下继续水解的规律与其它水解蛋白一致。这一支的批间色泽波动相对明显,尤其在浅色透明体系里容易暴露,来料检验建议直接加验色度,并要求供应商提供近几批的色度数据做趋势判断,而不是只看单批 COA。冻融后需单列观察。','属常见已用于化妆品的植物蛋白方向,按现行原料目录与备案要求核对来源与规格,以最新官方文本为准。','作为化妆品成分常规使用,产品信息文件中保留原料档案与来源说明,以最新官方文本为准。','常规使用方向,按目标渠道规则复核标签与宣称,以最新官方文本为准。','常规使用方向,部分买家会问询转基因来源文件,以最新官方文本为准。','植物来源,通常可做 vegan;清真需供应商出具证明。玉米来源同样存在转基因问询,出海订单需提前确认品牌方要求。','low','压成本方案的正确做法是玉米蛋白打底承担主要用量,再用少量米蛋白或豌豆蛋白做手感修饰与成分表叙事,而不是把单一便宜蛋白顶满用量,后者成本省不了多少,感官却明显变差。注意市面上不少商品化牌号是玉米蛋白与其它蛋白的复配液,报价单与规格书必须写清实际固含与组成,否则客户会拿复配液的价格去和纯蛋白比价,谈判会很被动。投料方式与其它水解蛋白相同:冷却到 45℃ 以下加入,先稀释再入锅,控制泡沫。若客户要求非转基因来源,开单前先向供应商确认能否出具文件,不要打完样再回头补。','conditioning','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('ectoin','Ectoin','依克多因','依克多因,四氢甲基嘧啶羧酸,Ectoine,THP(A)','96702-03-3','发酵物','hydrating,soothing,barrier,repair','来自极端环境微生物的相容性溶质,属于「优先排阻」型的水结构调节分子:它不直接结合到蛋白与膜表面,而是改变周围水分子的排布状态,常用于外界刺激条件下降低体系应激反应的方向,以及保湿与屏障舒缓方向。分子小、水溶性极好、化学性质惰性,几乎不改变体系的外观、粘度和 pH,是少见的「加进去不惹麻烦」的活性物,这也是它在配方上受欢迎的主要原因。','0.3–2%(公开配方学常见区间,非法规限值;多数方案落在 0.5–1% 一档)','serum,essence,toner,lotion,cream,mask,gel','3.0–9.0(实际使用多在 4.5–7.0)','化学上非常温和,几乎没有典型的配伍禁忌,这正是它的价值所在。需要提醒的不是冲突而是误解:它对体系粘度和肤感的贡献接近于零,常被误以为加了就能改善手感,配方上必须靠其它组分撑手感,否则客户会觉得「加了很贵的东西却没感觉」。高用量时会略微提高体系渗透压,若配方同时使用卡波姆类增稠体系并含较多盐类,可能出现粘度下降,这时应改用耐电解质增稠剂,而不是靠加大增稠剂用量硬顶。与强氧化或强还原体系未见普遍冲突,但极端 pH 加高温的组合仍建议实测,不要凭「它很稳」直接跳过。','是稳定性最省心的一类活性物之一:耐受常规乳化温度,pH 适应范围宽,不见光敏、不易氧化,加速试验中通常不构成变量。它本身不是防腐剂,也不给微生物提供额外营养,但纯水溶液体系仍需按常规设计防腐。真正的风险不在稳定性而在来料:市面上掺假、低纯度、以其它相容性溶质冒充的情况都存在,而它在成品里既不显色也不显味,一旦买到问题料,通过感官和常规理化指标根本发现不了,只能靠来料端拦住。','作为化妆品原料的常规使用方向,需按现行原料目录与备案要求核对来源、规格与安全信息资料,以最新官方文本为准。','作为化妆品成分常规使用,产品信息文件中保留纯度与生产工艺资料,以最新官方文本为准。','常规使用方向,宣称按目标渠道规则复核,以最新官方文本为准。','日韩市场使用广泛,属常规使用方向,按目标市场规则复核,以最新官方文本为准。','主流商品化路线为微生物发酵法生产,非动物来源,一般可做 vegan;清真需供应商出具证明,并确认发酵培养基组分来源。','high','这一支单价高、客户点名率高,来料验证是整条链上最该花力气的环节:每批索取 HPLC 纯度图谱与含量数据,并核对报告上的批号能否追溯到原厂批号,必要时送第三方复检;只有文字版 COA 不足以放行。水溶性极好,常温直接溶于水相即可,不需要加热助溶,建议放在冷却阶段加入以减少无谓的热暴露。白色结晶粉末,称量后立即封口,干燥密封储存。最容易出事的地方是漏投:因为它不改变外观、气味、粘度和 pH,产线上漏加一整锅也不会有人察觉,所以必须把它列入关键投料双人复核清单并保留称量记录,这是这一支的头号工厂风险。商务上,配方定稿前先按目标到岸价倒推可用浓度,不要先按 2% 打样再往下砍,砍浓度会直接让客户产生缩水印象。','barrier-repair','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('ergothioneine','Ergothioneine','麦角硫因','L-麦角硫因,EGT,硫代组氨酸三甲基内盐,L-Ergothioneine','497-30-3','发酵物','antioxidant,soothing,anti-aging','天然存在的含硫组氨酸衍生物,在生理 pH 下以硫酮式为主而非硫醇式,因此不像常见硫醇类那样容易自身氧化,常用于抗氧化与调节体系氧化应激的方向。它对过渡金属离子具有螯合能力,这既是其作用机理的一部分,也是配方设计上必须提前处理的变量。近年询盘增长很快,但因单价极高,实际方案的添加量普遍很低。','0.01–0.1%(公开配方学常见区间,非法规限值;受成本约束,多数方案落在 0.05% 以下)','serum,essence,cream,lotion,toner,mask','4.0–7.5','最需要警惕的是金属离子:与铁、铜含量较高的植物提取物、部分黏土与矿粉、未经纯化的果蔬提取物同用时,可能形成有色络合物,料体在货架期逐渐转粉、转灰或转褐。这类组合上中试之前必须先做 1:1 小样兼容并在 45℃ 放四周观察颜色,绝不能凭理论直接放大。与过氧化物、高浓度过硫酸盐等强氧化体系同用会被持续消耗,昂贵的活性物白花钱。与其它含硫化合物同用需评估气味叠加与相互消耗。若配方里已经有铜肽类原料,两者在机理上互相牵制,不建议放进同一支产品。与高浓度阳离子表活的相容性缺少通用经验,需单独验证。','干粉状态稳定性好,常温密封储存问题不大。水溶液在中性偏酸区相对稳定,但只要体系里存在游离过渡金属离子,尤其是铜和铁,消耗速度和变色速度都会明显加快。配套做法有三条:体系里同步加入螯合剂(EDTA 类或植酸)、控制生产用水的金属离子含量、避免使用带锈或裸露铁质的辅具与未钝化管路。它的光稳定性相对有限,但实践中成品色变多数来自金属络合而不是光解,所以排查变色时应该先查金属和水质,而不是先去换避光包材,换包材往往解决不了问题还多花钱。高温长时间加热会造成损失,建议冷却阶段加入。','作为化妆品原料的准入身份与备案资料需按现行原料目录逐项确认,不同来源与规格的原料身份可能不同,以最新官方文本为准。','作为化妆品成分使用,需按最新官方文本复核并在产品信息文件中保留纯度、手性与生产工艺资料,以最新官方文本为准。','常规使用方向,宣称按目标渠道规则复核,以最新官方文本为准。','日韩市场关注度高,准入与规格按目标市场规则复核,以最新官方文本为准。','主流商品化路线为微生物发酵法生产,非动物来源,一般可做 vegan;清真需供应商出具证明并确认发酵培养基组分。','high','单价极高,称量误差同时是成本问题和稳定性问题:小批量必须用万分之一天平,并且先配 1:100 或 1:1000 母液再投料,不要直接称取毫克级粉末,静电和挂壁会让实际投料量严重失真。母液当班用完,不隔夜。投料放在冷却阶段(40℃ 以下),顺序上先让螯合剂进水相把金属离子锁住,再加麦角硫因,顺序反过来会在最开始的几分钟就损失一部分。生产用水优先用纯化水并检测金属离子;不锈钢锅具没有问题,但要避免带锈辅具、铁质刮刀和未钝化管路。商务上要注意很多品牌方对「0.01% 也算添加」没有概念,报价时应同时给出浓度与对应成本区间,并把浓度写进打样单,避免后期为了压价悄悄降浓度而埋下纠纷。来料同样要看 HPLC 纯度与手性(L-型),并要求报告可追溯到原厂批号。','antioxidant','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('phytic-acid','Phytic Acid','植酸','aliases 改为「肌醇六磷酸,IP6,Inositol Hexaphosphate,Phytate,Phytic Acid」;来源信息移到 mechanism_zh 或 halal_vegan(那里已有「常见米糠及谷物来源」)。','83-86-3','植物提取物','brightening','米糠等谷物来源的天然多磷酸化合物,对铁、铜等过渡金属离子有很强的螯合能力。在草本配方里它真正的价值是保色保味:多酚类植提在货架期变褐、变暗,很大一部分是微量金属离子催化的氧化,把这些离子锁住就能明显延缓这个过程。它本身还是一种弱酸,在复合酸体系里也用于温和的酸性调理方向,但用在这个方向时对 pH 的影响必须单独管理。','0.05–0.5% 作为螯合与稳定辅助;复合酸体系中可到 1–2%(均以商品化原料液计;公开配方学常见区间,非法规限值)','serum,essence,toner,lotion,cream,gel,mask','3.0–6.0(作为螯合剂使用时可适当放宽,但必须核算它对体系 pH 的拉低作用)','第一条是它自己的强酸性:商品化植酸多为约 50% 的水溶液,pH 大约在 1–2,即便只加 0.2%,也可能把体系 pH 拉低半个单位以上,必须配套碱调并在调完后复测,不能凭经验免测。第二条是与金属离子类活性物的直接冲突:锌盐(PCA 锌、葡萄糖酸锌)、镁盐、铜肽这些都会被它螯合掉,活性物失效并可能出现沉淀,含铜肽的配方不要加植酸。第三条是水质:与硬水中的钙镁离子会生成不溶的植酸钙镁,表现为细密白色沉淀,生产用水必须是软化水或纯化水。第四条是与高浓度阳离子表活或阳离子聚合物形成不溶复合物,洗护体系里会起浊、降粘。与 EDTA 类螯合剂不冲突但功能重叠,通常二选一或各自降量并用。偏碱性体系(pH 大于 7)中它的表现变化明显,不建议直接使用。','分子本身热稳定性尚可,但强酸条件下长期高温可能促进部分水解为低级磷酸酯,螯合能力随之下降,所以不要让含植酸的体系长时间高温循环。它的光稳定性不是主要矛盾,真正要看的是它保护对象的状态。评估它有没有加对,最直接的办法是在 45℃ 加速试验里留一组不含植酸的对照:含多酚草本提取物的体系,加了植酸之后颜色变化通常明显放缓,这一组颜色对比比任何理论解释都有说服力,也是能拿给客户看的证据。如果成品出现返浊或白色细沉,排查顺序应该是先查生产用水硬度和是否混入了钙镁盐类,再去怀疑防腐或增稠体系。','作为化妆品原料的常规使用方向,按现行原料目录与备案要求核对来源与规格,以最新官方文本为准。','作为化妆品成分常规使用,注意其在配方中承担的功能定位与相应文件说明,以最新官方文本为准。','常规使用方向,若用于酸性调理方向,标签警示与使用说明按目标渠道规则复核,以最新官方文本为准。','常规使用方向,按目标市场规则复核,以最新官方文本为准。','植物来源(常见米糠及谷物来源),通常可做 vegan;清真需供应商出具证明。','low','绝对不要把 50% 原液直接倒进主锅:局部强酸会让附近的植提和增稠剂瞬间凝聚,形成再也搅不开的团块,这是这一支最常见的生产事故。正确做法是取配方内一部分水稀释十倍以上,再沿锅壁在搅拌状态下缓慢加入。投料顺序上建议放在水相早期、其它怕金属的活性物之前,让它先把水里的金属离子锁住,再引入维 C 衍生物、麦角硫因、多酚植提这类敏感组分,顺序反了等于让活性物先挨一轮氧化。加完植酸后统一调 pH,并在 24 小时后复测一次,含羧酸类原料的体系 pH 常有回漂。全程避免铁质器具和未钝化管路,否则一边加螯合剂一边引入金属离子。放大生产时最容易被忽略的变量是水的硬度,同一个配方换一个厂区的水,可能一批清一批浊,转厂或换水源时这一项要重新验证。','antioxidant','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('betaine','Betaine','甜菜碱','aliases 改为「三甲基甘氨酸,无水甜菜碱,TMG,Trimethylglycine,Glycine Betaine」;来源留在 halal_vegan 与 mechanism_zh 里说明即可。','107-43-7','植物提取物','hydrating,soothing,barrier,conditioning','甜菜糖蜜来源的天然相容性溶质,与依克多因同属渗透调节类小分子,只是分子更简单、成本低得多。在配方里主要承担吸湿保湿方向,也常用于降低表活体系刺激感受的方向。实际使用中一个很有价值的用法是替换掉一部分甘油:在保持保湿的同时减轻甘油带来的黏腻,是性价比最高的肤感调整手段之一。','0.5–5%(公开配方学常见区间,非法规限值;洁面体系常用 1–3%,保湿体系可到 5%)','serum,essence,toner,lotion,cream,mask,foam,gel','3.0–9.0','化学上很宽容,真正的冲突不多,但它本质上是电解质性质的小分子,这一点决定了它的两个坑。第一,用量超过约 3–5% 会对卡波姆类增稠体系产生明显降粘作用,凝胶体系要么改用耐电解质增稠剂,要么把用量压下来,不能靠加大卡波姆用量硬补。第二,与盐类共用会叠加降粘,并且会改变表活体系的盐增稠曲线,洗面奶调粘度时必须在含甜菜碱的实际体系里重新标定加盐量,沿用空白配方的曲线一定偏。与阴离子表活相容性很好,是氨基酸洁面里的常客。另外必须提醒一个中文命名陷阱:「甜菜碱」与「椰油酰胺丙基甜菜碱(Cocamidopropyl Betaine)」完全不是一种东西,后者是两性表活,两者在规格书、物料编码和检验项上必须彻底分开,车间串料会直接毁掉一整锅。','化学稳定性很好:耐热、耐宽 pH 区间、不见光敏、不易氧化,乳化阶段或冷却阶段加入都可以,在加速试验里基本不构成变量。它不是理想的微生物营养源,但也不提供任何保护,防腐按常规体系设计即可。这一支真正的稳定性问题不在料体端而在粉料端:无水甜菜碱粉极易吸潮,吸潮后先结块,严重时潮解成糊,称量精度和投料效率都会受影响。高浓度水溶液牌号在低温下可能析出结晶,冬季运输与仓储要留意,析出后可用温水加热复溶,但必须确认完全澄清后再投料,不能带着未溶结晶入锅。','作为化妆品原料的常规使用方向,按现行原料目录与备案要求核对来源与规格,以最新官方文本为准。','作为化妆品成分常规使用,注意与两性表活类甜菜碱的名称区分,以最新官方文本为准。','常规使用方向,按目标渠道规则复核标签与宣称,以最新官方文本为准。','常规使用方向,按目标市场规则复核,以最新官方文本为准。','常见为甜菜糖蜜来源,也存在合成来源牌号;植物来源牌号通常可做 vegan,清真需供应商出具证明并确认生产路线与来源。','low','粉料储存是这一支的头号实务问题:开封后必须立即密封,建议加干燥剂并按小包装分装,车间湿度大的季节尽量不要在敞开环境长时间称量。已经结块的料在使用前要先判断是单纯物理结块(可打散复溶,仍可用)还是已经潮解(应报废),不要为了省料把潮解的粉倒进锅里。溶解方面,它在常温水中溶解度很高,但一次性大量倒入会在锅底形成高浓度层并结团,应该边搅拌边分次加入,或者先配 20–30% 母液再投。溶解过程略微吸热,冬季用冷水溶解会明显变慢,用 35–40℃ 温水即可加快,不需要更高温度。市面上也有 40–50% 的液体牌号,液体省掉了吸潮的麻烦,但要按固含折算并注意冬季析晶,报价单与配方表上要写清是粉料还是液体牌号,不能混着报。用它替换部分多元醇是常见的降本手段,但替换后黏腻感和成膜感都会下降,必须在打样单上提前说明,让品牌方带着预期评估。','hydration','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('niacinamide','Niacinamide','烟酰胺','烟酰胺,维生素B3,尼克酰胺,菸鹼醯胺,Nicotinamide,Vitamin B3','98-92-0','维生素及衍生物','barrier,brightening,oil-control,hydrating','维生素B3的酰胺形式,是体内NAD/NADP辅酶体系的前体分子,水溶性极好,常用于屏障与肤色均匀度方向,也常出现在控油类配方中。它在配方里的角色是高添加量的水相主活性,几乎不影响肤感与流变,因此客户点名率很高。真正决定成品成败的不是加多少,而是它在生产过程中经历了什么样的pH与温度,因为它的降解产物烟酸会直接带来气味与刺痛类投诉。','2–5%(公开配方学常见区间,非法规限值);超过5%后使用者刺痛反馈明显增多,高添加需先做人群试用','serum,essence,toner,lotion,cream,gel,mask','5.0–7.0(约pH 6附近最稳)','1)与低pH的直接酸体系(高浓度果酸、水杨酸、乙基VC)同锅长时间共存,会水解生成烟酸,带来潮红、刺痛反馈与鱼腥/氨样气味,这是最常见的翻车形式。2)与纯L-抗坏血酸同体系,在低pH加高温条件下容易泛黄,常规做法是两者不同锅、或降温后再加、或明确让出pH。3)与铜盐类原料(如蓝铜肽体系)会发生络合,体系变色且两边活性互相干扰,应视为直接冲突。4)与单宁、多酚含量高的草本提取物(白柳皮、绿茶、五倍子、栗子壳)在酸性条件下叠加,尤其在有铁离子时,货架期颜色会逐步加深至黄褐。5)与酸性防腐体系(苯甲酸、山梨酸类)搭配时,为了保证防腐效力压低pH,会同时把烟酰胺推入水解区间,两者需要一起权衡而不是分开定。','干粉状态非常稳定,常温密封可长期保存。水溶液在pH 5–7、常温下稳定;pH低于4或高于8显著加速水解为烟酸,长时间在70–80℃以上保温同样加速。对光不敏感,但与铁、铜等金属离子共存时,颜色会随时间加深,所以螯合剂是配套项。另一个容易被忽略的变量是原料本身:不同批次COA上的烟酸杂质含量差别很大,杂质高的批次成品放置后更容易出现气味与刺痛投诉,配方没改却出问题时先查进料。稳定性方案应同时监测pH、颜色与气味三项,不能只测含量。','在中国属于常规使用的化妆品原料,按产品的普通/特殊分类走对应备案或注册路径,涉及功效宣称需另备符合要求的评价资料;以最新官方文本为准。','欧盟市场常规使用,需在安全评估文件中纳入原料纯度与杂质信息(尤其烟酸残留);以最新官方文本为准。','美国市场作为普通化妆品成分常规使用,宣称措辞不得越过化妆品与药品的边界;以最新官方文本为准。','日韩及东南亚主要市场常规使用,各市场对功效表述的接受度差异较大,须逐一复核;以最新官方文本为准。','合成来源,与动物源无关,通常可做vegan;清真需供应商出具证明。','low','1)归水相,优先在冷却阶段加入(建议45℃以下)。若必须随水相加热溶解,控制在60℃以内并尽量缩短保温时间。2)室温水中溶解度很高,不需要助溶剂,常规搅拌5–10分钟即溶,不要为了溶得快而提温。3)与酸性活性共配时,先把体系pH调到5.0以上再加烟酰胺,不要在低pH状态下长时间热搅;调pH时缓慢滴加,避免局部酸区。4)必配螯合剂(EDTA二钠或植酸类),并使用去离子水,防止金属离子致黄。5)进料环节盯COA上的烟酸杂质项,建立进厂验收标准。6)放大生产最大的坑是降温曲线:大锅从80℃降到40℃所需时间远长于小样,烟酰胺在高温段的实际停留时间可能是小样的数倍,"小样不臭、大样有味"多半出在这里,中试时必须按实际降温曲线复核而不是照抄小样工艺。','barrier-repair','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('panthenol','Panthenol','泛醇','泛醇,D-泛醇,右旋泛醇,维生素原B5,前维生素B5,Dexpanthenol,Provitamin B5','81-13-0(D-泛醇);DL-泛醇为16485-10-2','维生素及衍生物','hydrating,soothing,barrier,repair,conditioning','泛酸的醇类似物,进入皮肤后可转化为泛酸,参与辅酶A相关的代谢路径,同时分子本身吸湿性强,可在角质层提供保湿。是草本舒缓类配方近乎默认的搭档,肤感不留负担、与绝大多数体系相容,所以配方师习惯性加它。它在配方里最需要盯的不是相容性,而是保质期内的pH走向:一旦水解,pH会继续下移并进一步加速水解。','0.5–5%(公开配方学常见区间,非法规限值),常用1–2%;注意液体规格多为75%水溶液,按纯度折算投料','serum,essence,toner,lotion,cream,gel,mask,foam','4.5–7.0(约5.5–6.5最稳)','1)强酸(pH低于4)与强碱(pH高于8)两端都会使其水解成泛酸及其盐,不是变质而是缓慢失效,同时体系会发酸、pH持续下移,形成自加速的恶性循环。与高浓度果酸、直接酸类体系同配是最典型的翻车场景。2)与富含有机酸的草本提取物、水果提取物或发酵滤液共配时,这些原料本身会把体系pH拉到5以下,配方师往往只看了活性物却没看pH的实际落点。3)酸性、高温、长时间三者叠加时水解最快,单看任一项都可能判为安全。4)75%水溶液规格粘稠且吸湿,直接投入无水油相或高油相体系会分层挂壁,必须先在水相中稀释。5)与阴离子表活体系、阳离子调理剂本身均相容,不是配伍禁忌区。','常温、pH 5–7条件下稳定,对光和氧都不敏感,真正的杀手是pH漂移与储存温度。加速试验中若体系pH低于4.5,通常在40℃放置数周即可观察到pH进一步下降和轻微的酸样气味,这是水解产物泛酸造成的,含量检测会同步走低。液体原料本身吸湿性强,开桶后未密封会吸潮变稀、影响实际投料浓度,并可能滋生微生物,应记录开桶日期并尽快用完。稳定性计划里必须逐月记录pH,这在保质期争议时是唯一能自证工艺没问题的数据。','在中国属于常规使用的化妆品原料,按产品分类走对应备案或注册路径;以最新官方文本为准。','欧盟市场常规使用,安全评估中注明规格(D型或DL型)与浓度;以最新官方文本为准。','美国市场作为普通化妆品成分常规使用,宣称措辞需避免疗效表述;以最新官方文本为准。','日韩及东南亚主要市场常规使用,各市场对舒缓类表述的口径不同,须逐一复核;以最新官方文本为准。','合成来源,与动物源无关,通常可做vegan;清真需供应商出具证明,并确认液体规格的稀释介质。','mid','1)水相原料,冷却阶段加入(建议40–50℃以下),不要在加热保温段投料。2)液体规格粘度高,称量时挂壁损耗大,必须用少量配方水冲洗称量容器一并投入,否则实际投料低于配方值;这个偏差在放大生产时被等比例放大,直接影响标示含量。3)粉体规格溶解偏慢,先用部分配方水预溶清亮再并锅,不要直接撒入主锅形成结团。4)与烟酰胺、甘油、氨基酸类保湿剂可在同一水相预溶,无冲突。5)最终pH定在5.0–6.5之间,并把pH纳入留样监测项,每月记录一次。6)如果配方里同时有酸性活性,先算清楚加完所有原料后的实际pH落点再定泛醇添加量,不要按理想值排配方。','soothing','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('ceramide-np','Ceramide NP','神经酰胺NP','神经酰胺3,神经酰胺III,N-硬脂酰基植物鞘氨醇,Ceramide 3,Ceramide NP','100403-19-8(待与供应商COA核对;不同酰基碳链规格登记号不同)','脂质(神经酰胺)','barrier,repair,hydrating','皮肤角质层细胞间脂质的主要结构类型之一,在配方中作为屏障类脂质补充使用,常与胆固醇、脂肪酸组成类皮脂的脂质配伍。添加量通常在千分之几的量级,对成品性状影响很小,但溶解难度在整个原料库里排前列。这条原料的全部工程难点都在物理形态:能不能真正溶开、以及冷却后会不会重新析出。','0.05–0.5%(公开配方学常见区间,非法规限值),常见0.1%上下','cream,lotion,balm,essence,serum(需增溶或脂质体规格)','4.0–8.0(自身对pH不敏感,实际由体系决定)','1)与纯水相体系基本不相容,直接投入水剂或精华会析出白点、白絮,过滤也去不干净,这是最常见的返工原因。2)与丙二醇、丁二醇、甘油等多元醇单独共热并不能真正溶解,热态看着清、冷却后重结晶。3)与高浓度乙醇体系同样是热态假澄清,降温或低温运输时结晶析出。4)与全部由非极性成分组成的油相(高纯硅油、异十六烷、轻质酯)相容性差,需要有一定极性的油脂、多元醇酯,或胆固醇加脂肪酸的共熔体系带它。5)与乳化能力弱、单一乳化剂的体系搭配时,冷却后会从乳液中泛出,表现为膏体发粗、涂抹有颗粒感。','分子本身对光、氧、pH都相当稳定,不易氧化变色,因此它的失效形式几乎全是物理性的。熔点高(通常在90℃以上),冷却过程中一定会经历再结晶,成品有没有白点取决于降温速率与共存脂质体系,而不是储存条件。最能暴露问题的测试是低温循环(5℃与室温之间往返)与冻融,应至少做三轮以上再判定;只做45℃高温加速试验完全测不出这条原料的真实风险。已经析出的结晶回温后通常不会自行溶回,属于不可逆缺陷。','在中国按常规化妆品原料使用,注意所采购规格的INCI名与目录收录名称需逐字核对;以最新官方文本为准。','欧盟市场常规使用,安全评估中注明来源(合成或发酵)与纯度;以最新官方文本为准。','美国市场作为普通化妆品成分常规使用,屏障类宣称需控制在化妆品范畴内;以最新官方文本为准。','日韩市场使用普遍,东南亚部分市场需确认原料来源声明,须逐一复核;以最新官方文本为准。','当前主流为合成或发酵来源,可做vegan,但必须取得供应商关于非动物来源的书面确认(历史上存在动物来源规格);清真需供应商出具证明。','high','1)绝不直接投料。三条可行路线:一是与胆固醇、硬脂酸等按类皮脂比例做成脂质预混,与乳化剂在油相共熔;二是采购已增溶的液体规格或预分散体,浓度低但省工艺;三是走脂质体或多层乳液的外包工艺。2)油相共熔通常需要升到80–90℃并保温至肉眼完全澄清、无任何颗粒后才能乳化,温度不足是白点的第一来源。3)乳化后降温不要过快,也不要在40℃以下长时间静置不搅,给脂质均匀分散的时间。4)放大生产的坑:小样在烧杯里90℃很容易全溶,几百公斤的乳化锅内部温差大,靠近罐壁先冷的区域会先结晶。必须看锅内实测温度而不是夹套温度,并相应延长保温时间。5)添加量极低,直接称量的相对误差很大,建议先做1:10或1:100的脂质母液再投,不要在500公斤锅里直接称几十克。6)成品放行检验必须加一项低温循环后的目视白点检查,不能只做高温加速。','barrier-repair','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('allantoin','Allantoin','尿囊素','尿囊素,脲基海因,5-脲基乙内酰脲,Allantoin,天然存在于聚合草 Symphytum officinale','97-59-6','小分子有机物','soothing,repair,hydrating,conditioning','结构简单的小分子,常用于舒缓与角质调理方向,肤感中性、几乎不影响体系,加上价格极低,是各类草本配方的常规配角。它的技术难点不在化学而在溶解度:室温水中的溶解上限很低,配方师按"多加一点更好"的思路提量,货架期就会以针状结晶的形式还回来。','0.1–0.5%(公开配方学常见区间,非法规限值);室温水中溶解度约0.5%左右,超过这一量级必须配增溶方案','cream,lotion,gel,toner,essence,mask,foam','4.0–8.0(4–7区间最稳,强碱下会水解)','1)与高电解质体系(高盐、氯化钠增稠的表活配方)共存时溶解度进一步下降,析晶风险显著上升。2)与高乙醇体系搭配时,乙醇并不助溶,反而降低其在水中的溶解度,货架期析出针状结晶。3)与尿素、氨基酸类等高浓度水溶性保湿剂叠加,体系总溶质浓度上去,低温时更容易过饱和。4)在pH高于9的强碱体系(如部分皂基)中长期存放会水解失效。5)与深色多酚类草本提取物本身不发生化学反应,但析出的结晶会把提取物颜色裹进去,外观上表现为"有色小颗粒",客户往往误判为微生物污染或原料变质。','化学性质很稳定:耐热、可随水相加热溶解,不见光变色、不易氧化,含量在货架期内基本不掉。它的失效形式几乎全是物理性的——热态溶清,降温或低温储运时过饱和析出针状晶体,外观上像"长毛"或碎玻璃渣,是消费者投诉率很高的外观缺陷。25℃水中溶解度约0.5%,温度每下降10℃溶解度明显下降,因此冬季运输、冷库暂存、北方仓储都是高发场景。判定必须用低温循环(5℃放置48小时以上再回温观察),常规45℃加速试验对这条原料完全无效。','在中国属于常规使用的化妆品原料,按产品分类走对应备案或注册路径;以最新官方文本为准。','欧盟市场常规使用,安全评估中注明来源与纯度;以最新官方文本为准。','美国市场作为普通化妆品成分常规使用;部分用途下的表述需由法规复核,以最新官方文本为准。','日韩及东南亚主要市场常规使用,须按目标市场规则复核;以最新官方文本为准。','化妆品级多为合成来源,通常可做vegan,但起始物料需供应商书面确认;清真需供应商出具证明。','low','1)用量守住0.5%以内。想在文案上写更高浓度就必须换方案(多元醇预溶,或改用其它可溶规格),不要靠"多搅一会儿"硬溶。2)水相加热到60–70℃溶解,搅拌到完全澄清、无未溶颗粒为止;残留的未溶颗粒会成为后期结晶的晶种,是最隐蔽的返工原因。3)建议单独做预溶母液:取部分配方水加热溶清后过筛网,再并入主锅。4)冷却过程避免局部急冷,夹套直接通冰水会让贴壁区先结晶,而且结晶不再回溶。5)放大生产的坑是锅底与搅拌死角沉底未溶,小样几分钟溶清并不代表大锅同样溶清;打料前从锅底取样确认无颗粒。6)成品放行前做一次低温循环观察,这一项能挡掉这条原料绝大部分的返工。','soothing','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('ascorbyl-glucoside','Ascorbyl Glucoside','抗坏血酸葡糖苷','抗坏血酸葡糖苷,维C葡糖苷,AA2G,2-O-α-D-吡喃葡萄糖基-L-抗坏血酸,Ascorbyl Glucoside','129499-78-1','维生素及衍生物','brightening,antioxidant','抗坏血酸2位羟基被葡萄糖基化的衍生物,糖苷键把易被氧化的烯二醇结构保护起来,因此在配方中比游离维C耐氧化得多,常用于肤色均匀度与抗氧化方向。它需要经皮肤上的糖苷酶水解释放抗坏血酸,起效路径与游离维C不同。配方端真正要解决的问题不是"能不能加",而是到货架期末还留得住多少、以及颜色能否被品牌方接受。','1–2%(公开配方学常见区间,非法规限值);多数体系做到2%已接近水溶与稳定性的现实边界','serum,essence,toner,lotion,cream,mask','5.0–7.0(偏中性更稳,强酸与强碱都加速分解)','1)铁、铜等过渡金属离子会显著加速泛黄,来源包括生产用水、色浆、金属工具与包材金属件,以及某些植物提取物自带的金属残留,螯合剂是必配项而非可选项。2)与高浓度草本多酚(绿茶、白柳皮、五倍子、栗子壳、迷迭香提取物)叠加时,双方的氧化产物互相催化,变色速度比单用任何一方都快;"加点植提显得更天然"是这条原料最常见的翻车动机。3)与pH高于7.5的碱性体系或含游离氨基的碱剂长期共存,降解与颜色加深同步加快。4)与含还原糖的高糖发酵滤液共存,在高温下存在美拉德样褐变风险。5)与含糖苷酶活性的酶解类原料同配,理论上会在瓶子里提前把它水解掉,等于白花钱买了衍生物。6)与乙基VC等酸性维C衍生物同配时最佳pH不在一处,硬凑的结果是两边都不稳。','比L-抗坏血酸稳定得多,但绝不是不变色。典型轨迹是无色转浅黄再转琥珀色,速度由pH、金属离子、温度、氧含量四项共同决定,pH越高、金属越多、温度越高越快。见光加速,应优先使用避光包材。加速试验只做45℃一个月往往低估问题,应同时安排室温6个月留样和实际包材在货架灯光下的暴露对照,并在打样阶段就与品牌方确认"可接受的最深颜色",做成色板留档——多数纠纷不是含量不合格,而是颜色没有事先约定。','在中国按常规化妆品原料使用,涉及功效宣称需另备符合要求的评价资料;以最新官方文本为准。','欧盟市场常规使用,安全评估中注明浓度与体系pH;以最新官方文本为准。','美国市场作为普通化妆品成分常规使用,宣称需控制在化妆品范畴内;以最新官方文本为准。','日韩及东南亚主要市场使用普遍,各市场对肤色相关表述的口径差异较大,须逐一复核;以最新官方文本为准。','合成或酶法来源,通常可做vegan(酶法需确认所用酶的来源);清真需供应商出具证明。','mid','1)水相原料,冷却阶段加入(建议45℃以下),不要跟着水相走全程热历程。2)溶解速度偏慢且粉末易结团,先用部分配方水单独预溶至清亮再并锅,结团处会形成局部高浓度并拖长溶解时间。3)必配螯合剂(EDTA二钠或植酸、葡糖酸钠类),并使用去离子水;生产用水的金属残留是批间色差最常见的隐藏变量。4)体系pH建议控制在5.5–6.5;若必须与酸性活性同配,先决定谁让步并把决定写进工艺文件。5)尽量减少搅拌带入的空气,乳化后避免高速空搅,有条件在灌装前做惰性气体顶空。6)包材优先不透明或深色、阻氧性好的材质,避免透明PET直接在白光货架陈列。7)放大生产的坑:大锅的溶氧与顶空空气总量比小样多,同一配方大样更容易早期泛黄,先做一次中试留样再定量产工艺,不要用小样数据直接放行。','brightening','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('3-o-ethyl-ascorbic-acid','3-O-Ethyl Ascorbic Acid','3-邻乙基抗坏血酸','乙基VC,VC乙基醚,3-O-乙基抗坏血酸,3-邻乙基抗坏血酸,Ethyl Ascorbic Acid','86404-04-8','维生素及衍生物','brightening,antioxidant','抗坏血酸3位羟基被乙基醚化的衍生物,兼具一定水溶性与亲脂性,在配方中比游离维C耐氧,进入皮肤后可脱去乙基释放抗坏血酸,常用于肤色均匀度方向。客户点名率很高,但它仍保留部分还原性,对金属离子和氧依然敏感,不能当成"稳定型、随便加"的原料来排配方。','0.5–2%(公开配方学常见区间,非法规限值)','serum,essence,toner,lotion,cream,gel','4.0–6.0(常见做到5.0–5.5)','1)铁、铜离子是头号问题,极低浓度即可引起明显黄变甚至粉变,来源包括生产用水、植物提取物、色粉、锅体与工具磨损的铁屑、以及泵头里的金属弹簧。2)与烟酰胺同配存在pH冲突:乙基VC偏好pH 5以下,烟酰胺希望5以上,折中做到5.0–5.5并严格控制热历程,避免在低pH高温下长时间共处。3)与单宁、多酚含量高的草本提取物(白柳皮、绿茶、五倍子、栗子壳)叠加时,变色速度显著加快且颜色偏深。4)与三乙醇胺等胺类碱剂体系相容性差,易变色。5)在低pH条件下,部分丙烯酸类增稠剂的增稠力大幅下降甚至完全失效,配方会"越放越稀",必须选耐酸耐电解质的流变剂。6)与过氧化物、氧化型染发体系直接冲突。','干粉稳定,水溶液的稳定性由pH、金属、氧、光四项共同决定。pH 4–5.5明显更稳,高于6后降解与变色同步加快。见光加速,透明包材加货架灯是最常见的变色场景。颜色从无色转黄再转橙褐是典型的降解轨迹,可作为半定量的老化指示,但不能替代含量检测。稳定化方案基本是固定四件套:螯合剂、低pH、避光阻氧包材、控制生产溶氧,缺任何一项都会在6–12个月留样上看出差别。','在中国按常规化妆品原料使用,涉及功效宣称需另备符合要求的评价资料;以最新官方文本为准。','欧盟市场需在安全评估中纳入该原料的浓度、纯度与体系pH信息;以最新官方文本为准。','美国市场作为普通化妆品成分常规使用,宣称需控制在化妆品范畴内;以最新官方文本为准。','日韩及东南亚主要市场使用普遍,各市场对肤色相关表述口径不同,须逐一复核;以最新官方文本为准。','合成来源,与动物源无关,通常可做vegan;清真需供应商出具证明。','mid','1)冷却阶段加入,建议40℃以下;在高温段投料等于替客户提前消耗有效物。2)螯合剂按常规量必加,并全程使用去离子水,金属离子控制是这条原料的生命线。3)锅体与管路优先使用状态良好的316L不锈钢,禁止铁质工具、破损搪瓷器皿;取样勺、过滤网、刮板都算在内。4)先用部分配方水做预溶至完全澄清,再调pH,再并入主体;调pH时缓慢滴加,避免出现局部碱性区域造成的局部变色。5)尽量减少空气卷入,搅拌后静置脱气,有条件在灌装线做氮气顶空。6)包材必须做相容性试验,重点看避光性、阻氧性,以及带金属弹簧的泵头接触区域有没有变色;这一项常被跳过,却是上市后变色投诉的高发来源。7)放大生产的坑:中试到量产变色加剧,通常来自更长的管路停留时间、更高的溶氧和更差的水质,不要一上来就怀疑原料批次。','brightening','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('bakuchiol','Bakuchiol','补骨脂酚','把该项整段删掉,替换为真正的区分提示。aliases 改为:「补骨脂酚,Bakuchiol,来源补骨脂 Psoralea corylifolia(异名 Cullen corylifolium);注意与补骨脂素(psoralen)及呋喃香豆素类为完全不同的化合物,后者在多个市场受限或禁用,不可混称混采」','10309-37-2','多酚(萜酚类)','antioxidant,anti-aging','来自补骨脂的萜酚类单体,油溶性,分子中含酚羟基,配方中常用于抗氧化与抗老方向。近年被大量作为视黄醇的替代方向来宣传,但它与视黄醇的化学结构完全不同,不能把视黄醇的机理与宣称直接搬过来。这条原料的主要风险不在配方端,而在文案端:比较性与等效性表述是被挑战最多的地方,配方定稿前就应该让法规同事介入。','0.5–1%(公开配方学常见区间,非法规限值);多数体系不超过1%','serum,oil,cream,lotion,balm,essence','4.0–8.0(自身不由pH主导,实际由体系决定)','1)与过氧化苯甲酰等强氧化性组分直接冲突,会氧化变深。2)油溶性使它在澄清水基体系中很难做,强行增溶需要大量表活,会带来肤感变化与澄清度的长期不稳定。3)原料本身多为淡黄到黄棕色的粘稠油,添加0.5–1%已足以把白色乳霜带成米黄,浅色与白色体系必须先算颜色账。4)气味明显(木质带坚果与辛感),与清爽花香型香精容易打架,必须在打样阶段就做香精遮盖测试,不能等成品出来再补香。5)与未加抗氧化保护的高不饱和植物油相共存时,油相一旦酸败会连带它一起变味变色。6)在高pH皂基类体系中,酚羟基更易氧化,颜色加深更快。','主要风险是光照与氧化:长期光照下颜色加深、气味发生变化,高温加速。相对视黄醇而言它耐受度高得多,常规乳化温度(75–80℃)可以承受,但没有必要让它经历高温段。配方内应搭配抗氧化剂(如生育酚)与螯合剂,并使用避光包材。稳定性评估除了含量之外,必须单独跟踪颜色与气味两条曲线——实际投诉中,气味变化往往先于含量不合格出现,而颜色变化会被误判为产品变质。纯品在低温下会变稠甚至半凝,这是物理现象不是变质,但会影响冬季称量。','使用前需确认该原料在中国的收录情况与使用要求,宣称不得涉及药品或医疗器械相关表述;以最新官方文本为准。','欧盟市场需在安全评估中纳入原料来源与纯度信息,并避免与视黄醇作等效性比较的宣称;以最新官方文本为准。','美国市场作为化妆品成分使用,与视黄醇的比较性宣称容易引发监管关注与同业挑战,须由法规复核后定稿;以最新官方文本为准。','各市场对"替代视黄醇"类表述的容忍度差异很大,须逐一复核;以最新官方文本为准。','植物来源,通常可做vegan;若采购稀释规格需确认载体油同为植物来源;清真需供应商出具证明。','high','1)油相原料,建议在冷却阶段(50–60℃以下)加入,不需要随油相长时间高温保温。2)常见规格分纯品(粘稠油,冬季变稠)与稀释液(溶于辛酸/癸酸甘油三酯等)。纯品冬季需40–50℃温水浴化开后称量,不要直接高温加热。3)纯品挂壁损耗大,称量后用配方内的酯油冲洗容器一并投入,否则实际添加量低于标示值。4)与香精一起在冷却阶段加入,先在小样阶段完成气味与颜色评估,并把可接受的颜色做成色板留档。5)采购要盯清楚纯度规格(常见98%、99%与各类稀释规格,价差很大),并且严格区分"补骨脂酚单体"与"补骨脂提取物"——后者成分复杂、安全评估与宣称路径完全不同,报价单上没写清楚的不要比价。6)配方立项时就把文案边界一起定下来,尤其是任何"替代""等效""温和版"的说法,这条原料的返工多数发生在文案而不是配方。','antioxidant','中');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('salicylic-acid','Salicylic Acid','水杨酸','水杨酸,2-羟基苯甲酸,邻羟基苯甲酸,BHA,β-羟基酸,Salicylic Acid','69-72-7','多酚(酚酸类)','exfoliating,oil-control,cleansing','脂溶性的β-羟基酸,能进入含油脂的毛孔环境,常用于角质更新与油光管理方向。它在配方中的行为高度依赖pH:只有在游离酸形式占比足够高时才有实际意义,pH抬到4.5以上大部分转为水杨酸盐,肤感更温和但方向也随之改变。需要特别说明的是,它与白柳皮提取物不是同一件事,后者主要含水杨苷,含量口径与转化路径都不同,不能互相替代或按水杨酸折算。','0.2–2%(公开配方学常见区间,非法规限值;各市场对适用产品类型、使用条件与标注的规定不同,必须逐一复核后再定量)','toner,serum,gel,lotion,cream,foam,essence,mask','3.0–4.0(常见做到3.5左右)','1)室温水中溶解度很低(约0.2%量级),不做助溶直接投料必然析晶,这是最基础也最常犯的错误。2)与铁离子显色是经典现象,微量铁即产生紫色至深紫色,来源包括铁质工具、破损设备内衬、某些色粉与硬水;显色不可逆,常被误判为原料变质。3)与阳离子表面活性剂、阳离子调理聚合物在酸性条件下容易形成沉淀或絮凝。4)与氢氧化钠过量、三乙醇胺或偏碱性的植物提取物混合会成盐并把pH拉高,方向随之改变,而含量检测仍然合格,很容易被误读。5)在pH 3–4条件下,多数丙烯酸类增稠剂增稠力大幅下降甚至完全不增稠,必须选耐酸型流变剂。6)与烟酰胺同体系时存在pH冲突,且低pH加高温会加速烟酰胺水解产生气味,两者同配要么各让一步要么分开做。7)与白柳皮提取物同处一支产品时,内部与客户极易混淆两者的功能与计量口径,标签与说明必须写清楚。','分子本身相当稳定:耐热、耐氧、不易见光分解,含量在货架期内通常没有问题。风险集中在物理析晶与显色两件事上。热态溶清、降温后过饱和析出是常态,冬季运输与低温仓储是高发场景;pH漂移会改变游离酸与盐的比例,进而改变实际表现,因此保质期内必须监测pH而不只是含量。遇铁显色属于化学显色而非降解,颜色一旦出现不可逆,只能靠工艺预防。','中国对水杨酸的使用范围与使用条件有专门规定,添加量、适用产品类型与标注要求须逐条复核后再定配方;以最新官方文本为准。','欧盟对水杨酸按用途区分使用条件并有相应标注要求,不同产品类型的要求不同,须逐项确认;以最新官方文本为准。','在美国用于特定用途时可能落入OTC专论路径,与作为一般化妆品成分使用的要求不同,必须先确定产品定位再定配方;以最新官方文本为准。','日韩及东南亚各市场对水杨酸的使用条件与标注要求不一致,须逐一复核;以最新官方文本为准。','以合成来源为主(亦有天然来源规格),通常可做vegan;清真需供应商出具证明,并确认助溶体系是否含乙醇。','low','1)必须助溶:常见做法是用乙醇、丙二醇/丁二醇,或非离子增溶剂预溶成澄清母液再并入水相,不要指望在主锅里靠加热搅拌溶开。2)预溶温度控制在60–70℃以内,溶清后随主体一起平缓降温,避免局部急冷造成贴壁析晶。3)全线禁铁:锅体、搅拌桨、取样勺、过滤网、灌装管路都要确认没有裸露铁件;必须用去离子水并配螯合剂。4)pH调整放在最后一步,分次滴加,记录调节前后的pH与测量温度(pH随温度变化,统一在25℃测,不同温度下测出来的数据不能互比)。5)成品放行前做低温循环(5℃放置48小时以上)与常温长期留样双轨观察析晶,只做高温加速无效。6)包材相容性必须做,尤其含乙醇助溶体系对某些塑料件与外部印刷层的影响。7)工艺文件里把"目标市场"写在配方第一行:各市场使用条件不同,先做配方后补合规是这条原料最贵的返工。','exfoliating','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('tocopherol','Tocopherol','生育酚','生育酚,维生素E,dl-α-生育酚,d-α-生育酚,混合生育酚,Vitamin E','59-02-9(d-α-生育酚);dl-α-生育酚为10191-41-0','维生素及衍生物','antioxidant,conditioning','油溶性酚类抗氧化剂,通过提供氢原子中断油脂的自由基链式氧化,在草本油相配方里的首要作用是保护不饱和油脂与其它易氧化组分不快速哈败。它保护的是配方本身的品质,与对皮肤的作用是两件事,写文案时不要混着说。用量与加入时机都有讲究:加多了会转为促氧化,加早了会在加热阶段先被消耗掉。','0.05–0.5%(公开配方学常见区间,非法规限值);作为油相抗氧化保护常用0.05–0.2%,提高用量不等于保护更好','oil,cream,lotion,balm,serum,stick','4.0–8.0(自身不由pH主导,实际由体系决定)','1)最反直觉的一条:用量过高会反转为促氧化。超过一定浓度后生育酚自由基来不及被再生,反而参与自由基传递,油相酸败更快、颜色更深。经验做法是控制在0.2%以内,并搭配可再生它的体系(如抗坏血酸棕榈酸酯配螯合剂,或迷迭香提取物)。2)自身带色:天然混合生育酚为黄至红棕色粘稠液,0.5%就足以把白色乳霜带成明显米黄或浅棕,浅色体系要提前算账。3)与金属离子共存时抗氧化效率明显下降,螯合剂是配套项而非可选项。4)与过氧化物类强氧化剂直接冲突。5)在高pH皂基体系中,酚羟基更易氧化,颜色加深加快。6)它只待在油相,对水相里的变色问题(如维C衍生物泛黄)完全无能为力——"加点维E防变色"是常见误用。7)大豆或葵花来源规格涉及过敏原与非转基因声明,与vegan、清真宣称一起需要向供应商索证。','它本身就是容易被氧化的分子,这正是它的工作方式。开桶后接触空气会逐渐变深变稠,原料颜色深浅可作为氧化程度的粗略判断。见光、遇热、遇金属都加速,储存需密封避光阴凉,开桶后记录日期并尽快用完。在成品中它随时间被消耗,所以"加速试验没哈败"不等于"货架期不会哈败";高不饱和油脂配方应使用过氧化值一类指标跟踪,而不是只靠闻味,等闻得出来时通常已经过了可挽回的阶段。','在中国属于常规使用的化妆品原料,注意来源(大豆、葵花、棕榈等)与过敏原、非转基因等声明需向供应商索证;以最新官方文本为准。','欧盟市场常规使用,安全评估中注明规格与来源,过敏原相关信息需可追溯;以最新官方文本为准。','美国市场作为普通化妆品成分常规使用,涉及来源与过敏原的标注需按目标市场规则确认;以最新官方文本为准。','日韩及东南亚主要市场常规使用,部分市场对原料来源声明要求较严,须逐一复核;以最新官方文本为准。','多为植物来源(大豆、葵花、棕榈),通常可做vegan;需确认稀释载体油同为植物来源;清真需供应商出具证明。','mid','1)油相加入,建议在冷却阶段(60–70℃以下)投料,不要在80℃以上长时间保温,那等于让它先替你消耗掉一部分。2)原料粘稠,称量挂壁明显,用配方内的油冲洗容器一并投入。3)与螯合剂配合使用:螯合剂在水相、生育酚在油相,抗氧化保护要两边都有,单边布置效果有限。4)若配方含玫瑰果油、月见草油、亚麻籽油等高不饱和油脂,抗氧化体系必须在油相进锅时就到位,不能等最后再补——氧化在加热阶段就已经开始。5)采购规格必须看清:合成dl-α-生育酚、天然d-α-生育酚、混合生育酚(含β/γ/δ)三类在颜色、气味、抗氧化表现和价格上都不同,换规格等于换配方,必须重做稳定性。6)生育酚乙酸酯(Tocopheryl Acetate)不是它:乙酸酯在配方体系里几乎没有抗氧化功能,采购与配方在这里买错、用错的频率非常高,下单前逐字核对INCI。','antioxidant','高');
INSERT OR REPLACE INTO ingredients (slug,inci,name_zh,aliases,cas,family,functions,mechanism_zh,use_level,formats,ph_range,incompatible,stability,market_cn,market_eu,market_us,market_apac,halal_vegan,cost_band,factory_note,claim_tag,confidence) VALUES ('asiaticoside','Asiaticoside','积雪草苷','积雪草苷,亚洲苷,羟基积雪草苷(为另一成分,勿混),Asiaticoside,来源积雪草 Centella asiatica','16830-15-2','植物提取物(三萜皂苷单体)','soothing,repair,barrier','积雪草中的三萜皂苷单体,常用于舒缓与屏障修护方向,是草本线里客户认知度最高的成分之一。它与"积雪草提取物"是两种规格、两个价位:提取物是多成分混合、含量按总苷或提取比计;积雪草苷是纯化单体,含量按纯度计,两者单价可以差一个数量级。采购最容易在这里比错价,报价前必须先统一含量口径。','0.05–0.5%(公开配方学常见区间,非法规限值);单体规格常用0.1%上下','serum,essence,cream,lotion,gel,mask','4.5–7.0(强酸强碱下糖苷键易水解)','1)在pH低于4的酸性体系或碱性体系中长期共存,糖苷键会水解生成苷元(亚洲酸),溶解度更差并可能析出,而水解初期外观完全正常,极具欺骗性。2)水中溶解度低,直接投入水相会留下不溶颗粒;与高电解质体系共存溶解度进一步下降。3)皂苷结构本身有表面活性,浓度较高时在搅拌与灌装环节会起泡,并可能轻微干扰乳化体系的界面平衡——高剪切乳化后出现说不清原因的粘度下降,可以往这里怀疑。4)与阳离子表活或阳离子调理聚合物可能形成络合物,表现为浑浊或沉淀。5)与高浓度乙醇体系相容性尚可,但低温析出风险必须单独验证,不能默认按水基体系的结论走。','干粉状态稳定,避光密封常温可长期保存。溶液状态的主要风险是pH引起的糖苷键水解与低温析出。高温长时间加热(80℃以上保温)会加速降解,乳化时不应让它跟随全程热历程。对光相对不敏感,但含它的配方通常同时含易氧化的多酚类植提,整体仍建议避光包材。稳定性判定必须同时看含量(HPLC)与外观:水解初期溶液可能依旧澄清透明,只看清亮度会得出"稳定"的错误结论,这是这条原料最容易被放过的隐性失效。','在中国按常规化妆品原料使用,注意所购规格的INCI名与目录收录名称需逐字核对;以最新官方文本为准。','欧盟市场常规使用,安全评估中注明来源、纯度与提取溶剂残留信息;以最新官方文本为准。','美国市场作为普通化妆品成分常规使用,舒缓与修护类宣称需控制在化妆品范畴内;以最新官方文本为准。','日韩及东南亚市场使用普遍,各市场对植物来源成分的申报资料要求不同,须逐一复核;以最新官方文本为准。','植物来源,通常可做vegan;需确认提取溶剂与稀释载体同样无动物源;清真需供应商出具证明。','high','1)溶解方案必须在工艺单里写死,三条常见路线:一是丙二醇、丁二醇或1,3-丙二醇预溶(需加温50–60℃并充分搅拌);二是少量乙醇预溶后并入水相(需评估最终乙醇残留与肤感);三是用非离子增溶剂(聚山梨酯类、氢化蓖麻油类)做增溶体系。直接投水相是最常见的错误。2)预溶母液做好后过滤,确认澄清无颗粒再并锅。3)冷却阶段加入(建议45–50℃以下),不要在高温保温段投料。4)体系pH控制在4.5–7.0,并把pH纳入留样监测项。5)皂苷会起泡:预溶与并锅时降低搅拌转速,乳化后留足消泡时间再灌装,否则装量不准且瓶内可见气泡。6)采购环节最容易出问题:必须要求COA标明纯度(如≥90%、≥95%)与检测方法(HPLC),并明确区分"积雪草苷单体""总苷类混合物""积雪草提取物"三种口径,报价单上没写口径的比价没有意义。7)放大生产的坑:小样在50毫升多元醇里几分钟就澄清,大批量预溶时局部浓度过高会结块且很难再溶开,应边加边搅、分批投入并延长溶解时间。','soothing','高');
